display.text:
/**
 * AR-001C: M9 Activity Room Types
 *
 * Consolidated from @vestara/types. These are the Activity Room's own
 * persistence, input, and query contracts. Previously lived in
 * @vestara/types as "Family B" / M9 contracts.
 *
 * Ownership: @vestara/activity-room
 */

import type {
  BindingId,
  Brand,
  ExecutionId,
  RepositoryBindingId,
  RequestId,
  RuntimeSessionId,
  TraceId,
  WorkflowRunId,
  WorkflowTaskId,
} from '@vestara/types';

// ─── Activity Record ID ─────────────────────────────────────

/** Unique identity for a durable Activity record. */
export type ActivityRecordId = Brand<string, 'ActivityRecordId'>;

// ─── Activity Types ─────────────────────────────────────────

/**
 * Canonical activity types. Extensible for future domains (browser, etc.)
 * but normalized to prevent provider/OpenCode-specific leakage.
 */
export type ActivityType =
  // Workflow lifecycle (consumed from M8 WorkflowEvents)
  | 'workflow.started'
  | 'workflow.completed'
  | 'workflow.failed'
  | 'workflow.cancelled'
  // Task lifecycle (consumed from M8 WorkflowEvents)
  | 'task.runnable'
  | 'task.started'
  | 'task.completed'
  | 'task.failed'
  | 'task.cancelled'
  // Agent lifecycle (normalized from agent harness)
  | 'agent.assigned'
  | 'agent.started'
  | 'agent.progress'
  | 'agent.waiting'
  | 'agent.completed'
  | 'agent.failed'
  | 'agent.cancelled'
  // Tool lifecycle (normalized from OpenCode runtime)
  | 'tool.called'
  | 'tool.succeeded'
  | 'tool.failed'
  // Human interaction
  | 'human.message'
  // System
  | 'system.event'
  // Interaction (AR-REC-C2)
  | 'interaction.presented'
  | 'interaction.responded';

/**
 * Source system that produced the event.
 * Normalized to Vestara concepts, not OpenCode internals.
 */
export type ActivitySource =
  | 'workflow-engine'
  | 'agent-harness'
  | 'human-input'
  | 'runtime-session'
  | 'system'
  | 'interaction-app';

/**
 * Visibility scope for an activity record.
 */
export type ActivityVisibility = 'all' | 'operators' | 'system';

// ─── Activity Record ────────────────────────────────────────

/**
 * Durable Activity record. Carries canonical M1/M2 lineage.
 * Never becomes an orchestration authority.
 *
 * Projection state (UI/API) is reconstructable from these records.
 */
export interface ActivityRecord {
  /** Unique identity for this durable record. */
  readonly activityId: ActivityRecordId;

  /** Idempotency key: canonical event identity. Deduplication anchor. */
  readonly eventId: string;

  /** Monotonic sequence number within the store. Ordering anchor. */
  readonly sequenceNumber: number;

  /** Canonical activity type. */
  readonly type: ActivityType;

  /** When the activity occurred (ISO 8601). */
  readonly timestamp: string;

  // ─── Canonical M1/M2 Lineage ────────────────────────────

  /** Canonical execution identity (M1). */
  readonly executionId?: ExecutionId;

  /** Distributed trace identifier (M1). */
  readonly traceId?: TraceId;

  /** Transport/request identity (M1). */
  readonly requestId?: RequestId;

  /** Workflow run identity (M8). */
  readonly workflowRunId?: WorkflowRunId;

  /** Workflow task identity (M8). */
  readonly taskId?: WorkflowTaskId;

  /** Agent assignment identity. */
  readonly agentAssignmentId?: string;

  /** Repository binding identity (M5). */
  readonly repositoryBindingId?: RepositoryBindingId;

  /** Runtime session binding identity (M7). */
  readonly runtimeSessionBindingId?: RuntimeSessionId;

  /** AI binding identity (M4). */
  readonly aiBindingId?: BindingId;

  // ─── Actor & Source ─────────────────────────────────────

  /** Who generated this activity. */
  readonly actor: import('@vestara/types').ActivityActor;

  /** Specific identity of the actor (agent ID, user ID, etc.) */
  readonly actorId?: string;

  /** Which system produced this event. */
  readonly source: ActivitySource;

  // ─── Content ────────────────────────────────────────────

  /** Normalized payload. Provider/OpenCode-specific details are stripped. */
  readonly payload: ActivityPayload;

  /** Who can see this record. */
  readonly visibility: ActivityVisibility;
}

/**
 * Normalized payload. Structured to avoid provider/OpenCode leakage.
 */
export interface ActivityPayload {
  /** Human-readable message. */
  readonly message?: string;

  /** Activity-specific structured data. */
  readonly data?: Readonly<Record<string, unknown>>;

  /** Error details (for failed activities). */
  readonly error?: {
    readonly message: string;
    readonly code?: string;
  };

  /** Output details (for completed activities). */
  readonly output?: string;

  /** Task dependency condition (for task.runnable). */
  readonly dependencyCondition?: 'completed' | 'any';
}

// ─── Activity Event (Input) ────────────────────────────────

/**
 * Canonical event that arrives at the Activity Store.
 * Can come from M8 WorkflowEvents, human messages, agent lifecycle, etc.
 * The store normalizes these into durable ActivityRecords.
 */
export interface ActivityEvent {
  /** Canonical event identity for deduplication. */
  readonly eventId: string;

  /** Activity type. */
  readonly type: ActivityType;

  /** When the event occurred. */
  readonly timestamp: string;

  // ─── Lineage (same fields as ActivityRecord) ────────────

  readonly executionId?: ExecutionId;
  readonly traceId?: TraceId;
  readonly requestId?: RequestId;
  readonly workflowRunId?: WorkflowRunId;
  readonly taskId?: WorkflowTaskId;
  readonly agentAssignmentId?: string;
  readonly repositoryBindingId?: RepositoryBindingId;
  readonly runtimeSessionBindingId?: RuntimeSessionId;
  readonly aiBindingId?: BindingId;

  // ─── Actor & Source ─────────────────────────────────────

  readonly actor: import('@vestara/types').ActivityActor;
  readonly actorId?: string;
  readonly source: ActivitySource;

  // ─── Content ────────────────────────────────────────────

  readonly payload: ActivityPayload;
  readonly visibility?: ActivityVisibility;
}

// ─── Query Surface ──────────────────────────────────────────

/**
 * Cursor for pagination and replay.
 * Event identity + sequence number, not timestamp alone.
 */
export interface ActivityCursor {
  /** Sequence number for cursor-based pagination. */
  readonly sequenceNumber: number;

  /** Event identity for deduplication verification. */
  readonly eventId: string;

  /** Timestamp for time-based filtering. */
  readonly timestamp: string;
}

/**
 * M9 Query filters for the Activity Store.
 * Supports M10/M11 data requirements without overbuilding.
 *
 * Note: This is the M9 query interface. The canonical ActivityQuery
 * (workflowId, sessionId, taskId, agentId, kind, severity, ...)
 * lives in store.ts and works with the 6-kind discriminated union.
 */
export interface M9ActivityQuery {
  /** Filter by workflow run. */
  readonly workflowRunId?: WorkflowRunId;

  /** Filter by execution identity. */
  readonly executionId?: ExecutionId;

  /** Filter by task identity. */
  readonly taskId?: WorkflowTaskId;

  /** Filter by actor type. */
  readonly actor?: import('@vestara/types').ActivityActorType;

  /** Filter by actor identity. */
  readonly actorId?: string;

  /** Filter by activity type. */
  readonly type?: ActivityType | ActivityType[];

  /** Filter by source system. */
  readonly source?: ActivitySource;

  /** Only records after this cursor (exclusive). */
  readonly after?: ActivityCursor;

  /** Only records before this timestamp. */
  readonly before?: string;

  /** Only records after this timestamp. */
  readonly afterTimestamp?: string;

  /** Maximum number of results. */
  readonly limit?: number;
}

// ─── Store Interface ────────────────────────────────────────

/**
 * M9 Durable Activity Store interface.
 * Idempotent ingestion: same eventId → exactly one ActivityRecord.
 * Deterministic ordering via sequenceNumber.
 *
 * Note: This is the M9 ingestion-oriented store. The canonical ActivityStore
 * (append/get/list/lastSequence) lives in store.ts and works with the
 * 6-kind discriminated union ActivityRecord.
 */
export interface M9ActivityStore {
  /**
   * Append a canonical event. Idempotent: same eventId returns existing record.
   * Returns the durable ActivityRecord with assigned sequenceNumber.
   */
  append(event: ActivityEvent): Promise<ActivityRecord>;

  /**
   * Query activities with filters. Returns results in deterministic order.
   */
  query(q: M9ActivityQuery): Promise<readonly ActivityRecord[]>;

  /**
   * Get activities after a cursor (exclusive). For pagination/replay.
   */
  getAfter(cursor: ActivityCursor): Promise<readonly ActivityRecord[]>;

  /**
   * Get a single record by event ID. For deduplication verification.
   */
  getByEventId(eventId: string): Promise<ActivityRecord | undefined>;

  /**
   * Replay a range of records. For rebuild/verification.
   */
  replay(from?: ActivityCursor, to?: ActivityCursor): Promise<readonly ActivityRecord[]>;

  /**
   * Rebuild projection from all durable facts. Returns all records in order.
   */
  rebuild(): Promise<readonly ActivityRecord[]>;

  /**
   * Get current cursor (last appended record). For reconnect/resume.
   */
  getCursor(): Promise<ActivityCursor | null>;

  /**
   * Get the last sequence number. For polling/recovery.
   */
  lastSequence(): Promise<number>;
}

/**
 * AR-001C: Activity Room Projection Types
 *
 * Read models for the Activity Room UI. Consolidated from @vestara/types.
 * Previously lived in @vestara/types as M10 projection contracts.
 *
 * Ownership: @vestara/activity-room
 */

import type {
  ActivityActor,
  ActivityActorType,
  ExecutionId,
  MembershipState,
  PresenceState,
  WorkflowRunId,
  WorkflowTaskId,
  WorkState,
} from '@vestara/types';
import type { ActivityCursor } from './m9-types';

// ─── Stream Item ────────────────────────────────────────────

/**
 * Classification of stream item content.
 * Determines visual treatment in M11.
 */
export type StreamItemKind =
  | 'conversation' // human messages
  | 'activity' // meaningful workflow/task/agent events
  | 'progress' // incremental progress updates
  | 'tool-call' // tool invocation started
  | 'tool-result' // tool invocation completed/failed
  | 'log' // detailed runtime logs
  | 'diagnostic' // error/failure details
  | 'evidence' // test results, verification output
  | 'telemetry' // system metrics, performance data
  | 'interaction'; // structured interactions (presented/responded)

/**
 * Projection importance for visual muting in M11.
 */
export type StreamImportance = 'primary' | 'secondary' | 'muted';

/**
 * A projected stream item for the Activity Room.
 * Derived from M9 ActivityRecords with importance classification.
 */
export interface StreamItem {
  /** Stable identity for this projected item. */
  readonly streamItemId: string;

  /** Reference to the source M9 ActivityRecord. */
  readonly activityId: string;

  /** M9 sequence number for ordering. */
  readonly sequenceNumber: number;

  /** Content classification. */
  readonly kind: StreamItemKind;

  /** Visual importance. */
  readonly importance: StreamImportance;

  /** Who produced this. */
  readonly actor: ActivityActor;

  /** Human-readable content. */
  readonly content: string;

  /** Timestamp. */
  readonly timestamp: string;

  /** M1 lineage. */
  readonly workflowRunId?: WorkflowRunId;
  readonly executionId?: ExecutionId;
  readonly taskId?: WorkflowTaskId;

  /** Aggregation context (for muted items). */
  readonly aggregated?: {
    readonly count: number;
    readonly kind: StreamItemKind;
    readonly summary: string;
    /** Deterministic references to underlying M9 record activity IDs for drill-down. */
    readonly referencedActivityIds: readonly string[];
    /** Sequence range [first, last] for M9 cursor-based retrieval. */
    readonly sequenceRange: { readonly first: number; readonly last: number };
  };

  /** Interaction presentation data (only when kind === 'interaction'). */
  readonly interaction?: {
    /** Stable identity for the originating StructuredInteraction. */
    readonly interactionId: string;
    /** Whether this is a presented or responded event. */
    readonly lifecycle: 'presented' | 'responded';
    /** Opaque choice options from the presenting producer. */
    readonly choices?: readonly { readonly choiceId: string; readonly label: string; readonly description?: string }[];
    /** Selected choice identity (only when lifecycle === 'responded'). */
    readonly selectedChoiceId?: string;
    /** Responding participant identity (only when lifecycle === 'responded'). */
    readonly respondingParticipantId?: string;
    /** Responding participant display name (only when lifecycle === 'responded'). */
    readonly respondingParticipantName?: string;
  };
}

// ─── Participant Projection ─────────────────────────────────

/**
 * Projected participant state in the Activity Room.
 * Combines durable membership with transient presence and work state.
 */
export interface ParticipantProjection {
  /** Unique participant identity. */
  readonly participantId: string;

  /** Participant type. */
  readonly type: ActivityActorType;

  /**
   * Canonical display name — participant identity when available.
   * For unnamed agents this is the stable agentId; for named agents
   * it is their chosen name. For humans it is the user name.
   */
  readonly displayName: string;

  /**
   * Presentation-only model display name (e.g. "Mimo", "DeepSeek").
   * Separate from canonical identity. UI uses `modelDisplayName ?? displayName`
   * as a fallback for unnamed AI participants.
   * Undefined for humans.
   */
  readonly modelDisplayName?: string;

  /** Agent role (e.g. 'developer', 'reviewer'). Undefined for humans. */
  readonly role?: string;

  /** Resolved model ID (e.g. 'mimo-v2.5-free'). Undefined for humans. */
  readonly modelId?: string;

  /** Resolved provider ID. Undefined for humans. */
  readonly providerId?: string;

  /**
   * Team membership reference — comes from upstream AgentTeam authority,
   * NOT from Activity Room. Undefined when no team authority is wired.
   * Activity Room does not define or own team membership.
   */
  readonly teamId?: string;

  /**
   * Team display name — denormalized from AgentTeam for presentation.
   * Activity Room consumes this; it does not define it.
   */
  readonly teamName?: string;

  /** Durable membership state. */
  readonly membership: MembershipState;

  /** Transient presence state (resolved independently, not from history). */
  readonly presence: PresenceState;

  /** Current work state (derived from authoritative facts). */
  readonly workState: WorkState;

  /** Current task assignment, if any. */
  readonly currentAssignment?: {
    readonly workflowRunId: WorkflowRunId;
    readonly taskId: WorkflowTaskId;
    readonly taskTitle?: string;
  };

  /** When this participant joined. */
  readonly joinedAt: string;

  /** Last activity timestamp. */
  readonly lastActivityAt: string;
}

// ─── Attention ──────────────────────────────────────────────

/**
 * Typed attention reasons. Not a generic boolean.
 */
export type AttentionReason =
  | 'task-failed'
  | 'task-blocked'
  | 'workflow-failed'
  | 'attention-required'
  | 'waiting-for-human'
  | 'dependency-unavailable'
  | 'retry-needed'
  | 'material-change'
  | 'interaction-presented'
  | 'interaction-resolved';

/**
 * Attention severity levels.
 */
export type AttentionSeverity = 'critical' | 'high' | 'medium' | 'low';

/**
 * An attention entry — something that needs human awareness.
 */
export interface AttentionEntry {
  /** Stable identity. */
  readonly attentionId: string;

  /** Why attention is needed. */
  readonly reason: AttentionReason;

  /** Severity level. */
  readonly severity: AttentionSeverity;

  /** Human-readable description. */
  readonly message: string;

  /** Which actor/task/workflow is involved. */
  readonly actor?: ActivityActor;
  readonly workflowRunId?: WorkflowRunId;
  readonly taskId?: WorkflowTaskId;

  /** Reference to originating StructuredInteraction (for interaction-presented/resolved). */
  readonly interactionId?: string;

  /** When this was generated. */
  readonly timestamp: string;

  /** Whether this has been acknowledged. */
  readonly acknowledged: boolean;
}

// ─── Workflow Summary ───────────────────────────────────────

/**
 * Projected workflow summary for the Activity Room.
 */
export interface WorkflowSummary {
  readonly workflowRunId: WorkflowRunId;
  readonly executionId?: ExecutionId;
  readonly status: 'pending' | 'running' | 'completed' | 'failed' | 'cancelled';
  readonly taskCount: number;
  readonly completedTasks: number;
  readonly failedTasks: number;
  readonly currentTask?: string;
  readonly startedAt: string;
  readonly lastActivityAt: string;
}

// ─── Contextual Capabilities ────────────────────────────────

/**
 * M11 composer discovery context.
 * Structured information for @ mentions, / commands, # references.
 */
export interface ContextualCapabilities {
  /** Mentionable participants (from dynamic room membership). */
  readonly mentionableParticipants: ReadonlyArray<{
    readonly participantId: string;
    readonly displayName: string;
    readonly type: ActivityActorType;
  }>;

  /** Available slash commands (from module contributions). */
  readonly availableCommands: ReadonlyArray<{
    readonly command: string;
    readonly description: string;
  }>;

  /** Referenceable entities (workflows, tasks, artifacts). */
  readonly referenceableEntities: ReadonlyArray<{
    readonly entityId: string;
    readonly entityType: 'workflow' | 'task' | 'artifact';
    readonly displayName: string;
  }>;
}

// ─── Activity Room Projection ───────────────────────────────

/**
 * Complete Activity Room projection state.
 * Suitable for M11's production Activity Room API/UI.
 *
 * Reconstructable from M9 durable storage.
 * No critical state exists only inside M10 process.
 */
export interface ActivityRoomProjection {
  /** Room metadata. */
  readonly room: {
    readonly roomId: string;
    readonly name: string;
    readonly cursor: ActivityCursor;
    readonly rebuiltAt: string;
  };

  /** Current participants. */
  readonly participants: readonly ParticipantProjection[];

  /** Activity stream items. */
  readonly stream: readonly StreamItem[];

  /** Current workflow summary, if active. */
  readonly workflowSummary?: WorkflowSummary;

  /** Attention entries requiring human awareness. */
  readonly attention: readonly AttentionEntry[];

  /** Contextual capabilities for M11 composer. */
  readonly contextualCapabilities: ContextualCapabilities;
}

/**
 * M11C-I1: M9 Production Ingestion Bridge
 *
 * Single EventBus → M9 write boundary. Normalizes authoritative EventBus
 * events into canonical M9 ActivityEvents and appends to the durable store.
 *
 * Architecture:
 *   EventBus → M9IngestionBridge → DurableM9ActivityStore (M9)
 *
 * Invariants:
 *   I1-1: Single M9 ingestion authority (no other DurableM9ActivityStore.append calls)
 *   I1-2: Event identity preservation (canonical M1/M2 lineage flows through)
 *   I1-3: Idempotent redelivery (M9 deduplicates by eventId)
 *   I1-4: Typed normalization (existing M9 adapters, no prose parsing)
 *   I1-5: Explicit event disposition (INGEST/IGNORE/DEFER per pattern)
 *   I1-6: Failure isolation (bridge failures don't corrupt authoritative execution)
 *   I1-7: Ordering (sequential events produce deterministic M9 sequences)
 *   I1-8: No feedback loop (bridge does not emit to EventBus)
 *   I1-9: Lifecycle (initialized once, disposed cleanly)
 */

import type { EventBus } from '@vestara/event-bus';
import type { Unsubscribe, VestaraEvent } from '@vestara/shared';
import type { WorkflowRunId } from '@vestara/types';
import {
  fromAgentLifecycle,
  fromHumanMessage,
  fromInteractionPresented,
  fromInteractionResponded,
  fromToolEvent,
} from './m9-adapter';
import type { ActivityEvent, M9ActivityStore } from './m9-types';

// ─── Event Disposition (I1-5) ──────────────────────────────

type Disposition = 'INGEST' | 'IGNORE' | 'DEFER';

