// ─── Bridge ────────────────────────────────────────────────

export interface M9IngestionBridgeOptions {
  /** The M9 durable activity store. */
  readonly store: M9ActivityStore;
  /** The process-wide EventBus. */
  readonly eventBus: EventBus;
  /** Optional logger. */
  readonly logger?: {
    warn: (msg: string, ctx?: Record<string, unknown>) => void;
    info: (msg: string, ctx?: Record<string, unknown>) => void;
  };
}

/**
 * Single EventBus → M9 write boundary.
 *
 * Subscribes to EventBus patterns classified as INGEST and normalizes
 * them into M9 ActivityEvents using existing adapters. Appends to the
 * DurableM9ActivityStore. Does NOT emit to EventBus (I1-8).
 */
export class M9IngestionBridge {
  private readonly store: M9ActivityStore;
  private readonly eventBus: EventBus;
  private readonly logger?: M9IngestionBridgeOptions['logger'];
  private readonly unsubscribers: Unsubscribe[] = [];
  private started = false;

  constructor(options: M9IngestionBridgeOptions) {
    this.store = options.store;
    this.eventBus = options.eventBus;
    this.logger = options.logger;
  }

  /**
   * Subscribe to INGEST patterns. Must be called exactly once (I1-9).
   * Safe to call multiple times — subsequent calls are no-ops.
   */
  start(): void {
    if (this.started) return;
    this.started = true;

    const ingestPatterns = PATTERN_DISPOSITIONS.filter((d) => d.disposition === 'INGEST');

    for (const disposition of ingestPatterns) {
      try {
        const unsub = this.eventBus.subscribe(disposition.pattern, async (event: VestaraEvent) => {
          await this.ingest(event);
        });
        this.unsubscribers.push(unsub);
      } catch (err) {
        this.logger?.warn('M9IngestionBridge: failed to subscribe', {
          pattern: disposition.pattern,
          error: err instanceof Error ? err.message : String(err),
        });
      }
    }

    this.logger?.info('M9IngestionBridge started', { patterns: ingestPatterns.length });
  }

  /**
   * Unsubscribe all patterns. Called during shutdown/restart (I1-9).
   */
  stop(): void {
    for (const unsub of this.unsubscribers) {
      try {
        unsub();
      } catch {
        /* best-effort */
      }
    }
    this.unsubscribers.length = 0;
    this.started = false;
    this.logger?.info('M9IngestionBridge stopped');
  }

  /**
   * Get the list of patterns classified as INGEST (for testing/introspection).
   */
  static getIngestPatterns(): readonly string[] {
    return PATTERN_DISPOSITIONS.filter((d) => d.disposition === 'INGEST').map((d) => d.pattern);
  }

  /**
   * Get the full disposition table (for testing/introspection).
   */
  static getDispositions(): readonly PatternDisposition[] {
    return PATTERN_DISPOSITIONS;
  }

  // ─── Internal ────────────────────────────────────────────

  /**
   * Normalize and append a single EventBus event to M9.
   * Failures are logged and do not propagate (I1-6).
   *
   * F2 correction: Uses semantic eventId from payload for interaction events,
   * ensuring stable deduplication across normal and recovery publication.
   */
  private async ingest(event: VestaraEvent): Promise<void> {
    try {
      const activityEvent = this.mapToActivityEvent(event);
      if (activityEvent === null) {
        return;
      }
      // F2 correction: For interaction events, use the semantic eventId from the
      // payload (e.g. "interaction:presented:${interactionId}") instead of the
      // auto-generated delivery id ("interaction:presented:evt-XXXX"). This ensures
      // the same semantic fact produces the same M9 eventId across normal and
      // recovery publication, enabling idempotent deduplication.
      const deterministicEvent: ActivityEvent = {
        ...activityEvent,
        eventId: this.getSemanticEventId(event, activityEvent),
      };
      await this.store.append(deterministicEvent);
    } catch (err) {
      // I1-6: Failure isolation — log but don't throw
      this.logger?.warn('M9IngestionBridge: ingest failed', {
        eventId: event.id,
        eventType: event.type,
        error: err instanceof Error ? err.message : String(err),
      });
    }
  }

  /**
   * F2 correction: Derive the M9 eventId.
   * For interaction events, use the stable semantic identity from the payload.
   * For human messages, use the authoritative messageId for stable deduplication.
   * For tool events, use the adapter-generated eventId (derived from callID).
   * For all other events, preserve the existing delivery-based identity.
   */
  private getSemanticEventId(event: VestaraEvent, activityEvent: ActivityEvent): string {
    if (event.type === 'interaction:presented' || event.type === 'interaction:responded') {
      // The adapter puts the semantic eventId (e.g. "interaction:presented:${interactionId}")
      // in the payload. Use it directly for stable deduplication.
      return (event.payload.eventId as string) || `${event.type}:${event.id}`;
    }
    if (event.type === 'conversation:message.sent') {
      // Use the authoritative messageId from the conversation service for stable
      // deduplication. Same logical message → same M9 eventId across replays.
      const messageId = event.payload.messageId as string | undefined;
      return messageId ? `human.message:${messageId}` : `${event.type}:${event.id}`;
    }
    if (event.type === 'opencode.message.part.updated') {
      // The fromToolEvent adapter generates a deterministic eventId from callID.
      // Use it for stable deduplication across replays of the same tool transition.
      return activityEvent.eventId;
    }
    if (event.type === 'conversation:response.completed') {
      // AR-DOGFOOD-009: Deterministic eventId from authoritative messageId.
      // Same response message replay → same Activity eventId.
      const messageId = event.payload.messageId as string | undefined;
      return messageId ? `agent.completed:${messageId}` : `${event.type}:${event.id}`;
    }
    return `${event.type}:${event.id}`;
  }

  /**
   * Map a VestaraEvent to an M9 ActivityEvent using existing adapters (I1-4).
   * Returns null if the event type doesn't match any adapter.
   */
  private mapToActivityEvent(event: VestaraEvent): ActivityEvent | null {
    const type = event.type;

    // ─── Human message → fromHumanMessage ─────────────────
    // Uses actual message content from the authoritative conversation service.
    // eventId is derived from messageId for stable deduplication.
    if (type === 'conversation:message.sent') {
      const userId = (event.actor?.id as string) || (event.payload.userId as string) || 'local';
      const displayName = (event.actor?.id as string) || (event.payload.userId as string) || 'User';
      return fromHumanMessage({
        message: (event.payload.content as string) || '',
        userId,
        displayName,
        messageId: event.payload.messageId as string | undefined,
        conversationId: event.payload.conversationId as string | undefined,
        executionId: event.metadata.executionId as any,
        traceId: event.metadata.traceId as any,
      });
    }

    // ─── Provider request started → agent.started ──────────
    // Authoritative execution start signal from the conversation service.
    // Different runtime producers (conversation service, agent harness) map to
    // canonical Activity semantics downstream — this is NOT agent:started.
    if (type === 'conversation:provider.request.started') {
      const _conversationId = (event.payload.conversationId as string) || 'unknown';
      const model = (event.payload.model as string) || undefined;
      return fromAgentLifecycle({
        agentId: 'vestara',
        displayName: 'Vestara',
        lifecycleType: 'started',
        message: model ? `Started work (${model})` : 'Started work',
        executionId: event.metadata.executionId as any,
        traceId: event.metadata.traceId as any,
      });
    }

    // ─── AI response completed → fromAgentLifecycle ────────
    // AR-DOGFOOD-009: Use bounded contentPreview from authoritative conversation service.
    // Activity Room shows a preview, not the full response (Conversation = authority).
    // Provenance: conversationId + responseMessageId carried in payload.data.
    if (type === 'conversation:response.completed') {
      const contentPreview = (event.payload.contentPreview as string) || undefined;
      const tokens = event.payload.tokens as number | undefined;
      const conversationId = (event.payload.conversationId as string) || undefined;
      const responseMessageId = (event.payload.messageId as string) || undefined;
      const preview = contentPreview ? `${contentPreview}` : tokens ? `Completed (${tokens} tokens)` : 'Completed';
      const base = fromAgentLifecycle({
        agentId: 'vestara',
        displayName: 'Vestara',
        lifecycleType: 'completed',
        message: preview,
        executionId: event.metadata.executionId as any,
        traceId: event.metadata.traceId as any,
      });
      // Carry provenance in payload.data for future navigation
      return {
        ...base,
        payload: {
          ...base.payload,
          data: {
            ...base.payload.data,
            ...(conversationId ? { conversationId } : {}),
            ...(responseMessageId ? { responseMessageId } : {}),
          },
        },
      };
    }

    // ─── Agent lifecycle → fromAgentLifecycle ──────────────
    if (type === 'agent:started') {
      return fromAgentLifecycle({
        agentId: (event.payload.agentId as string) || 'unknown',
        displayName: (event.payload.agentId as string) || 'Agent',
        lifecycleType: 'started',
        role: (event.payload.role as string) || undefined,
        modelId: (event.payload.modelId as string) || undefined,
        modelDisplayName: (event.payload.modelDisplayName as string) || undefined,
        providerId: (event.payload.providerId as string) || undefined,
        message: `${(event.payload.modelDisplayName as string) || (event.payload.agentId as string) || 'Agent'} started ${(event.payload.task as string) || 'task'}`,
        executionId: event.metadata.executionId as any,
        traceId: event.metadata.traceId as any,
      });
    }
    if (type === 'agent:completed') {
      return fromAgentLifecycle({
        agentId: (event.payload.agentId as string) || 'unknown',
        displayName: (event.payload.agentId as string) || 'Agent',
        lifecycleType: 'completed',
        role: (event.payload.role as string) || undefined,
        modelId: (event.payload.modelId as string) || undefined,
        modelDisplayName: (event.payload.modelDisplayName as string) || undefined,
        providerId: (event.payload.providerId as string) || undefined,
        message: `${(event.payload.modelDisplayName as string) || (event.payload.agentId as string) || 'Agent'} completed`,
        executionId: event.metadata.executionId as any,
        traceId: event.metadata.traceId as any,
      });
    }

    // ─── Changeset created → fromAgentLifecycle ────────────
    if (type === 'changeset:created') {
      return fromAgentLifecycle({
        agentId: (event.payload.agentId as string) || 'vestara',
        displayName: (event.payload.agentName as string) || 'Vestara',
        lifecycleType: 'completed',
        message: `Created change set with ${event.payload.fileCount ?? 0} file(s)`,
        executionId: event.metadata.executionId as any,
        traceId: event.metadata.traceId as any,
      });
    }

    // ─── Verification → fromAgentLifecycle ─────────────────
    if (type === 'verification:started') {
      return fromAgentLifecycle({
        agentId: (event.payload.agentId as string) || 'verifier',
        displayName: (event.payload.agentName as string) || 'Verifier',
        lifecycleType: 'started',
        message: 'Running verification checks...',
        executionId: event.metadata.executionId as any,
        traceId: event.metadata.traceId as any,
      });
    }
    if (type === 'verification:completed') {
      return fromAgentLifecycle({
        agentId: (event.payload.agentId as string) || 'verifier',
        displayName: (event.payload.agentName as string) || 'Verifier',
        lifecycleType: 'completed',
        message: event.payload.allPassed ? 'All checks passed' : `${event.payload.failedCount ?? 0} check(s) failed`,
        executionId: event.metadata.executionId as any,
        traceId: event.metadata.traceId as any,
      });
    }

    // ─── Tool lifecycle (OpenCode runtime) ─────────────────
    // Authoritative tool operation facts from OpenCode. Uses callID for
    // stable correlation across called/succeeded/failed transitions.
    // Tool events arrive as message.part.updated with part.type=tool.
    if (type === 'opencode.message.part.updated') {
      const outerPayload = (event.payload ?? {}) as Record<string, unknown>;
      const innerPayload = (outerPayload.payload ?? outerPayload) as Record<string, unknown>;
      const part = innerPayload.part as Record<string, unknown> | undefined;
      if (part && part.type === 'tool') {
        const callID = (part.callID as string) ?? (part.callId as string) ?? `${event.id}`;
        const toolName = (part.tool as string) ?? (part.name as string) ?? 'unknown';
        const state = (part.state as Record<string, unknown>)?.status as string | undefined;
        const lifecycleType =
          state === 'running'
            ? 'called'
            : state === 'completed' || state === 'completed'
              ? 'succeeded'
              : state === 'error' || state === 'failed'
                ? 'failed'
                : 'called'; // default to called for unknown states
        return fromToolEvent({ lifecycleType: lifecycleType as 'called' | 'succeeded' | 'failed', callID, toolName });
      }
      return null; // non-tool part updates are not ingested
    }

    // ─── Orchestration events → generic ActivityEvent ──────
    if (type.startsWith('orchestration.')) {
      const projectId = event.payload.projectId as string | undefined;
      const taskId = event.payload.taskId as string | undefined;
      return {
        eventId: `orch-${event.id}`,
        type: mapOrchestrationType(type),
        timestamp: event.timestamp,
        workflowRunId: projectId as WorkflowRunId | undefined,
        taskId: taskId as any,
        actor: {
          type: 'system',
          id: 'workflow-orchestrator',
          displayName: 'Workflow Orchestrator',
        },
        source: 'workflow-engine',
        payload: {
          message: defaultMessage(type),
        },
      };
    }

    // ─── Plan events → generic ActivityEvent ───────────────
    if (type === 'plan:created' || type === 'plan:approved') {
      return {
        eventId: `plan-${event.id}`,
        type: type === 'plan:created' ? 'workflow.started' : 'workflow.completed',
        timestamp: event.timestamp,
        actor: {
          type: 'human',
          id: (event.actor?.id as string) || 'local',
          displayName: (event.payload.userName as string) || 'User',
        },
        source: 'human-input',
        payload: {
          message:
            type === 'plan:created'
              ? `Created plan: ${event.payload.title || ''}`
              : `Approved plan: ${event.payload.title || ''}`,
        },
      };
    }

    // ─── Changeset applied → generic ActivityEvent ──────────
    if (type === 'changeset:applied') {
      return {
        eventId: `cs-${event.id}`,
        type: 'workflow.completed',
        timestamp: event.timestamp,
        actor: {
          type: 'human',
          id: (event.actor?.id as string) || 'local',
          displayName: 'User',
        },
        source: 'human-input',
        payload: {
          message: 'Applied change set to disk',
        },
      };
    }

    // ─── Interaction events → fromInteractionPresented/Responded ──
    if (type === 'interaction:presented') {
      return fromInteractionPresented({
        eventId: (event.payload.eventId as string) || event.id,
        interactionId: (event.payload.interactionId as string) || 'unknown',
        conversationId: event.payload.conversationId as string | undefined,
        presentingParticipantId:
          (event.payload.presentingParticipantId as string) || (event.actor?.id as string) || 'system',
        presentingParticipantName: (event.payload.presentingParticipantName as string) || 'System',
        createdAt: event.timestamp,
        content: (event.payload.content as string) || '',
        choices:
          (event.payload.choices as readonly {
            readonly choiceId: string;
            readonly label: string;
            readonly description?: string;
          }[]) || [],
      });
    }
    if (type === 'interaction:responded') {
      return fromInteractionResponded({
        eventId: (event.payload.eventId as string) || event.id,
        interactionId: (event.payload.interactionId as string) || 'unknown',
        responseId: (event.payload.responseId as string) || 'unknown',
        selectedChoiceId: (event.payload.selectedChoiceId as string) || 'unknown',
        respondingParticipantId:
          (event.payload.respondingParticipantId as string) || (event.actor?.id as string) || 'local',
        respondingParticipantName: (event.payload.respondingParticipantName as string) || 'User',
        respondedAt: event.timestamp,
        correlationId: event.payload.correlationId as string | undefined,
      });
    }

    // Unknown type — skip
    return null;
  }
}

// ─── Helpers ───────────────────────────────────────────────

function mapOrchestrationType(type: string): ActivityEvent['type'] {
  // Map orchestration.* to canonical ActivityType
  if (type.includes('task.started') || type.includes('task.runnable')) return 'task.started';
  if (type.includes('task.completed')) return 'task.completed';
  if (type.includes('task.failed')) return 'task.failed';
  if (type.includes('task.blocked')) return 'task.failed';
  if (type.includes('project.completed')) return 'workflow.completed';
  if (type.includes('plan.generated')) return 'workflow.started';
  return 'system.event';
}

function defaultMessage(type: string): string {
  switch (type) {
    case 'orchestration.project.completed':
      return 'Project completed';
    case 'orchestration.task.failed':
      return 'Task failed';
    case 'orchestration.task.blocked':
      return 'Task blocked';
    case 'orchestration.task.approval-requested':
      return 'Approval required';
    case 'orchestration.task.review.decided':
      return 'Task reviewed';
    case 'orchestration.verification.failed':
      return 'Verification failed';
    case 'orchestration.plan.generated':
      return 'Plan generated';
    default:
      return type.replace('orchestration.', '');
  }
}

/**
 * ARX-015 M10: Projection Runtime
 *
 * Transforms durable M9 ActivityRecords into live projection state.
 * Reconstructable: given the same ordered M9 records, rebuilding
 * produces equivalent projection state.
 *
 * This is a projection layer — never an orchestration authority.
 */

import type { MembershipState, WorkState } from '@vestara/types';
import type { ActivityCursor, ActivityRecord } from './m9-types';
import type {
  ActivityRoomProjection,
  AttentionEntry,
  ContextualCapabilities,
  ParticipantProjection,
  StreamImportance,
  StreamItem,
  StreamItemKind,
  WorkflowSummary,
} from './projection-types';

// ─── Configuration ──────────────────────────────────────────

/** Maximum muted items before aggregation kicks in. */
const MUTING_THRESHOLD = 5;

/** Maximum stream items in memory before backpressure. */
const MAX_STREAM_ITEMS = 500;

// ─── Projection Runtime ─────────────────────────────────────

/**
 * Live projection runtime. Rebuilds from M9 records and processes
 * new activities incrementally.
 */
export class ProjectionRuntime {
  private participants = new Map<string, ParticipantProjection>();
  private stream: StreamItem[] = [];
  private attention: AttentionEntry[] = [];
  private workflowSummaries = new Map<string, WorkflowSummary>();
  private cursor: ActivityCursor | null = null;
  private roomName = 'Activity Room';

  /**
   * Rebuild entire projection from M9 durable records.
   * Produces equivalent state given the same ordered records.
   */
  rebuild(records: readonly ActivityRecord[]): ActivityRoomProjection {
    // Reset state
    this.participants.clear();
    this.stream = [];
    this.attention = [];
    this.workflowSummaries.clear();
    this.cursor = null;

    // Process each record in order
    for (const record of records) {
      this.processRecord(record);
    }

    return this.getProjection();
  }

  /**
   * Process a new activity record (live update).
   */
  processRecord(record: ActivityRecord): void {
    // Update cursor
    this.cursor = {
      sequenceNumber: record.sequenceNumber,
      eventId: record.eventId,
      timestamp: record.timestamp,
    };

    // Update participants
    this.updateParticipantFromRecord(record);

    // Add stream item
    const streamItem = this.recordToStreamItem(record);
    this.stream.push(streamItem);

    // Backpressure: trim old muted items
    if (this.stream.length > MAX_STREAM_ITEMS) {
      this.stream = this.stream.slice(-MAX_STREAM_ITEMS);
    }

    // Update workflow summary
    this.updateWorkflowSummary(record);

    // Generate attention entries
    this.generateAttention(record);
  }

  /**
   * Get current projection state.
   */
  getProjection(): ActivityRoomProjection {
    const participants = [...this.participants.values()];

    // Aggregate muted items for cleaner presentation
    const aggregatedStream = this.aggregateMutedItems(this.stream);

    return {
      room: {
        roomId: 'default',
        name: this.roomName,
        cursor: this.cursor ?? { sequenceNumber: 0, eventId: '', timestamp: '' },
        rebuiltAt: new Date().toISOString(),
      },
      participants,
      stream: aggregatedStream,
      workflowSummary: this.getLatestWorkflowSummary(),
      attention: this.attention.filter((a) => !a.acknowledged),
      contextualCapabilities: this.buildContextualCapabilities(participants),
    };
  }

  // ─── Participant Management ───────────────────────────────

  private updateParticipantFromRecord(record: ActivityRecord): void {
    const actor = record.actor;
    const participantId = `${actor.type}-${actor.id}`;

    const existing = this.participants.get(participantId);

    const membership = this.deriveMembership(record);
    const workState = this.deriveWorkState(record);
    const assignment = this.deriveAssignment(record);

    // Extract model/role metadata from payload.data (set by AgentLifecycleBridge)
    const data = record.payload.data as Record<string, unknown> | undefined;
    const role = typeof data?.role === 'string' ? data.role : undefined;
    const modelId = typeof data?.modelId === 'string' ? data.modelId : undefined;
    const modelDisplayName = typeof data?.modelDisplayName === 'string' ? data.modelDisplayName : undefined;
    const providerId = typeof data?.providerId === 'string' ? data.providerId : undefined;
    const teamId = typeof data?.teamId === 'string' ? data.teamId : undefined;
    const teamName = typeof data?.teamName === 'string' ? data.teamName : undefined;

    if (existing) {
      // Update existing participant — preserve stable identity, update metadata
      this.participants.set(participantId, {
        ...existing,
        modelDisplayName: modelDisplayName ?? existing.modelDisplayName,
        role: role ?? existing.role,
        modelId: modelId ?? existing.modelId,
        providerId: providerId ?? existing.providerId,
        teamId: teamId ?? existing.teamId,
        teamName: teamName ?? existing.teamName,
        membership: membership ?? existing.membership,
        workState: workState ?? existing.workState,
        currentAssignment: assignment ?? existing.currentAssignment,
        lastActivityAt: record.timestamp,
      });
    } else {
      // New participant
      this.participants.set(participantId, {
        participantId,
        type: actor.type,
        displayName: actor.displayName,
        modelDisplayName,
        role,
        modelId,
        providerId,
        teamId,
        teamName,
        membership: membership ?? 'joined',
        presence: 'offline', // presence resolved independently
        workState: workState ?? 'available',
        currentAssignment: assignment,
        joinedAt: record.timestamp,
        lastActivityAt: record.timestamp,
      });
    }
  }

  private deriveMembership(record: ActivityRecord): MembershipState | undefined {
    if (record.type === 'human.message' && record.actor.type === 'human') {
      return 'joined';
    }
    if (record.type.startsWith('agent.')) {
      return 'joined';
    }
    return undefined;
  }

  private deriveWorkState(record: ActivityRecord): WorkState | undefined {
    switch (record.type) {
      case 'task.started':
      case 'agent.started':
        return 'working';
      case 'task.runnable':
        return record.actor.type === 'agent' ? 'available' : undefined;
      case 'task.completed':
      case 'agent.completed':
        return 'available';
      case 'task.failed':
      case 'agent.failed':
        return 'attention-required';
      case 'agent.waiting':
        return 'waiting';
      case 'workflow.failed':
        return record.actor.type === 'agent' ? 'blocked' : undefined;
      default:
        return undefined;
    }
  }

  private deriveAssignment(record: ActivityRecord): ParticipantProjection['currentAssignment'] | undefined {
    if (record.type === 'task.started' && record.taskId && record.workflowRunId) {
      return {
        workflowRunId: record.workflowRunId,
        taskId: record.taskId,
        taskTitle: record.payload.message,
      };
    }
    return undefined;
  }

  // ─── Stream Management ────────────────────────────────────

  private recordToStreamItem(record: ActivityRecord): StreamItem {
    const kind = this.classifyKind(record);
    const importance = this.classifyImportance(record, kind);
    const activityIdStr = String(record.activityId);

    const base: StreamItem = {
      streamItemId: `si-${activityIdStr}`,
      activityId: activityIdStr,
      sequenceNumber: record.sequenceNumber,
      kind,
      importance,
      actor: record.actor,
      content: record.payload.message ?? `${record.type}`,
      timestamp: record.timestamp,
      workflowRunId: record.workflowRunId,
      executionId: record.executionId,
      taskId: record.taskId,
    };

    // Carry interaction presentation data for kind === 'interaction'
    if (kind === 'interaction' && record.payload.data) {
      const data = record.payload.data as Record<string, unknown>;
      const interactionId = typeof data.interactionId === 'string' ? data.interactionId : undefined;
      if (interactionId) {
        const lifecycle = record.type === 'interaction.responded' ? ('responded' as const) : ('presented' as const);
        const choices = Array.isArray(data.choices)
          ? (data.choices as readonly { choiceId: string; label: string; description?: string }[])
          : undefined;
        const selectedChoiceId = typeof data.selectedChoiceId === 'string' ? data.selectedChoiceId : undefined;
        const respondingParticipantId = lifecycle === 'responded' ? record.actor.id : undefined;
        const respondingParticipantName = lifecycle === 'responded' ? record.actor.displayName : undefined;

        return {
          ...base,
          interaction: {
            interactionId,
            lifecycle,
            ...(choices ? { choices } : {}),
            ...(selectedChoiceId ? { selectedChoiceId } : {}),
            ...(respondingParticipantId ? { respondingParticipantId } : {}),
            ...(respondingParticipantName ? { respondingParticipantName } : {}),
          },
        };
      }
    }

    return base;
  }

  private classifyKind(record: ActivityRecord): StreamItemKind {
    switch (record.type) {
      case 'human.message':
        return 'conversation';
      case 'workflow.started':
      case 'workflow.completed':
      case 'task.started':
      case 'task.completed':
      case 'agent.assigned':
      case 'agent.completed':
        return 'activity';
      case 'agent.progress':
        return 'progress';
      case 'tool.called':
        return 'tool-call';
      case 'tool.succeeded':
      case 'tool.failed':
        return 'tool-result';
      case 'task.runnable':
        return 'log';
      case 'task.failed':
      case 'agent.failed':
      case 'workflow.failed':
        return 'diagnostic';
      case 'system.event':
        return record.payload.data ? 'evidence' : 'telemetry';
      case 'interaction.presented':
      case 'interaction.responded':
        return 'interaction';
      default:
        return 'log';
    }
  }

  private classifyImportance(record: ActivityRecord, kind: StreamItemKind): StreamImportance {
    // Human messages are always primary
    if (record.type === 'human.message') return 'primary';

    // Workflow lifecycle is primary
    if (record.type === 'workflow.started' || record.type === 'workflow.completed') return 'primary';
    if (record.type === 'workflow.failed') return 'primary';

    // Task lifecycle is secondary
    if (record.type === 'task.started' || record.type === 'task.completed') return 'secondary';
    if (record.type === 'task.failed') return 'secondary';

    // Agent assigned/completed is secondary
    if (record.type === 'agent.assigned' || record.type === 'agent.completed') return 'secondary';

    // Tool operations are secondary (visible, not primary)
    if (record.type === 'tool.called' || record.type === 'tool.succeeded' || record.type === 'tool.failed')
      return 'secondary';

    // Interaction: presented is primary (decision needed), responded is secondary
    if (record.type === 'interaction.presented') return 'primary';
    if (record.type === 'interaction.responded') return 'secondary';

    // Progress, logs, telemetry are muted
    if (kind === 'progress' || kind === 'log' || kind === 'telemetry') return 'muted';

    // Default to secondary
    return 'secondary';
  }

  private aggregateMutedItems(items: StreamItem[]): StreamItem[] {
    const result: StreamItem[] = [];
    let mutedBuffer: StreamItem[] = [];

    for (const item of items) {
      if (item.importance === 'muted') {
        mutedBuffer.push(item);
        if (mutedBuffer.length >= MUTING_THRESHOLD) {
          result.push(this.coalesceMuted(mutedBuffer));
          mutedBuffer = [];
        }
      } else {
        if (mutedBuffer.length > 0) {
          result.push(this.coalesceMuted(mutedBuffer));
          mutedBuffer = [];
        }
        result.push(item);
      }
    }

    // Flush remaining muted items
    if (mutedBuffer.length > 0) {
      result.push(this.coalesceMuted(mutedBuffer));
    }

    return result;
  }

  private coalesceMuted(items: StreamItem[]): StreamItem {
    if (items.length === 1) return items[0];

    const kindCounts = new Map<StreamItemKind, number>();
    for (const item of items) {
      kindCounts.set(item.kind, (kindCounts.get(item.kind) ?? 0) + 1);
    }

    const dominantKind = [...kindCounts.entries()].sort((a, b) => b[1] - a[1])[0][0];
    const totalLogs = items.filter((i) => i.kind === 'log').length;
    const totalTools = items.filter((i) => i.kind === 'progress').length;
    const warnings = items.filter((i) => i.kind === 'diagnostic').length;

    const parts: string[] = [];
    if (totalLogs > 0) parts.push(`${totalLogs} logs`);
    if (totalTools > 0) parts.push(`${totalTools} tools`);
    if (warnings > 0) parts.push(`${warnings} warning${warnings > 1 ? 's' : ''}`);

    return {
      streamItemId: `si-agg-${items[0].sequenceNumber}-${items[items.length - 1].sequenceNumber}`,
      activityId: items[0].activityId,
      sequenceNumber: items[0].sequenceNumber,
      kind: dominantKind,
      importance: 'muted',
      actor: items[0].actor,
      content: `${items.length} activities`,
      timestamp: items[items.length - 1].timestamp,
      aggregated: {
        count: items.length,
        kind: dominantKind,
        summary: parts.join(' · ') || `${items.length} items`,
        referencedActivityIds: items.map((i) => i.activityId),
        sequenceRange: {
          first: items[0].sequenceNumber,
          last: items[items.length - 1].sequenceNumber,
        },
      },
    };
  }

  // ─── Workflow Summary ─────────────────────────────────────

  private updateWorkflowSummary(record: ActivityRecord): void {
    if (!record.workflowRunId) return;

    const existing = this.workflowSummaries.get(record.workflowRunId);

    const status = this.deriveWorkflowStatus(record);
    const taskUpdate = this.deriveTaskUpdate(record);

    if (existing) {
      this.workflowSummaries.set(record.workflowRunId, {
        ...existing,
        status: status ?? existing.status,
        taskCount: taskUpdate?.taskCount ?? existing.taskCount,
        completedTasks: taskUpdate?.completedTasks ?? existing.completedTasks,
        failedTasks: taskUpdate?.failedTasks ?? existing.failedTasks,
        currentTask: taskUpdate?.currentTask ?? existing.currentTask,
        lastActivityAt: record.timestamp,
      });
    } else {
      this.workflowSummaries.set(record.workflowRunId, {
        workflowRunId: record.workflowRunId,
        executionId: record.executionId,
        status: status ?? 'running',
        taskCount: taskUpdate?.taskCount ?? 0,
        completedTasks: taskUpdate?.completedTasks ?? 0,
        failedTasks: taskUpdate?.failedTasks ?? 0,
        currentTask: taskUpdate?.currentTask,
        startedAt: record.timestamp,
        lastActivityAt: record.timestamp,
      });
    }
  }

  private deriveWorkflowStatus(record: ActivityRecord): WorkflowSummary['status'] | undefined {
    switch (record.type) {
      case 'workflow.started':
        return 'running';
      case 'workflow.completed':
        return 'completed';
      case 'workflow.failed':
        return 'failed';
      case 'workflow.cancelled':
        return 'cancelled';
      default:
        return undefined;
    }
  }

  private deriveTaskUpdate(record: ActivityRecord): Partial<WorkflowSummary> | undefined {
    switch (record.type) {
      case 'task.started':
        return { currentTask: record.taskId };
      case 'task.completed':
        return { completedTasks: 1, currentTask: undefined };
      case 'task.failed':
        return { failedTasks: 1 };
      case 'task.runnable':
        return { taskCount: 1 };
      default:
        return undefined;
    }
  }

  private getLatestWorkflowSummary(): WorkflowSummary | undefined {
    const summaries = [...this.workflowSummaries.values()];
    if (summaries.length === 0) return undefined;
    return summaries.reduce((latest, s) => (s.lastActivityAt > latest.lastActivityAt ? s : latest));
  }

  // ─── Attention ────────────────────────────────────────────

  private generateAttention(record: ActivityRecord): void {
    const attention = this.deriveAttention(record);
    if (attention) {
      // Deduplicate: don't create duplicate attention for same task+reason
      // Skip dedup when taskId is undefined (interaction attention uses interactionId instead)
      const existing =
        attention.taskId !== undefined
          ? this.attention.find(
              (a) => a.taskId === attention.taskId && a.reason === attention.reason && !a.acknowledged,
            )
          : undefined;
      if (!existing) {
        this.attention.push(attention);
      } else {
        // Always update to reflect latest failure details
        const idx = this.attention.indexOf(existing);
        this.attention[idx] = attention;
      }
    }

    // Deduplicate interaction attention: at most one unacknowledged per interactionId
    if (attention?.interactionId) {
      const dup = this.attention.find(
        (a) => a.interactionId === attention.interactionId && a.reason === attention.reason && !a.acknowledged,
      );
      if (dup && dup !== attention) {
        // Already have an unacknowledged attention for this interaction — remove the older one
        const idx = this.attention.indexOf(dup);
        this.attention.splice(idx, 1);
      }
    }

    // Auto-resolve attention when task completes
    if (record.type === 'task.completed' && record.taskId) {
      const toResolve = this.attention.find((a) => a.taskId === record.taskId && !a.acknowledged);
      if (toResolve) {
        const idx = this.attention.indexOf(toResolve);
        this.attention[idx] = { ...toResolve, acknowledged: true };
      }
    }

    // Auto-resolve interaction attention when interaction is responded
    if (record.type === 'interaction.responded') {
      const data = record.payload.data as Record<string, unknown> | undefined;
      const interactionId = typeof data?.interactionId === 'string' ? data.interactionId : undefined;
      if (interactionId) {
        const toResolve = this.attention.find((a) => a.interactionId === interactionId && !a.acknowledged);
        if (toResolve) {
          const idx = this.attention.indexOf(toResolve);
          this.attention[idx] = { ...toResolve, acknowledged: true };
        }
      }
    }
  }

  private deriveAttention(record: ActivityRecord): AttentionEntry | undefined {
    switch (record.type) {
      case 'task.failed':
        return {
          attentionId: `att-${String(record.activityId)}`,
          reason: 'task-failed',
          severity: 'high',
          message: record.payload.error?.message ?? `Task failed: ${record.payload.message ?? record.taskId}`,
          actor: record.actor,
          workflowRunId: record.workflowRunId,
          taskId: record.taskId,
          timestamp: record.timestamp,
          acknowledged: false,
        };
      case 'workflow.failed':
        return {
          attentionId: `att-${String(record.activityId)}`,
          reason: 'workflow-failed',
          severity: 'critical',
          message: record.payload.error?.message ?? 'Workflow failed',
          actor: record.actor,
          workflowRunId: record.workflowRunId,
          timestamp: record.timestamp,
          acknowledged: false,
        };
      case 'agent.waiting':
        return {
          attentionId: `att-${String(record.activityId)}`,
          reason: 'waiting-for-human',
          severity: 'medium',
          message: record.payload.message ?? 'Agent waiting for input',
          actor: record.actor,
          workflowRunId: record.workflowRunId,
          taskId: record.taskId,
          timestamp: record.timestamp,
          acknowledged: false,
        };
      case 'agent.failed':
        return {
          attentionId: `att-${String(record.activityId)}`,
          reason: 'attention-required',
          severity: 'high',
          message: record.payload.error?.message ?? 'Agent failed',
          actor: record.actor,
          workflowRunId: record.workflowRunId,
          taskId: record.taskId,
          timestamp: record.timestamp,
          acknowledged: false,
        };
      case 'interaction.presented': {
        // Extract interaction metadata from payload.data
        const data = record.payload.data as Record<string, unknown> | undefined;
        const interactionId = typeof data?.interactionId === 'string' ? data.interactionId : undefined;
        const content = typeof data?.content === 'string' ? data.content : record.payload.message;
        return {
          attentionId: `att-interaction-${interactionId ?? String(record.activityId)}`,
          reason: 'interaction-presented',
          severity: 'medium',
          message: content ?? 'Decision needed',
          actor: record.actor,
          interactionId,
          timestamp: record.timestamp,
          acknowledged: false,
        };
      }
      default:
        return undefined;
    }
  }

  // ─── Contextual Capabilities ──────────────────────────────

  private buildContextualCapabilities(participants: ParticipantProjection[]): ContextualCapabilities {
    return {
      mentionableParticipants: participants
        .filter((p) => p.membership === 'joined')
        .map((p) => ({
          participantId: p.participantId,
          displayName: p.displayName,
          type: p.type,
        })),
      availableCommands: [
        { command: '/status', description: 'Show current workflow status' },
        { command: '/retry', description: 'Retry failed task' },
      ],
      referenceableEntities: this.buildReferenceableEntities(),
    };
  }

  private buildReferenceableEntities(): ContextualCapabilities['referenceableEntities'] {
    const entities: Array<{ entityId: string; entityType: 'workflow' | 'task' | 'artifact'; displayName: string }> = [];

    for (const [id, summary] of this.workflowSummaries) {
      entities.push({
        entityId: id,
        entityType: 'workflow',
        displayName: `Workflow ${summary.status}`,
      });
    }

    return entities;
  }
}

/**
 * M9 → Projection Record Conversion
 *
 * Converts M9 ActivityRecords to the discriminated-union ActivityRecord
 * format used by the ActivityStreamHub and M11A/M11B projection layers.
 *
 * Extracted from apps/api/src/routes/activity-room-m11a.ts and
 * apps/api/src/routes/activity-room-m11b.ts to eliminate duplication.
 *
 * Architecture Traceability:
 *   ARX-015: M11A/M11B projection composition
 */

import type { ActivityRecord } from './contracts';
import type { ActivityRecord as M9ActivityRecord } from './m9-types';

/**
 * Map M9 activity types to projection ActivityRecord kinds.
 */
const KIND_MAP: Record<string, ActivityRecord['kind']> = {
  'workflow.started': 'workflow',
  'workflow.completed': 'workflow',
  'workflow.failed': 'workflow',
  'workflow.cancelled': 'workflow',
  'task.runnable': 'task',
  'task.started': 'task',
  'task.completed': 'task',
  'task.failed': 'task',
  'task.cancelled': 'task',
  'agent.assigned': 'agent-message',
  'agent.started': 'agent-message',
  'agent.progress': 'agent-message',
  'agent.waiting': 'agent-message',
  'agent.completed': 'agent-message',
  'agent.failed': 'agent-message',
  'agent.cancelled': 'agent-message',
  'tool.called': 'tool-call',
  'tool.succeeded': 'tool-result',
  'tool.failed': 'tool-result',
  'human.message': 'agent-message',
  'system.event': 'workflow',
  'interaction.presented': 'agent-message',
  'interaction.responded': 'agent-message',
};

/**
 * Convert an M9 ActivityRecord to the projection ActivityRecord format
 * used by the ActivityStreamHub for broadcasting.
 *
 * This is a lossy conversion — M9 records carry richer metadata than the
 * discriminated union projection format. The conversion preserves the
 * essential fields needed for UI rendering.
 */
export function toProjectionRecord(record: M9ActivityRecord): ActivityRecord {
  const kind = KIND_MAP[record.type] ?? 'workflow';
  const actor = {
    type: record.actor.type,
    id: record.actor.id,
    displayName: record.actor.displayName,
    ...(record.actorId ? { role: record.actorId } : {}),
  };
  const agentId = record.actor.type === 'agent' ? record.actor.id : '';
  const data = record.payload?.data as Record<string, unknown> | undefined;
  const callID = (data?.callID as string) ?? '';
  const toolName = (data?.toolName as string) ?? '';

  // Tool activities have a distinct shape from agent-message
  if (kind === 'tool-call') {
    return {
      id: String(record.activityId),
      sequence: record.sequenceNumber,
      timestamp: record.timestamp,
      actor,
      kind: 'tool-call',
      agentId,
      toolName,
      callID,
      evidenceRefs: [],
    };
  }
  if (kind === 'tool-result') {
    return {
      id: String(record.activityId),
      sequence: record.sequenceNumber,
      timestamp: record.timestamp,
      actor,
      kind: 'tool-result',
      agentId,
      toolName,
      callID,
      status: record.type === 'tool.failed' ? 'failed' : 'completed',
      evidenceRefs: [],
    };
  }

  return {
    id: String(record.activityId),
    sequence: record.sequenceNumber,
    timestamp: record.timestamp,
    actor,
    kind,
    agentId,
    messageKind: 'message',
    content: record.payload?.message ?? '',
    workflowId: record.workflowRunId,
    sessionId: undefined,
    evidenceRefs: [],
    ...(record.payload?.error ? { effect: 'intervention' as const } : {}),
    ...(record.payload?.output ? { output: record.payload.output } : {}),
  } as ActivityRecord;
}

/**
 * ARX-015 M9: Durable SQLite-backed Activity Store
 *
 * Persistence authority for the Activity Room. Records survive process restarts.
 * Deduplication by eventId is enforced at the database level, not just in-memory.
 * Monotonic sequence numbers are allocated from MAX(sequence)+1 in the database.
 *
 * This is the durable substrate. It is never an orchestration authority.
 */

import type {
  ActivityCursor,
  ActivityEvent,
  ActivityRecord,
  ActivityRecordId,
  M9ActivityStore as IActivityStore,
  M9ActivityQuery,
} from './m9-types';

/**
 * SQLite-backed Activity Store with durable persistence.
 * Uses sql.js Database interface for portability.
 */
export class SqliteActivityStore implements IActivityStore {
  private readonly db: any;

  constructor(db: any) {
    this.db = db;
    this.ensureSchema();
  }

  private ensureSchema(): void {
    this.db.run(`
      CREATE TABLE IF NOT EXISTS m9_activity_events (
        activity_id TEXT PRIMARY KEY,
        event_id TEXT NOT NULL UNIQUE,
        sequence_number INTEGER NOT NULL,
        type TEXT NOT NULL,
        timestamp TEXT NOT NULL,
        execution_id TEXT,
        trace_id TEXT,
        request_id TEXT,
        workflow_run_id TEXT,
        task_id TEXT,
        agent_assignment_id TEXT,
        repository_binding_id TEXT,
        runtime_session_binding_id TEXT,
        ai_binding_id TEXT,
        actor_type TEXT NOT NULL,
        actor_id TEXT,
        actor_display_name TEXT NOT NULL,
        source TEXT NOT NULL,
        payload_json TEXT NOT NULL,
        visibility TEXT NOT NULL DEFAULT 'all'
      );
      CREATE INDEX IF NOT EXISTS idx_m9_sequence ON m9_activity_events(sequence_number);
      CREATE INDEX IF NOT EXISTS idx_m9_event_id ON m9_activity_events(event_id);
      CREATE INDEX IF NOT EXISTS idx_m9_workflow_run ON m9_activity_events(workflow_run_id);
      CREATE INDEX IF NOT EXISTS idx_m9_execution ON m9_activity_events(execution_id);
      CREATE INDEX IF NOT EXISTS idx_m9_task ON m9_activity_events(task_id);
      CREATE INDEX IF NOT EXISTS idx_m9_type ON m9_activity_events(type);
      CREATE INDEX IF NOT EXISTS idx_m9_timestamp ON m9_activity_events(timestamp);
    `);
  }

  async append(event: ActivityEvent): Promise<ActivityRecord> {
    // Idempotency: same eventId returns existing record
    const existing = this.getByEventIdSync(event.eventId);
    if (existing) return existing;

    // Allocate monotonic sequence from database
    const sequenceNumber = this.allocateSequence();

    const activityId = `act-${sequenceNumber}-${event.eventId.slice(0, 8)}` as ActivityRecordId;

    const record: ActivityRecord = {
      activityId,
      eventId: event.eventId,
      sequenceNumber,
      type: event.type,
      timestamp: event.timestamp,
      executionId: event.executionId,
      traceId: event.traceId,
      requestId: event.requestId,
      workflowRunId: event.workflowRunId,
      taskId: event.taskId,
      agentAssignmentId: event.agentAssignmentId,
      repositoryBindingId: event.repositoryBindingId,
      runtimeSessionBindingId: event.runtimeSessionBindingId,
      aiBindingId: event.aiBindingId,
      actor: event.actor,
      actorId: event.actorId,
      source: event.source,
      payload: event.payload,
      visibility: event.visibility ?? 'all',
    };

    this.insertRecord(record);
    return record;
  }

  async query(q: M9ActivityQuery): Promise<readonly ActivityRecord[]> {
    const conditions: string[] = [];
    const params: unknown[] = [];

    if (q.workflowRunId !== undefined) {
      conditions.push('workflow_run_id = ?');
      params.push(q.workflowRunId);
    }
    if (q.executionId !== undefined) {
      conditions.push('execution_id = ?');
      params.push(q.executionId);
    }
    if (q.taskId !== undefined) {
      conditions.push('task_id = ?');
      params.push(q.taskId);
    }
    if (q.actor !== undefined) {
      conditions.push('actor_type = ?');
      params.push(q.actor);
    }
    if (q.actorId !== undefined) {
      conditions.push('actor_id = ?');
      params.push(q.actorId);
    }
    if (q.source !== undefined) {
      conditions.push('source = ?');
      params.push(q.source);
    }
    if (q.type !== undefined) {
      if (Array.isArray(q.type)) {
        conditions.push(`type IN (${q.type.map(() => '?').join(',')})`);
        params.push(...q.type);
      } else {
        conditions.push('type = ?');
        params.push(q.type);
      }
    }
    if (q.after !== undefined) {
      conditions.push('sequence_number > ?');
      params.push(q.after.sequenceNumber);
    }
    if (q.before !== undefined) {
      conditions.push('timestamp <= ?');
      params.push(q.before);
    }
    if (q.afterTimestamp !== undefined) {
      conditions.push('timestamp > ?');
      params.push(q.afterTimestamp);
    }

    const where = conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';
    const limit = q.limit !== undefined ? `LIMIT ${q.limit}` : '';

    const sql = `SELECT * FROM m9_activity_events ${where} ORDER BY sequence_number ASC ${limit}`;
    const rows = this.db.exec(sql, params)[0]?.values ?? [];

    return rows.map((row: unknown[]) => this.rowToRecord(row));
  }

  async getAfter(cursor: ActivityCursor): Promise<readonly ActivityRecord[]> {
    const rows =
      this.db.exec('SELECT * FROM m9_activity_events WHERE sequence_number > ? ORDER BY sequence_number ASC', [
        cursor.sequenceNumber,
      ])[0]?.values ?? [];

    return rows.map((row: unknown[]) => this.rowToRecord(row));
  }

  async getByEventId(eventId: string): Promise<ActivityRecord | undefined> {
    return this.getByEventIdSync(eventId);
  }

  async replay(from?: ActivityCursor, to?: ActivityCursor): Promise<readonly ActivityRecord[]> {
    const conditions: string[] = [];
    const params: unknown[] = [];

    if (from) {
      conditions.push('sequence_number > ?');
      params.push(from.sequenceNumber);
    }
    if (to) {
      conditions.push('sequence_number <= ?');
      params.push(to.sequenceNumber);
    }

    const where = conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';
    const sql = `SELECT * FROM m9_activity_events ${where} ORDER BY sequence_number ASC`;
    const rows = this.db.exec(sql, params)[0]?.values ?? [];

    return rows.map((row: unknown[]) => this.rowToRecord(row));
  }

  async rebuild(): Promise<readonly ActivityRecord[]> {
    // Rebuild returns all records in deterministic order.
    // Does NOT regenerate identity, sequencing, timestamps, or lineage.
    const rows = this.db.exec('SELECT * FROM m9_activity_events ORDER BY sequence_number ASC')[0]?.values ?? [];

    return rows.map((row: unknown[]) => this.rowToRecord(row));
  }

  async getCursor(): Promise<ActivityCursor | null> {
    const rows =
      this.db.exec(
        'SELECT event_id, sequence_number, timestamp FROM m9_activity_events ORDER BY sequence_number DESC LIMIT 1',
      )[0]?.values ?? [];

    if (rows.length === 0) return null;

    const row = rows[0];
    return {
      eventId: String(row[0]),
      sequenceNumber: Number(row[1]),
      timestamp: String(row[2]),
    };
  }

  async lastSequence(): Promise<number> {
    const result = this.db.exec('SELECT COALESCE(MAX(sequence_number), 0) FROM m9_activity_events');
    return Number(result[0]?.values?.[0]?.[0] ?? 0);
  }

  // ─── Private Helpers ──────────────────────────────────────

  private allocateSequence(): number {
    const result = this.db.exec('SELECT COALESCE(MAX(sequence_number), 0) + 1 FROM m9_activity_events');
    return Number(result[0]?.values?.[0]?.[0] ?? 1);
  }

  private insertRecord(record: ActivityRecord): void {
    this.db.run(
      `INSERT INTO m9_activity_events (
        activity_id, event_id, sequence_number, type, timestamp,
        execution_id, trace_id, request_id, workflow_run_id, task_id,
        agent_assignment_id, repository_binding_id, runtime_session_binding_id,
        ai_binding_id, actor_type, actor_id, actor_display_name,
        source, payload_json, visibility
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        record.activityId,
        record.eventId,
        record.sequenceNumber,
        record.type,
        record.timestamp,
        record.executionId ?? null,
        record.traceId ?? null,
        record.requestId ?? null,
        record.workflowRunId ?? null,
        record.taskId ?? null,
        record.agentAssignmentId ?? null,
        record.repositoryBindingId ?? null,
        record.runtimeSessionBindingId ?? null,
        record.aiBindingId ?? null,
        record.actor.type,
        record.actor.id,
        record.actor.displayName,
        record.source,
        JSON.stringify(record.payload),
        record.visibility,
      ],
    );
  }

  private getByEventIdSync(eventId: string): ActivityRecord | undefined {
    const rows = this.db.exec('SELECT * FROM m9_activity_events WHERE event_id = ?', [eventId])[0]?.values ?? [];

    if (rows.length === 0) return undefined;
    return this.rowToRecord(rows[0]);
  }

  private rowToRecord(row: unknown[]): ActivityRecord {
    return {
      activityId: String(row[0]) as ActivityRecordId,
      eventId: String(row[1]),
      sequenceNumber: Number(row[2]),
      type: String(row[3]) as ActivityRecord['type'],
      timestamp: String(row[4]),
      executionId: row[5] != null ? (String(row[5]) as any) : undefined,
      traceId: row[6] != null ? (String(row[6]) as any) : undefined,
      requestId: row[7] != null ? (String(row[7]) as any) : undefined,
      workflowRunId: row[8] != null ? (String(row[8]) as any) : undefined,
      taskId: row[9] != null ? (String(row[9]) as any) : undefined,
      agentAssignmentId: row[10] != null ? String(row[10]) : undefined,
      repositoryBindingId: row[11] != null ? (String(row[11]) as any) : undefined,
      runtimeSessionBindingId: row[12] != null ? (String(row[12]) as any) : undefined,
      aiBindingId: row[13] != null ? (String(row[13]) as any) : undefined,
      actor: {
        type: String(row[14]) as any,
        id: row[15] != null ? String(row[15]) : '',
        displayName: String(row[16]),
      },
      actorId: row[15] != null ? String(row[15]) : undefined,
      source: String(row[17]) as ActivityRecord['source'],
      payload: JSON.parse(String(row[18])),
      visibility: String(row[19]) as ActivityRecord['visibility'],
    };
  }
}

/**
 * Activity Room (AAR-001) API module.
 *
 * Owns the projection service, the durable append-only activity store, and the
 * broadcast hub for the Activity Room. The room persists every record to
 * `activity.db` (via the activity migration manifest) so it reconstructs its
 * state after a restart (production-readiness foundation 2: durable
 * continuity). The API never re-redacts or reinterprets stored records; it
 * serializes the normalized typed records as-is.
 */

import * as fs from 'node:fs';
import * as path from 'node:path';
import {
  ACTIVITY_MANIFEST,
  ActivityProjectionService,
  type ActivityStore,
  ActivityStreamHub,
  type ActivityStreamHubOptions,
  InMemoryActivityStore,
  SqliteActivityStore,
} from '@vestara/activity-room';
import { migrate } from '@vestara/sqlite-migrations';

export interface ActivityRoom {
  readonly store: ActivityStore;
  readonly service: ActivityProjectionService;
  readonly hub: ActivityStreamHub;
}

function persistDb(db: any, dbPath: string): void {
  try {
    const data = db.export();
    fs.mkdirSync(path.dirname(dbPath), { recursive: true });
    fs.writeFileSync(dbPath, Buffer.from(data));
  } catch {
    /* best-effort */
  }
}

/** In-memory room used by tests and as a pre-init fallback. */
export function createActivityRoom(hubOptions: ActivityStreamHubOptions = {}): ActivityRoom {
  const store = new InMemoryActivityStore();
  const hub = new ActivityStreamHub(hubOptions);
  const service = new ActivityProjectionService({
    store,
    onAppended: (record) => hub.broadcast(record),
  });
  return { store, service, hub };
}

/**
 * Initialize the durable Activity Room for a repo: open `activity.db`, run the
 * migration chain, and hydrate the working store so the room survives restart.
 * Call once at API boot before any route or WebSocket uses the room.
 */
export async function initActivityRoom(
  repoPath: string,
  hubOptions: ActivityStreamHubOptions = {},
): Promise<ActivityRoom> {
  const initSqlJs = (await import('sql.js')).default;
  const SQL = await initSqlJs();
  const dbPath = path.join(repoPath, '.vestara', 'activity.db');
  let db: any;
  try {
    if (fs.existsSync(dbPath)) {
      db = new SQL.Database(fs.readFileSync(dbPath));
    }
  } catch {
    /* corrupt or unreadable — start fresh */
  }
  db = db ?? new SQL.Database();

  migrate(db, ACTIVITY_MANIFEST, {
    persist: (migrated) => persistDb(migrated, dbPath),
  });

  const store = new SqliteActivityStore(db, {
    persist: () => persistDb(db, dbPath),
  });
  const hub = new ActivityStreamHub(hubOptions);
  const service = new ActivityProjectionService({
    store,
    onAppended: (record) => hub.broadcast(record),
  });
  room = { store, service, hub };
  return room;
}

let room: ActivityRoom | undefined;

/** Process-lifetime singleton shared by routes and the WebSocket handler. */
export function getActivityRoom(): ActivityRoom {
  room ??= createActivityRoom();
  return room;
}

/**
 * ARX-015 M11A — Production Activity Room Read API
 *
 * Read-only API boundary over frozen M9/M10 contracts.
 * Authority flow:
 *   Agent/Team authority (AgentStorage) → team membership, agent identity, AI binding
 *   M8 workflow truth → M9 durable activity → M10 projection → lifecycle state
 *   → M11A composition → Workspace UI
 *
 * Activity Room is a generic consumer of participant/team information.
 * It does NOT define teams, roles, or model bindings.
 *
 * Endpoints:
 *   GET /api/activity-room/v1/snapshot          — Room snapshot + authoritative cursor
 *   GET /api/activity-room/v1/activities        — Bounded/paginated historical activity retrieval
 *   GET /api/activity-room/v1/activities/:id    — Individual ActivityRecord retrieval
 *   GET /api/activity-room/v1/activities/aggregate/:id — Aggregate drill-down
 *   GET /api/activity-room/v1/participants      — Participant projection (authority + lifecycle)
 *   GET /api/activity-room/v1/attention         — Attention projection
 *   GET /api/activity-room/v1/workflow-summary  — Workflow summary projection
 *
 * All endpoints are read-only. No mutation of M8, M9, or M10 state.
 * No exposure of SQLite schema, OpenCode internals, or provider internals.
 */

import * as fs from 'node:fs';
import type * as http from 'node:http';
import * as path from 'node:path';
import type {
  ActivityCursor,
  ActivityRoomProjection,
  AttentionEntry,
  M9ActivityQuery,
  M9ActivityRecord,
  M9ActivityStore,
  ParticipantProjection,
  WorkflowSummary,
} from '@vestara/activity-room';
import { ActivityStreamHub, DurableActivityStore, ProjectionRuntime, toProjectionRecord } from '@vestara/activity-room';
import { json } from '../http/response';
import type { WorkspaceContext } from '../workspace-context';

// ─── Configuration ────────────────────────────────────────────────

const MAX_LIMIT = 100;
const DEFAULT_LIMIT = 50;
const MAX_CURSOR_AGE_MS = 5 * 60 * 1000; // 5 minutes

// ─── M11A Room State ────────────────────────────────────────────

/** Production-safe instrumentation counters (no PII, no SQL content). */
export interface M11AInstrumentation {
  /** Total watcher poll cycles since boot */
  watcherPollCount: number;
  /** Watcher poll cycles that threw */
  watcherErrorCount: number;
  /** Watcher poll latency (last, avg, max) in ms */
  watcherLastLatencyMs: number;
  watcherAvgLatencyMs: number;
  watcherMaxLatencyMs: number;
  /** Timestamp of first watcher error (null if none) */
  firstWatcherErrorAt: string | null;
  /** Timestamp of last watcher error (null if none) */
  lastWatcherErrorAt: string | null;
  /** Total db.exec() calls (read path) */
  dbExecReadCount: number;
  /** Total db.exec() calls (write path — via auto-persist) */
  dbExecWriteCount: number;
  /** Total persistDb() calls (db.export() invocations) */
  persistDbCount: number;
  /** Total snapshot fetches served */
  snapshotFetchCount: number;
  /** Snapshot fetch latency (last, avg, max) in ms */
  snapshotLastLatencyMs: number;
  snapshotAvgLatencyMs: number;
  snapshotMaxLatencyMs: number;
  /** Timestamp of last successful snapshot */
  lastSnapshotAt: string | null;
  /** Current Node.js memory (heapUsed, rss) in bytes */
  processHeapUsedBytes: number;
  processRssBytes: number;
}

export interface M11ARoomState {
  store: M9ActivityStore;
  runtime: ProjectionRuntime;
  hub: ActivityStreamHub;
  lastProjection: ActivityRoomProjection | null;
  lastProjectionAt: number;
  instrumentation: M11AInstrumentation;
}

/** In-memory singleton for process lifetime. */
let m11aRoom: M11ARoomState | null = null;

/**
 * Initialize the M11A Activity Room for a repo.
 * Opens the M9 SQLite database and creates the M10 ProjectionRuntime.
 * Called once at API boot before any route uses the room.
 */
export async function initM11AActivityRoom(repoPath: string): Promise<M11ARoomState> {
  const initSqlJs = (await import('sql.js')).default;
  const SQL = await initSqlJs();
  const dbPath = path.join(repoPath, '.vestara', 'm9-activity.db');

  let db: any;
  try {
    if (fs.existsSync(dbPath)) {
      db = new SQL.Database(fs.readFileSync(dbPath));
    }
  } catch {
    /* corrupt or unreadable — start fresh */
  }
  db = db ?? new SQL.Database();

  // Auto-persist on write operations — intercept db.run for INSERT/UPDATE/DELETE.
  // db.exec is used for reads (SELECT) and schema DDL; only db.run is used for
  // writes by the DurableActivityStore, so we only need to intercept db.run.
  const origRun = db.run.bind(db);
  db.run = (sql: string, params?: any[]) => {
    origRun(sql, params);
    const trimmed = sql.trim().toUpperCase();
    if (trimmed.startsWith('INSERT') || trimmed.startsWith('UPDATE') || trimmed.startsWith('DELETE')) {
      persistDb(db, dbPath);
    }
  };

  // DurableActivityStore constructor calls ensureSchema() — no inline DDL needed.
  const store = new DurableActivityStore(db);
  const runtime = new ProjectionRuntime();
  const hub = new ActivityStreamHub({
    earliestAvailableSequence: 1,
    bufferCapacity: 128,
  });

  // Build initial projection
  const records = await store.rebuild();
  const projection = runtime.rebuild(records);

  m11aRoom = {
    store,
    runtime,
    hub,
    lastProjection: projection,
    lastProjectionAt: Date.now(),
    instrumentation: {
      watcherPollCount: 0,
      watcherErrorCount: 0,
      watcherLastLatencyMs: 0,
      watcherAvgLatencyMs: 0,
      watcherMaxLatencyMs: 0,
      firstWatcherErrorAt: null,
      lastWatcherErrorAt: null,
      dbExecReadCount: 0,
      dbExecWriteCount: 0,
      persistDbCount: 0,
      snapshotFetchCount: 0,
      snapshotLastLatencyMs: 0,
      snapshotAvgLatencyMs: 0,
      snapshotMaxLatencyMs: 0,
      lastSnapshotAt: null,
      processHeapUsedBytes: 0,
      processRssBytes: 0,
    },
  };

  // Start background watcher for new records (M11B realtime transport)
  startActivityWatcher(m11aRoom);

  return m11aRoom;
}

/** Process-lifetime singleton shared by routes. */
export function getM11ARoom(): M11ARoomState {
  if (!m11aRoom) {
    throw new Error('M11A Activity Room not initialized. Call initM11AActivityRoom first.');
  }
  return m11aRoom;
}

function persistDb(db: any, dbPath: string): void {
  if (m11aRoom) m11aRoom.instrumentation.persistDbCount++;
  try {
    const data = db.export();
    fs.mkdirSync(path.dirname(dbPath), { recursive: true });
    fs.writeFileSync(dbPath, Buffer.from(data));
  } catch {
    /* best-effort */
  }
}

/** Background watcher: polls M9 store for new records and broadcasts via hub. */
function startActivityWatcher(room: M11ARoomState): void {
  let lastKnownSequence = 0;
  const inst = room.instrumentation;

  // Initialize with current last sequence
  room.store
    .lastSequence()
    .then((seq) => {
      lastKnownSequence = seq ?? 0;
    })
    .catch(() => {
      lastKnownSequence = 0;
    });

  const interval = setInterval(async () => {
    const pollStart = Date.now();
    inst.watcherPollCount++;
    try {
      const currentSequence = await room.store.lastSequence();
      if (currentSequence === undefined || currentSequence <= lastKnownSequence) return;

      // Fetch new records
      const cursor: ActivityCursor = {
        sequenceNumber: lastKnownSequence,
        eventId: '',
        timestamp: '',
      };
      const newRecords = await room.store.getAfter(cursor);

      if (newRecords.length > 0) {
        // Broadcast each new record in order (convert to projection format)
        for (const record of newRecords) {
          room.hub.broadcast(toProjectionRecord(record));
        }
        lastKnownSequence = newRecords[newRecords.length - 1].sequenceNumber;
      }
      // Track watcher latency (success path)
      const elapsed = Date.now() - pollStart;
      inst.watcherLastLatencyMs = elapsed;
      inst.watcherAvgLatencyMs =
        (inst.watcherAvgLatencyMs * (inst.watcherPollCount - 1) + elapsed) / inst.watcherPollCount;
      inst.watcherMaxLatencyMs = Math.max(inst.watcherMaxLatencyMs, elapsed);
      // Update process memory snapshot
      const mem = process.memoryUsage();
      inst.processHeapUsedBytes = mem.heapUsed;
      inst.processRssBytes = mem.rss;
    } catch (error) {
      inst.watcherErrorCount++;
      const now = new Date().toISOString();
      if (!inst.firstWatcherErrorAt) inst.firstWatcherErrorAt = now;
      inst.lastWatcherErrorAt = now;
      console.error('[M11A] Activity watcher error:', error);
    }
  }, 500); // Poll every 500ms

  interval.unref?.();
}

// ─── Query Parsing & Validation ──────────────────────────────────

function integer(value: string | null): number | undefined {
  if (value === null) return undefined;
  const parsed = Number(value);
  return Number.isFinite(parsed) && Number.isInteger(parsed) ? parsed : undefined;
}

function stringValue(value: string | null): string | undefined {
  return value !== null && value.length > 0 ? value : undefined;
}

/** Parse and validate query parameters into M9ActivityQuery. */
function parseActivityQuery(url: URL): M9ActivityQuery {
  const params = url.searchParams;
  const limit = integer(params.get('limit'));
  const afterSeq = integer(params.get('afterSequence'));
  const beforeSeq = integer(params.get('beforeSequence'));
  const afterTimestamp = stringValue(params.get('afterTimestamp'));
  const beforeTimestamp = stringValue(params.get('beforeTimestamp'));
  const workflowRunId = stringValue(params.get('workflowRunId'));
  const executionId = stringValue(params.get('executionId'));
  const taskId = stringValue(params.get('taskId'));
  const actorType = stringValue(params.get('actorType'));
  const actorId = stringValue(params.get('actorId'));
  const type = stringValue(params.get('type'));
  const source = stringValue(params.get('source'));

  // Validate limit
  const validatedLimit = limit !== undefined ? Math.max(1, Math.min(MAX_LIMIT, limit)) : DEFAULT_LIMIT;

  // Validate cursor parameters
  if (afterSeq !== undefined && afterSeq < 0) {
    throw new Error('afterSequence must be non-negative');
  }
  if (beforeSeq !== undefined && beforeSeq < 0) {
    throw new Error('beforeSequence must be non-negative');
  }
  if (afterSeq !== undefined && beforeSeq !== undefined && afterSeq >= beforeSeq) {
    throw new Error('afterSequence must be less than beforeSequence');
  }

  // Build cursor if afterSequence provided
  let after: ActivityCursor | undefined;
  if (afterSeq !== undefined) {
    after = {
      sequenceNumber: afterSeq,
      eventId: '',
      timestamp: '',
    };
  }

  return {
    workflowRunId: workflowRunId as M9ActivityQuery['workflowRunId'],
    executionId: executionId as M9ActivityQuery['executionId'],
    taskId: taskId as M9ActivityQuery['taskId'],
    actor: actorType as M9ActivityQuery['actor'],
    actorId,
    type: type as M9ActivityQuery['type'],
    source: source as M9ActivityQuery['source'],
    after,
    before: beforeTimestamp,
    afterTimestamp,
    limit: validatedLimit,
  };
}

// ─── Response Helpers ────────────────────────────────────────────

/** Sanitize ActivityRecord for API response (strip internal fields). */
function sanitizeRecord(record: M9ActivityRecord): Record<string, unknown> {
  return {
    activityId: String(record.activityId),
    eventId: record.eventId,
    sequenceNumber: record.sequenceNumber,
    type: record.type,
    timestamp: record.timestamp,
    executionId: record.executionId,
    traceId: record.traceId,
    requestId: record.requestId,
    workflowRunId: record.workflowRunId,
    taskId: record.taskId,
    agentAssignmentId: record.agentAssignmentId,
    repositoryBindingId: record.repositoryBindingId,
    runtimeSessionBindingId: record.runtimeSessionBindingId,
    aiBindingId: record.aiBindingId,
    actor: record.actor,
    actorId: record.actorId,
    source: record.source,
    payload: record.payload,
    visibility: record.visibility,
  };
}

/** Sanitize StreamItem for API response. */
function sanitizeStreamItem(item: ActivityRoomProjection['stream'][0]): Record<string, unknown> {
  return {
    streamItemId: item.streamItemId,
    activityId: item.activityId,
    sequenceNumber: item.sequenceNumber,
    kind: item.kind,
    importance: item.importance,
    actor: item.actor,
    content: item.content,
    timestamp: item.timestamp,
    workflowRunId: item.workflowRunId,
    executionId: item.executionId,
    taskId: item.taskId,
    aggregated: item.aggregated
      ? {
          count: item.aggregated.count,
          kind: item.aggregated.kind,
          summary: item.aggregated.summary,
          referencedActivityIds: item.aggregated.referencedActivityIds,
          sequenceRange: item.aggregated.sequenceRange,
        }
      : undefined,
    interaction: item.interaction
      ? {
          interactionId: item.interaction.interactionId,
          lifecycle: item.interaction.lifecycle,
          ...(item.interaction.choices ? { choices: item.interaction.choices } : {}),
          ...(item.interaction.selectedChoiceId ? { selectedChoiceId: item.interaction.selectedChoiceId } : {}),
          ...(item.interaction.respondingParticipantId
            ? { respondingParticipantId: item.interaction.respondingParticipantId }
            : {}),
          ...(item.interaction.respondingParticipantName
            ? { respondingParticipantName: item.interaction.respondingParticipantName }
            : {}),
        }
      : undefined,
  };
}

/** Sanitize ParticipantProjection for API response. */
function sanitizeParticipant(p: ParticipantProjection): Record<string, unknown> {
  return {
    participantId: p.participantId,
    type: p.type,
    displayName: p.displayName,
    modelDisplayName: p.modelDisplayName,
    role: p.role,
    modelId: p.modelId,
    providerId: p.providerId,
    teamId: p.teamId,
    teamName: p.teamName,
    membership: p.membership,
    presence: p.presence,
    workState: p.workState,
    currentAssignment: p.currentAssignment,
    joinedAt: p.joinedAt,
    lastActivityAt: p.lastActivityAt,
  };
}

/** Sanitize AttentionEntry for API response. */
function sanitizeAttention(a: AttentionEntry): Record<string, unknown> {
  return {
    attentionId: a.attentionId,
    reason: a.reason,
    severity: a.severity,
    message: a.message,
    actor: a.actor,
    workflowRunId: a.workflowRunId,
    taskId: a.taskId,
    timestamp: a.timestamp,
    acknowledged: a.acknowledged,
  };
}

/** Sanitize WorkflowSummary for API response. */
function sanitizeWorkflowSummary(w: WorkflowSummary): Record<string, unknown> {
  return {
    workflowRunId: w.workflowRunId,
    executionId: w.executionId,
    status: w.status,
    taskCount: w.taskCount,
    completedTasks: w.completedTasks,
    failedTasks: w.failedTasks,
    currentTask: w.currentTask,
    startedAt: w.startedAt,
    lastActivityAt: w.lastActivityAt,
  };
}

// ─── Authority Composition ────────────────────────────────────────

/**
 * Compose Activity Room participants from two authoritative sources:
 *
 * 1. M10 projection (lifecycle-derived): runtime presence, work state, current assignment
 * 2. Agent/Team authority (config-driven): agent identity, team membership, AI binding
 *
 * Agent/Team authority answers "who belongs in the room/team."
 * M10/lifecycle state answers "what is happening to/with that participant."
 *
 * Activity Room does NOT define teams, roles, or model bindings.
 * It consumes them from upstream AgentStorage/AgentTeam authorities.
 */
async function composeParticipants(
  ctx: WorkspaceContext,
  room: M11ARoomState,
): Promise<readonly ParticipantProjection[]> {
  // 1. Get lifecycle-derived participants from M10 projection
  if (Date.now() - room.lastProjectionAt > MAX_CURSOR_AGE_MS) {
    const records = await room.store.rebuild();
    room.lastProjection = room.runtime.rebuild(records);
    room.lastProjectionAt = Date.now();
  }
  const lifecycleParticipants = room.lastProjection?.participants ?? [];

  // Build lookup: participantId → lifecycle participant
  const lifecycleById = new Map<string, ParticipantProjection>();
  for (const p of lifecycleParticipants) {
    lifecycleById.set(p.participantId, p);
  }

  // 2. Get agent/team authority from AgentStorage
  const allAgents = await ctx.agents.listAgents();
  const allTeams = await ctx.agents.listTeams();

  // Build team membership map: agentId → { teamId, teamName }
  const teamByAgentId = new Map<string, { teamId: string; teamName: string }>();
  for (const team of allTeams) {
    // team.memberIds contains agent IDs
    for (const agentId of team.memberIds) {
      if (!teamByAgentId.has(agentId)) {
        teamByAgentId.set(agentId, { teamId: team.id, teamName: team.name });
      }
    }
    // Also check agent-side back-reference (teamId on agent definition)
    for (const agent of allAgents) {
      if (agent.teamId === team.id && !teamByAgentId.has(agent.id)) {
        teamByAgentId.set(agent.id, { teamId: team.id, teamName: team.name });
      }
    }
  }

  // 3. Build composed participant list
  const composed: ParticipantProjection[] = [];
  const seenIds = new Set<string>();

  // 3a. Add all configured agents from AgentStorage
  for (const agent of allAgents) {
    const participantId = `agent-${agent.id}`;
    const teamMembership = teamByAgentId.get(agent.id);
    const lifecycle = lifecycleById.get(participantId);

    if (lifecycle) {
      // Agent has lifecycle history — enrich with team/agent authority metadata
      composed.push({
        ...lifecycle,
        // Canonical identity: agent.name is the human-readable name (e.g. "Developer")
        // agent.id is the stable key (e.g. "agent-developer") — not suitable for display
        displayName: agent.name || agent.id,
        modelDisplayName: agent.model || undefined,
        role: agent.role || lifecycle.role,
        modelId: agent.model || lifecycle.modelId,
        providerId: agent.provider || lifecycle.providerId,
        // Team membership from AgentTeam authority
        teamId: teamMembership?.teamId ?? lifecycle.teamId,
        teamName: teamMembership?.teamName ?? lifecycle.teamName,
      });
    } else {
      // Agent configured but has no lifecycle history — render with idle state
      composed.push({
        participantId,
        type: 'agent' as const,
        displayName: agent.name || agent.id,
        modelDisplayName: agent.model || undefined,
        role: agent.role || undefined,
        modelId: agent.model || undefined,
        providerId: agent.provider || undefined,
        teamId: teamMembership?.teamId,
        teamName: teamMembership?.teamName,
        membership: 'joined' as const,
        presence: 'offline' as const,
        workState: 'available' as const,
        joinedAt: agent.createdAt,
        lastActivityAt: agent.createdAt,
      });
    }
    seenIds.add(participantId);
  }

  // 3b. Add human participants from lifecycle projection (not in AgentStorage)
  for (const p of lifecycleParticipants) {
    if (p.type === 'human' && !seenIds.has(p.participantId)) {
      composed.push(p);
      seenIds.add(p.participantId);
    }
  }

  return composed;
}

// ─── Route Handler ───────────────────────────────────────────────

/**
 * M11A Activity Room Read API.
 * All endpoints are read-only. No mutation of M8, M9, or M10 state.
 */
export async function handleM11AActivityRoomRoute(
  method: string,
  p: string,
  _req: http.IncomingMessage,
  res: http.ServerResponse,
  ctx: WorkspaceContext,
  _port: number,
  url: URL,
): Promise<boolean> {
  // The dispatcher invokes every handler for every request; return false early
  // for paths outside this route group so uninitialized rooms never break
  // unrelated endpoints (e.g. the 404 path or later-registered routes).
  if (!p.startsWith('/api/activity-room/v1')) return false;
  const room = getM11ARoom();

  // ─── GET /api/activity-room/v1/snapshot ──────────────────────
  // Room snapshot + authoritative cursor
  if (method === 'GET' && p === '/api/activity-room/v1/snapshot') {
    const snapStart = Date.now();
    // Refresh projection if stale
    if (Date.now() - room.lastProjectionAt > MAX_CURSOR_AGE_MS) {
      const records = await room.store.rebuild();
      room.lastProjection = room.runtime.rebuild(records);
      room.lastProjectionAt = Date.now();
    }

    const projection = room.lastProjection!;
    const participants = await composeParticipants(ctx, room);
    json(res, 200, {
      room: projection.room,
      participants: participants.map(sanitizeParticipant),
      stream: projection.stream.map(sanitizeStreamItem).slice(0, 50), // Bounded preview
      workflowSummary: projection.workflowSummary ? sanitizeWorkflowSummary(projection.workflowSummary) : null,
      attention: projection.attention.map(sanitizeAttention),
      contextualCapabilities: projection.contextualCapabilities,
      // Explicit cursor for reconnect
      cursor: projection.room.cursor,
    });
    // Track snapshot latency
    const snapElapsed = Date.now() - snapStart;
    room.instrumentation.snapshotFetchCount++;
    room.instrumentation.snapshotLastLatencyMs = snapElapsed;
    const sc = room.instrumentation.snapshotFetchCount;
    room.instrumentation.snapshotAvgLatencyMs =
      (room.instrumentation.snapshotAvgLatencyMs * (sc - 1) + snapElapsed) / sc;
    room.instrumentation.snapshotMaxLatencyMs = Math.max(room.instrumentation.snapshotMaxLatencyMs, snapElapsed);
    room.instrumentation.lastSnapshotAt = new Date().toISOString();
    return true;
  }

  // ─── GET /api/activity-room/v1/activities ────────────────────
  // Bounded/paginated historical activity retrieval
  if (method === 'GET' && p === '/api/activity-room/v1/activities') {
    try {
      const query = parseActivityQuery(url);
      const page = await room.store.query(query);

      json(res, 200, {
        records: page.map(sanitizeRecord),
        count: page.length,
        limit: query.limit ?? DEFAULT_LIMIT,
        // Cursor for next page
        nextCursor:
          page.length > 0
            ? {
                sequenceNumber: page[page.length - 1].sequenceNumber,
                eventId: page[page.length - 1].eventId,
                timestamp: page[page.length - 1].timestamp,
              }
            : null,
      });
    } catch (error) {
      json(res, 400, {
        error: { code: 'INVALID_QUERY', message: error instanceof Error ? error.message : 'Invalid query parameters' },
      });
    }
    return true;
  }

  // ─── GET /api/activity-room/v1/activities/after ──────────────
  // Cursor-based pagination (M9 sequence-based)
  if (method === 'GET' && p === '/api/activity-room/v1/activities/after') {
    try {
      const params = url.searchParams;
      const afterSeq = integer(params.get('afterSequence'));
      const afterEventId = stringValue(params.get('afterEventId'));
      const afterTimestamp = stringValue(params.get('afterTimestamp'));
      const limit = integer(params.get('limit')) ?? DEFAULT_LIMIT;

      if (afterSeq === undefined && !afterTimestamp) {
        json(res, 400, {
          error: { code: 'MISSING_CURSOR', message: 'afterSequence or afterTimestamp required' },
        });
        return true;
      }

      const cursor: ActivityCursor = {
        sequenceNumber: afterSeq ?? 0,
        eventId: afterEventId ?? '',
        timestamp: afterTimestamp ?? new Date(0).toISOString(),
      };

      const records = await room.store.getAfter(cursor);
      const limited = records.slice(0, limit);

      json(res, 200, {
        records: limited.map(sanitizeRecord),
        count: limited.length,
        limit,
        nextCursor:
          limited.length > 0
            ? {
                sequenceNumber: limited[limited.length - 1].sequenceNumber,
                eventId: limited[limited.length - 1].eventId,
                timestamp: limited[limited.length - 1].timestamp,
              }
            : null,
      });
    } catch (error) {
      json(res, 400, {
        error: {
          code: 'INVALID_CURSOR',
          message: error instanceof Error ? error.message : 'Invalid cursor parameters',
        },
      });
    }
    return true;
  }

  // ─── GET /api/activity-room/v1/activities/:id ────────────────
  // Individual ActivityRecord retrieval
  if (method === 'GET' && p.match(/^\/api\/activity-room\/v1\/activities\/[^/]+$/)) {
    const activityId = decodeURIComponent(p.split('/').pop()!);
    const record = await room.store.getByEventId(activityId);

    if (!record) {
      json(res, 404, {
        error: { code: 'NOT_FOUND', message: `Activity not found: ${activityId}` },
      });
      return true;
    }

    json(res, 200, { record: sanitizeRecord(record) });
    return true;
  }

  // ─── GET /api/activity-room/v1/activities/aggregate/:id ──────
  // Aggregate drill-down using referencedActivityIds / sequenceRange
  if (method === 'GET' && p.match(/^\/api\/activity-room\/v1\/activities\/aggregate\/[^/]+$/)) {
    const streamItemId = decodeURIComponent(p.split('/').pop()!);

    // Fetch recent records to find the aggregated stream item
    const recentRecords = await room.store.query({ limit: 500 });
    const projection = room.runtime.rebuild(recentRecords);

    const aggregatedItem = projection.stream.find((s) => s.aggregated !== undefined && s.streamItemId === streamItemId);

    if (!aggregatedItem?.aggregated) {
      json(res, 404, {
        error: { code: 'NOT_FOUND', message: `Aggregated activity not found: ${streamItemId}` },
      });
      return true;
    }

    // Retrieve all underlying M9 records via referencedActivityIds
    const referencedIds = aggregatedItem.aggregated.referencedActivityIds;
    const underlyingRecords: M9ActivityRecord[] = [];

    for (const refId of referencedIds) {
      const record = await room.store.getByEventId(refId);
      if (record) {
        underlyingRecords.push(record);
      }
    }

    // Also support sequenceRange fallback
    let rangeRecords: M9ActivityRecord[] = [];
    if (underlyingRecords.length === 0 && aggregatedItem.aggregated.sequenceRange) {
      const { first, last } = aggregatedItem.aggregated.sequenceRange;
      rangeRecords = (await room.store.query({ limit: last - first + 1 })).filter(
        (r) => r.sequenceNumber >= first && r.sequenceNumber <= last,
      );
    }

    const allUnderlying = [...underlyingRecords, ...rangeRecords];
    const uniqueRecords = Array.from(new Map(allUnderlying.map((r) => [r.sequenceNumber, r])).values()).sort(
      (a, b) => a.sequenceNumber - b.sequenceNumber,
    );

    json(res, 200, {
      aggregate: {
        streamItemId: aggregatedItem.streamItemId,
        count: aggregatedItem.aggregated.count,
        kind: aggregatedItem.aggregated.kind,
        summary: aggregatedItem.aggregated.summary,
        sequenceRange: aggregatedItem.aggregated.sequenceRange,
      },
      underlyingRecords: uniqueRecords.map(sanitizeRecord),
      count: uniqueRecords.length,
    });
    return true;
  }

  // ─── GET /api/activity-room/v1/participants ──────────────────
  // Participant projection — composed from Agent/Team authority + lifecycle state
  if (method === 'GET' && p === '/api/activity-room/v1/participants') {
    const participants = await composeParticipants(ctx, room);
    json(res, 200, {
      participants: participants.map(sanitizeParticipant),
      count: participants.length,
    });
    return true;
  }

  // ─── GET /api/activity-room/v1/attention ─────────────────────
  // Attention projection
  if (method === 'GET' && p === '/api/activity-room/v1/attention') {
    if (Date.now() - room.lastProjectionAt > MAX_CURSOR_AGE_MS) {
      const records = await room.store.rebuild();
      room.lastProjection = room.runtime.rebuild(records);
      room.lastProjectionAt = Date.now();
    }

    const projection = room.lastProjection!;
    json(res, 200, {
      attention: projection.attention.map(sanitizeAttention),
      count: projection.attention.length,
    });
    return true;
  }

  // ─── GET /api/activity-room/v1/workflow-summary ──────────────
  // Workflow summary projection
  if (method === 'GET' && p === '/api/activity-room/v1/workflow-summary') {
    if (Date.now() - room.lastProjectionAt > MAX_CURSOR_AGE_MS) {
      const records = await room.store.rebuild();
      room.lastProjection = room.runtime.rebuild(records);
      room.lastProjectionAt = Date.now();
    }

    const projection = room.lastProjection!;
    if (projection.workflowSummary) {
      json(res, 200, { workflowSummary: sanitizeWorkflowSummary(projection.workflowSummary) });
    } else {
      json(res, 200, { workflowSummary: null });
    }
    return true;
  }

  return false;
}

