/**
 * @vestara/api — Workspace Runtime HTTP + WebSocket gateway
 *
 * Architecture Traceability:
 *   PCS: PCS-010 — Workspace UI
 *   Runtime: VESTARA-KERNEL.md → Boot Sequence
 */

import * as fs from 'node:fs';
import * as path from 'node:path';
import { M9IngestionBridge } from '@vestara/activity-room';
import type { WorkspaceEvent } from '@vestara/events';
import { initActivityRoom } from './activity-room';
import { createAgentLifecycleBridge } from './bridges/agent-lifecycle-bridge';
import { startOpencodeSupervisor } from './opencode-supervisor';
import { getM11ARoom, initM11AActivityRoom } from './routes/activity-room-m11a';
import { initTelegramRoute } from './routes/telegram';
import { type ApiServer, createServer } from './server';
import { createWorkspaceContext } from './workspace-context';

// ─── Boot Waterfall Instrumentation ───────────────────────
const BOOT_T0 = process.hrtime.bigint();
const bootLog: Array<{ phase: string; elapsedMs: number }> = [];
function bootMark(phase: string): void {
  const ns = process.hrtime.bigint() - BOOT_T0;
  const ms = Number(ns) / 1_000_000;
  bootLog.push({ phase, elapsedMs: Math.round(ms) });
  console.log(`[boot] ${phase} — ${Math.round(ms)}ms`);
}
bootMark('process-spawned');

/**
 * Resolve the repo root relative to the API server's own location.
 *
 * The compiled server lives at `apps/api/dist/index.js`, so the project
 * root is two levels up: `apps/api/dist/` → `apps/api/` → project root.
 * We walk upward from there looking for `.vestara/workspace.json`.
 *
 * The `VESTARA_REPO` env var overrides the search entirely.
 */
function resolveRepoRoot(envOverride?: string): string {
  if (envOverride) return path.resolve(envOverride);
  // __dirname = apps/api/dist/ in compiled output.
  // Start one level above apps/api/ to avoid finding the API's own .vestara/.
  let dir = path.resolve(__dirname, '..', '..');
  const root = path.parse(dir).root;
  while (dir !== root) {
    if (fs.existsSync(path.join(dir, '.vestara', 'workspace.json'))) {
      return dir;
    }
    dir = path.dirname(dir);
  }
  // Fallback to the directory containing the API
  return path.resolve(__dirname, '..', '..');
}

async function main(): Promise<void> {
  bootMark('entrypoint-entered');
  const port = Number(process.env.VESTARA_API_PORT ?? 3001);
  const repoPath = resolveRepoRoot(process.env.VESTARA_REPO);
  bootMark('config-loaded');

  const pending: WorkspaceEvent[] = [];
  let broadcast: ((e: WorkspaceEvent) => void) | null = null;

  const publish = (event: WorkspaceEvent): void => {
    if (broadcast) broadcast(event);
    else pending.push(event);
  };

  console.log(`[api] opening workspace at ${repoPath}...`);
  bootMark('composition-begin');
  const ctx = await createWorkspaceContext(repoPath, publish);
  bootMark('composition-end');

  await initActivityRoom(repoPath);
  bootMark('activity-room-init');

  await initM11AActivityRoom(repoPath);
  bootMark('m11a-init');

  // VES-LEAN-003A: Gate Telegram by dogfood profile
  if (process.env.VESTARA_RUNTIME_PROFILE !== 'dogfood') {
    await initTelegramRoute(path.join(repoPath, '.vestara', 'telegram.db'), ctx);
  }
  bootMark('telegram-init');

  // M11C-I1: Start M9 ingestion bridge — single EventBus → M9 write boundary
  const m11aRoom = getM11ARoom();
  const m9Bridge = new M9IngestionBridge({
    store: m11aRoom.store,
    eventBus: ctx.kernel.eventBus,
    logger: ctx.kernel.logger,
  });
  m9Bridge.start();
  bootMark('m9-bridge-started');

  // ARX-015: Agent lifecycle bridge — maps harness.* → canonical agent:started/completed
  // for M9 ingestion. Resolves model metadata from AgentStorage so participants
  // display the assigned model name rather than a generic role label.
  const _unsubAgentLifecycle = createAgentLifecycleBridge({
    eventBus: ctx.kernel.eventBus,
    agentModelResolver: {
      async resolve({ agentId }) {
        try {
          const stored = await ctx.agents.listAgents();
          const agent = stored.find((a) => a.id === agentId || a.runtimeAgent === agentId || a.role === agentId);
          if (agent) {
            return {
              providerId: agent.provider || undefined,
              modelId: agent.model || undefined,
              role: agent.role || agentId,
              displayName: agent.name || agentId,
              modelDisplayName: agent.model || agent.name || agentId,
            };
          }
        } catch {
          /* best-effort */
        }
        return undefined;
      },
    },
  });
  bootMark('agent-lifecycle-bridge-started');

  // Idle-based OpenCode stop + on-demand restart (releases ~526 MB when idle).
  if (process.env.VESTARA_OPENCODE_SUPERVISOR !== '0') {
    startOpencodeSupervisor();
    console.log(
      `[api] opencode supervisor active (idle stop ${process.env.VESTARA_OPENCODE_IDLE_STOP_MS ?? 1800000} ms)`,
    );
  }
  bootMark('opencode-supervisor');

  const server = createServer(ctx, port) as ApiServer;
  broadcast = (e) => server.broadcast(e);
  for (const e of pending) server.broadcast(e);
  bootMark('routes-registered');

  server.listen(port, () => {

/**
 * ARX-015: Agent Lifecycle Bridge
 *
 * Subscribes to harness/runtime lifecycle events (`harness.*`) and re-emits
 * canonical agent lifecycle events (`agent:started`, `agent:completed`) on the
 * EventBus. This is the integration boundary between harness-internal event
 * namespaces and the canonical Activity Room agent lifecycle contract.
 *
 * The bridge resolves model/provider metadata from AgentStorage so the M9
 * durable record carries enough identity for M10 to project agent participants
 * with their assigned model name.
 *
 * Design constraints:
 *   - Does NOT modify the harness event contract
 *   - Does NOT create a second participant authority
 *   - Preserves stable agent identity (agentId) independently from model display
 *   - Follows the OrchestrationEventBridge composition-root pattern
 */

import type { EventBus } from '@vestara/event-bus';
import type { VestaraEvent } from '@vestara/shared';

/** Minimal interface for resolving agent model configuration. */
export interface AgentModelResolver {
  resolve(input: { agentId: string }): Promise<
    | {
        providerId?: string;
        modelId?: string;
        role?: string;
        displayName?: string;
        modelDisplayName?: string;
      }
    | undefined
  >;
}

export interface AgentLifecycleBridgeOptions {
  readonly eventBus: EventBus;
  readonly agentModelResolver: AgentModelResolver;
}

/** Identity fields carried in harness.* event payloads. */
interface HarnessIdentity {
  readonly agentId?: unknown;
  readonly threadId?: unknown;
  readonly turnId?: unknown;
  readonly runId?: unknown;
  readonly correlationId?: unknown;
  readonly causationId?: unknown;
}

/**
 * Create the Agent lifecycle bridge. Returns an unsubscribe function.
 *
 * The bridge subscribes to `harness.*` events and:
 *   1. Filters to turn lifecycle events (started/completed/cancelled)
 *   2. Resolves the agent's model configuration
 *   3. Emits canonical `agent:started`/`agent:completed` events
 *
 * The M9IngestionBridge then ingests these canonical events normally.
 */
export function createAgentLifecycleBridge(options: AgentLifecycleBridgeOptions): () => void {
  const handler = async (event: VestaraEvent): Promise<void> => {
    try {
      const payload = event.payload as HarnessIdentity & Record<string, unknown>;
      const agentId = typeof payload.agentId === 'string' && payload.agentId ? payload.agentId : '';
      if (!agentId) return;

      // Map harness event types to canonical agent lifecycle types
      const lifecycleType = mapHarnessToLifecycle(event.type);
      if (!lifecycleType) return;

      // Resolve model metadata from agent configuration
      const resolved = await options.agentModelResolver.resolve({ agentId });

      // displayName = canonical identity (agentId for unnamed agents)
      // modelDisplayName = presentation-only model name (for unnamed AI fallback)
      const modelDisplayName = resolved?.modelDisplayName || resolved?.displayName;

      // Emit canonical agent lifecycle event for M9 bridge ingestion
      await options.eventBus
        .emit({
          type: `agent:${lifecycleType}`,
          source: 'agent-lifecycle-bridge',
          actor: { id: agentId, role: 'agent' },
          payload: {
            agentId,
            displayName: agentId,
            modelDisplayName,
            role: resolved?.role || agentId,
            modelId: resolved?.modelId,
            providerId: resolved?.providerId,
            task: (payload as Record<string, unknown>).instruction ?? (payload as Record<string, unknown>).task,
          },
          metadata: {
            correlationId:
              typeof payload.correlationId === 'string' ? payload.correlationId : event.metadata?.correlationId,
            causationId: typeof payload.causationId === 'string' ? payload.causationId : event.metadata?.causationId,
            executionId: event.metadata?.executionId,
            traceId: event.metadata?.traceId,
          },
        })
        .catch(() => {
          /* bridge failures must never break the harness run */
        });
    } catch {
      /* best-effort — swallow all errors */
    }
  };

  return options.eventBus.subscribe('harness.*', handler);
}

/**
 * Map harness event types to canonical agent lifecycle types.
 * Returns undefined for events that don't represent agent lifecycle transitions.
 */
function mapHarnessToLifecycle(type: string): 'started' | 'completed' | 'failed' | 'cancelled' | 'progress' | null {
  if (type === 'harness.turn.started') return 'started';
  if (type === 'harness.outcome.completed') return 'completed';
  if (type === 'harness.outcome.failed') return 'failed';
  if (type === 'harness.outcome.cancelled') return 'cancelled';
  if (type === 'harness.model.started') return 'progress';
  return null;
}

