import type { ConversationListPage, ConversationStore } from '@vestara/conversation';
import type { Logger } from '@vestara/logger';
import type { Conversation, ConversationStatus, ConversationSummary, Message, ToolObservation } from '@vestara/shared';
import { migrate } from '@vestara/sqlite-migrations';
import { CONVERSATION_MANIFEST } from './migrations';

let SQL: any = null;

async function getDb(): Promise<any> {
  if (SQL) return SQL;
  const { getSql } = await import('@vestara/shared');
  SQL = await getSql();
  return SQL;
}

function dbRun(db: any, sql: string, params?: any[]): void {
  const stmt = db.prepare(sql);
  if (params) stmt.bind(params);
  stmt.step();
  stmt.free();
}

function dbGet(db: any, sql: string, params?: any[]): any {
  const stmt = db.prepare(sql);
  if (params) stmt.bind(params);
  const result = stmt.step() ? stmt.getAsObject() : null;
  stmt.free();
  return result;
}

function dbAll(db: any, sql: string, params?: any[]): any[] {
  const results: any[] = [];
  const stmt = db.prepare(sql);
  if (params) stmt.bind(params);
  while (stmt.step()) results.push(stmt.getAsObject());
  stmt.free();
  return results;
}

/**
 * GA-TOOL-UX-001B: parse the persisted `tool_observations_json` column.
 * Returns the observations when the payload is a non-empty array of
 * minimally-shaped observations, else undefined (absent/malformed payloads
 * degrade to no observations — never a crash, never partial garbage).
 */
function parseToolObservations(value: unknown): readonly ToolObservation[] | undefined {
  if (typeof value !== 'string' || value.length === 0) return undefined;
  let parsed: unknown;
  try {
    parsed = JSON.parse(value);
  } catch {
    return undefined;
  }
  if (!Array.isArray(parsed) || parsed.length === 0) return undefined;
  const observations = parsed.filter(
    (item): item is ToolObservation =>
      !!item &&
      typeof item === 'object' &&
      typeof (item as Record<string, unknown>).toolCallId === 'string' &&
      typeof (item as Record<string, unknown>).toolName === 'string' &&
      typeof (item as Record<string, unknown>).timestamp === 'string' &&
      typeof (item as Record<string, unknown>).content === 'string',
  );
  return observations.length > 0 ? observations : undefined;
}

/**
 * SQLite-backed `ConversationStore` for `@vestara/conversation`. Persists the
 * conversation + message rows so chat history survives restart. Uses the same
 * sql.js pattern as `SqliteConversationSessionStore`; each store owns its own
 * tables so they can share a dbPath without interfering.
 */
export class SqliteConversationStore implements ConversationStore {
  private db: any;
  private logger?: Logger;
  private initialized = false;
  private dbPath?: string;

  constructor(options?: { dbPath?: string; logger?: Logger }) {
    this.dbPath = options?.dbPath;
    this.logger = options?.logger?.child({ component: 'conversation-store' });
  }

  async initialize(): Promise<void> {
    if (this.initialized) return;
    const sql = await getDb();
    const fs = await import('node:fs');
    if (this.dbPath) {
      try {
        const buffer = fs.readFileSync(this.dbPath);
        this.db = new sql.Database(buffer);
      } catch {
        this.db = new sql.Database();
      }
    } else {
      this.db = new sql.Database();
    }

    migrate(this.db, CONVERSATION_MANIFEST, {
      persist: (migrated) => {
        if (this.dbPath) {
          fs.writeFileSync(this.dbPath, Buffer.from(migrated.export()));
        }
      },
    });
    this.initialized = true;
  }

  private async _db(): Promise<any> {
    await this.initialize();
    return this.db;
  }

  async create(conversation: Conversation): Promise<void> {
    const db = await this._db();
    dbRun(
      db,
      `INSERT INTO conversations (id, user_id, title, status, created_at, updated_at, runtime_session_id) VALUES (?, ?, ?, ?, ?, ?, ?)`,
      [
        conversation.id,
        conversation.userId,
        conversation.title,
        conversation.status,
        conversation.createdAt,
        conversation.updatedAt,
        conversation.runtimeSessionId ?? null,
      ],
    );
    this._persist();
  }

  /** Unbounded read — returns the complete conversation. Retained for backward compatibility. */
  async get(id: string): Promise<Conversation | null> {
    const db = await this._db();
    const row = dbGet(db, 'SELECT * FROM conversations WHERE id = ?', [id]);
    if (!row) return null;
    const messages = dbAll(
      db,
      'SELECT * FROM conversation_messages WHERE conversation_id = ? ORDER BY created_at, rowid',
      [id],
    );
    return {
      id: row.id as string,
      userId: row.user_id as string,
      title: row.title as string,
      status: row.status as ConversationStatus,
      runtimeSessionId: (row.runtime_session_id as string) || undefined,
      createdAt: row.created_at as string,
      updatedAt: row.updated_at as string,
      messages: messages.map((m) => this._rowToMessage(m)),
    };
  }

  /**
   * VES-PERF-001B: Bounded newest-window-first read.
   *
   * Defaults to the newest 50 messages. Messages are always returned in
   * chronological order regardless of `order`; `order: 'desc'` selects the
   * newest window (used for initial load and older-page loading), `order: 'asc'`
   * selects the oldest window.
   */
  async getConversation(
    id: string,
    options?: { limit?: number; offset?: number; order?: 'asc' | 'desc' },
  ): Promise<Conversation | null> {
    const db = await this._db();
    const row = dbGet(db, 'SELECT * FROM conversations WHERE id = ?', [id]);
    if (!row) return null;

    const limit = options?.limit ?? 50;
    const offset = options?.offset ?? 0;
    const newestFirst = (options?.order ?? 'desc') === 'desc';

    // Select the window (newest-first when requested) then normalize to chronological.
    const window = dbAll(
      db,
      `SELECT * FROM conversation_messages WHERE conversation_id = ? ORDER BY created_at ${newestFirst ? 'DESC' : 'ASC'}, rowid ${newestFirst ? 'DESC' : 'ASC'} LIMIT ? OFFSET ?`,
      [id, limit, offset],
    );
    const messages = newestFirst ? window.reverse() : window;

    const countRow = dbGet(db, 'SELECT COUNT(*) as count FROM conversation_messages WHERE conversation_id = ?', [id]);
    const totalCount = (countRow?.count as number) ?? 0;

    return {
      id: row.id as string,
      userId: row.user_id as string,
      title: row.title as string,
      status: row.status as ConversationStatus,
      runtimeSessionId: (row.runtime_session_id as string) || undefined,
      createdAt: row.created_at as string,
      updatedAt: row.updated_at as string,
      messages: messages.map((m) => this._rowToMessage(m)),
      _pagination: {
        total: totalCount,
        offset,
        limit,
        hasMore: offset + limit < totalCount,
      },
    };
  }

  async list(userId: string): Promise<ConversationSummary[]> {
    const db = await this._db();
    const rows = dbAll(
      db,
      `SELECT c.*, COUNT(m.id) AS message_count
       FROM conversations c
       LEFT JOIN conversation_messages m ON m.conversation_id = c.id
       WHERE c.user_id = ? AND c.status != 'deleted'
       GROUP BY c.id ORDER BY c.updated_at DESC`,
      [userId],
    );
    return rows.map((row: any) => ({
      id: row.id as string,
      title: row.title as string,
      messageCount: Number(row.message_count ?? 0),
      status: row.status as ConversationStatus,
      createdAt: row.created_at as string,
      updatedAt: row.updated_at as string,
      runtimeSessionId: (row.runtime_session_id as string) || undefined,
    }));
  }

  async listPage(userId: string, options?: { limit?: number; offset?: number }): Promise<ConversationListPage> {
    const db = await this._db();
    const limit = options?.limit ?? 25;
    const offset = options?.offset ?? 0;

    const countRow = dbGet(
      db,
      `SELECT COUNT(*) AS count FROM conversations c WHERE c.user_id = ? AND c.status != 'deleted'`,
      [userId],
    );
    const total = (countRow?.count as number) ?? 0;

    const rows = dbAll(
      db,
      `SELECT c.*, COUNT(m.id) AS message_count
       FROM conversations c
       LEFT JOIN conversation_messages m ON m.conversation_id = c.id
       WHERE c.user_id = ? AND c.status != 'deleted'
       GROUP BY c.id ORDER BY c.updated_at DESC LIMIT ? OFFSET ?`,
      [userId, limit, offset],
    );
    const conversations: ConversationSummary[] = rows.map((row: any) => ({
      id: row.id as string,
      title: row.title as string,
      messageCount: Number(row.message_count ?? 0),
      status: row.status as ConversationStatus,
      createdAt: row.created_at as string,
      updatedAt: row.updated_at as string,
      runtimeSessionId: (row.runtime_session_id as string) || undefined,
    }));

    return { conversations, total, offset, limit, hasMore: offset + limit < total };
  }

  async addMessage(conversationId: string, message: Message): Promise<void> {
    const db = await this._db();
    // GA-TOOL-UX-001B: durable tool observations ride the message row as
    // JSON (observations belong to the assistant message aggregate).
    // Legacy databases without the column fall back to the column-less
    // insert so old schemas keep working.
    const observationsJson =
      message.toolObservations && message.toolObservations.length > 0 ? JSON.stringify(message.toolObservations) : null;
    try {
      dbRun(
        db,
        `INSERT INTO conversation_messages
         (id, conversation_id, role, content, provider, model, tokens, cost, latency, created_at, tool_observations_json)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          message.id,
          conversationId,
          message.role,
          message.content,
          message.provider ?? null,
          message.model ?? null,
          message.tokens ?? null,
          message.cost ?? null,
          message.latency ?? null,
          message.createdAt,
          observationsJson,
        ],
      );
    } catch (error) {
      // Legacy databases predate the observations column: fall back to the
      // column-less insert (observations are dropped, messages are not).
      // Any other failure is real — rethrow instead of losing the message.
      if (!String((error as Error)?.message ?? error).includes('no such column')) throw error;
      dbRun(
        db,
        `INSERT INTO conversation_messages
         (id, conversation_id, role, content, provider, model, tokens, cost, latency, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          message.id,
          conversationId,
          message.role,
          message.content,
          message.provider ?? null,
          message.model ?? null,
          message.tokens ?? null,
          message.cost ?? null,
          message.latency ?? null,
          message.createdAt,
        ],
      );
    }
    dbRun(db, 'UPDATE conversations SET updated_at = ? WHERE id = ?', [message.createdAt, conversationId]);
    this._persist();
  }

  async setStatus(id: string, status: Conversation['status']): Promise<void> {
    const db = await this._db();
    dbRun(db, 'UPDATE conversations SET status = ? WHERE id = ?', [status, id]);
    this._persist();
  }

  async updateTitle(id: string, title: string): Promise<void> {
    const db = await this._db();
    dbRun(db, 'UPDATE conversations SET title = ?, updated_at = ? WHERE id = ?', [title, new Date().toISOString(), id]);
    this._persist();
  }

  async updateRuntimeSessionId(id: string, runtimeSessionId: string): Promise<void> {
    const db = await this._db();
    dbRun(db, 'UPDATE conversations SET runtime_session_id = ?, updated_at = ? WHERE id = ?', [
      runtimeSessionId,
      new Date().toISOString(),
      id,
    ]);
    this._persist();
  }

  async remove(id: string): Promise<void> {
    const db = await this._db();
    dbRun(db, 'DELETE FROM conversation_messages WHERE conversation_id = ?', [id]);
    dbRun(db, 'DELETE FROM conversations WHERE id = ?', [id]);
    this._persist();
  }

  private _rowToMessage(row: Record<string, unknown>): Message {
    // GA-TOOL-UX-001B: recover durable tool observations. Malformed or
    // non-array payloads degrade to absent (never a crash, never partial).
    const toolObservations = parseToolObservations(row.tool_observations_json);
    return {
      id: row.id as string,
      conversationId: row.conversation_id as string,
      role: row.role as Message['role'],
      content: row.content as string,
      provider: (row.provider as string) ?? undefined,
      model: (row.model as string) ?? undefined,
      tokens: (row.tokens as number) ?? undefined,
      cost: (row.cost as number) ?? undefined,
      latency: (row.latency as number) ?? undefined,
      createdAt: row.created_at as string,
      ...(toolObservations ? { toolObservations } : {}),
    };
  }

  private _persist(): void {
    if (!this.dbPath) return;
    try {
      const fs = require('node:fs') as typeof import('node:fs');
      const data = this.db.export();
      const buffer = Buffer.from(data);
      const dir = this.dbPath.substring(0, this.dbPath.lastIndexOf('/'));
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }
      fs.writeFileSync(this.dbPath, buffer);
    } catch {}
  }
}

