const READ_WRAPPER_RE =
  /^<path>([\s\S]*?)<\/path>\r?\n<type>([\s\S]*?)<\/type>\r?\n<content>\n([\s\S]*?)(?:<\/content>\s*)?$/;
const READ_LINE_RE = /^(\d+): ?(.*)$/;
const READ_TOTAL_RE = /\btotal (\d+) lines\b/;
const READ_TRUNCATION_RE = /truncat/i;

