export interface CompletionRequest {
  model: string;
  messages: Array<{
    role: 'system' | 'user' | 'assistant' | 'tool';
    content: string;
    toolCallId?: string;
    toolCalls?: Array<{ id: string; name: string; arguments: string }>;
  }>;
  temperature?: number;
  maxTokens?: number;
  stream?: boolean;
  tools?: ToolDefinition[];
  /** Caller-controlled cancellation: when aborted, the provider terminates the turn. */
  signal?: AbortSignal;
  /** Streaming execution events (runtime-normalized) as the turn progresses. */
  onExecutionEvent?: (event: ProviderExecutionEvent) => void;
  /** The runtime agent (e.g. vestara-planner) to run the completion as. */
  agent?: string;
  /** Semantic title for the execution session (e.g. task title, workflow title). */
  title?: string;
  /**
   * GA-RUNTIME-001: owning conversation identity. Set by the conversation
   * service (via the context assembler) so the executor can bind the turn's
   * OpenCode session to conversation-level continuity. Never browser-supplied.
   */
  conversationId?: string;
  /**
   * GA-RUNTIME-001: requested upstream provider ID (browser selection, bounded
   * server-side). Never trusted as execution authority — the executor resolves
   * it against the canonical provider discovery before execution.
   */
  provider?: string;
  /**
   * Trusted turn-time surface context (GA-CONTEXT-002). Additive and optional:
   * the current Workspace UI surface. Bounded server-side; treated as trusted
   * application context by the model — NEVER repository/execution authority.
   */
  surfaceContext?: TurnSurfaceContext;
  /** M7: Runtime session ID for session continuity. When set, the provider reuses the existing OpenCode session. */
  runtimeSessionId?: string;
  /**
   * Request structured JSON output: the provider forces the model to return
   * validated JSON matching this schema. When set, `CompletionResponse` carries
   * the parsed result in `structuredOutput`.
   */
  jsonSchema?: Record<string, unknown>;
  /**
   * GA-EXEC-001: per-turn execution configuration from the Global Assistant
   * UI. Carries Vestara-owned limits (turnTimeoutMs, maxOperations,
   * maxToolCalls) that the adapter enforces. OpenCode/provider-owned limits
   * (contextWindow, maxOutput) are NOT included — those remain at the
   * provider layer.
   *
   * undefined = use adapter defaults. Values override defaults per-turn.
   * Changes apply to subsequent turns, not mid-turn.
   */
  executionConfig?: GAExecutionConfig;
}

/**
 * GA-EXEC-001: Vestara-owned per-turn execution configuration for the
 * Global Assistant. All fields are optional; undefined = use adapter defaults.
 *
 * Ownership:
 *   - turnTimeoutMs: Vestara (adapter enforcement)
 *   - maxToolCalls: Vestara (adapter enforcement, tracks tool invocations)
 *
 * NOT included (provider-owned, not Vestara-controlled):
 *   - contextWindow (provider model property)
 *   - maxOutput (provider model property)
 *   - maxIterations (OpenCode server agent loop)
 *   - maxTokens (per-completion output cap, already in CompletionRequest.maxTokens)
 */
export interface GAExecutionConfig {
  /** Hard cap for a single turn in milliseconds. Default: 900000 (15 min). */
  readonly turnTimeoutMs?: number;
  /** Maximum tool invocations per turn. undefined = adapter default (30), 0 = unlimited, 1..200 = capped. */
  readonly maxToolCalls?: number;
}

/** Runtime-normalized execution event emitted while a completion runs. */
export interface ProviderExecutionEvent {
  readonly type:
    | 'agent.activity'
    | 'agent.progress'
    | 'tool.started'
    | 'tool.completed'
    | 'agent.completed'
    | 'agent.failed'
    | 'agent.cancelled';
  readonly state: string;
  readonly activity?: string;
  readonly at: string;
  readonly sessionId?: string;
}

export interface CompletionResponse {
  id: string;
  model: string;
  provider: string;
  content: string;
  toolCalls?: Array<{ id: string; name: string; arguments: string }>;
  /** Parsed structured output when `CompletionRequest.jsonSchema` was set. */
  structuredOutput?: unknown;
  usage: {
    promptTokens: number;
    completionTokens: number;
    totalTokens: number;
  };
  latency: number;
  /** How the provider resolved which upstream provider/model executed this completion (provenance). */
  resolution?: {
    /** Selected upstream provider id; undefined means the runtime's configured default. */
    providerId?: string;
    /** Why this resolution was chosen. */
    reason: 'preferred' | 'preferred-unavailable' | 'explicit-model' | 'explicit-unresolvable' | 'default';
    /** True when execution fell back to the runtime's configured/default resolution. */
    defaultResolution: boolean;
    /** GA-RUNTIME-001: the OpenCode session that carried this completion (set when one was acquired). */
    runtimeSessionId?: string;
  };
}

