/**
 * Activity Room Context Panel (Right Column)
 *
 * Renders operational context backed by authoritative data:
 * - Activity Metrics (total events, participants, active agents)
 * - Recent Operations (last 5 stream items)
 * - OpenCode Session Status (live from /api/opencode/session/status)
 * - Activity Stream Status (single truthful connection indicator)
 *
 * All data sources are READY/DERIVABLE from existing projections.
 * No mocks, no placeholders, no fabricated operational data.
 */

import type { M11CStreamItem } from '../../hooks/useM11CActivityRoom';
import type { M11CConnectionState } from '../../hooks/useM11CActivityRoom';
import { StatusIndicator } from '@vestara/ui';
import { formatRelative } from './activity-formatters';
import { CONNECTION_STATUS_CONFIG } from './status-config';
import { useSessionStatus } from '../../hooks/useSessionStatus';

display.text:
/**
 * Activity Room Context Panel (Right Column)
 *
 * Renders operational context backed by authoritative data:
 * - Activity Metrics (total events, participants, active agents)
 * - Recent Operations (last 5 stream items)
 * - OpenCode Session Status (live from /api/opencode/session/status)
 * - Activity Stream Status (single truthful connection indicator)
 *
 * All data sources are READY/DERIVABLE from existing projections.
 * No mocks, no placeholders, no fabricated operational data.
 */

import type { M11CStreamItem } from '../../hooks/useM11CActivityRoom';
import type { M11CConnectionState } from '../../hooks/useM11CActivityRoom';
import { StatusIndicator } from '@vestara/ui';
import { formatRelative } from './activity-formatters';
import { CONNECTION_STATUS_CONFIG } from './status-config';
import { useSessionStatus } from '../../hooks/useSessionStatus';

// ─── Types ───────────────────────────────────────────────────

interface ActivityRoomContextPanelProps {
  /** Stream items for metrics and recent operations. */
  readonly stream: readonly M11CStreamItem[];
  /** Participant count for metrics. */
  readonly participantCount: number;
  /** Active agent count for metrics. */
  readonly activeAgentCount: number;
  /** Connection state for stream status. */
  readonly connectionState: M11CConnectionState;
}

// ─── Severity Badge ──────────────────────────────────────────

function OperationBadge({ kind }: { readonly kind: string }) {
  // Map stream item kind to severity badge
  const badgeClass = (() => {
    switch (kind) {
      case 'conversation':
        return 'ar-operation__badge--info';
      case 'interaction':
        return 'ar-operation__badge--info';
      case 'activity':
        return 'ar-operation__badge--success';
      case 'progress':
        return 'ar-operation__badge--info';
      case 'log':
        return 'ar-operation__badge--warning';
      case 'error':
        return 'ar-operation__badge--error';
      default:
        return 'ar-operation__badge--info';
    }
  })();

  const label = (() => {
    switch (kind) {
      case 'conversation':
        return 'Message';
      case 'interaction':
        return 'Interaction';
      case 'activity':
        return 'Activity';
      case 'progress':
        return 'Progress';
      case 'log':
        return 'Event';
      case 'error':
        return 'Error';
      default:
        return kind;
    }
  })();

  return (
    <span className={`ar-operation__badge ${badgeClass}`}>
      {label}
    </span>
  );
}

// ─── Component ───────────────────────────────────────────────

export default function ActivityRoomContextPanel({
  stream,
  participantCount,
  activeAgentCount,
  connectionState,
}: ActivityRoomContextPanelProps) {
  // DERIVABLE: total events from stream length
  const totalEvents = stream.length;

  // DERIVABLE: recent operations (last 5 items)
  const recentOperations = stream.slice(-5).reverse();

  // READY: connection status from room.state
  const statusConfig = CONNECTION_STATUS_CONFIG[connectionState] ?? CONNECTION_STATUS_CONFIG.offline;

  // LIVE: OpenCode session status (polls /api/opencode/session/status)
  const { statusMap } = useSessionStatus({ intervalMs: 5_000 });
  const sessionEntries = Object.values(statusMap);
  const activeSessions = sessionEntries.filter((s) => s === 'active').length;
  const idleSessions = sessionEntries.filter((s) => s === 'idle').length;
  const failedSessions = sessionEntries.filter((s) => s === 'failed').length;

  return (
    <div className="ar-context" role="region" aria-label="Operational context">
      {/* ── Activity Metrics ────────────────────────────────── */}
      <div className="ar-context__section">
        <div className="ar-context__section-header">
          <h3 className="ar-context__title">Activity Metrics</h3>
        </div>
        <div className="ar-context__metrics">
          <div className="ar-metric">
            <div className="ar-metric__icon ar-metric__icon--events">
              ◈
            </div>
            <div>
              <p className="ar-metric__value">{totalEvents}</p>
              <p className="ar-metric__label">Total Events</p>
            </div>
          </div>
          <div className="ar-metric">
            <div className="ar-metric__icon ar-metric__icon--participants">
              ●
            </div>
            <div>
              <p className="ar-metric__value">{participantCount}</p>
              <p className="ar-metric__label">Participants</p>
            </div>
          </div>
          <div className="ar-metric">
            <div className="ar-metric__icon ar-metric__icon--agents">
              ◉
            </div>
            <div>
              <p className="ar-metric__value">{activeAgentCount}</p>
              <p className="ar-metric__label">Active Agents</p>
            </div>
          </div>
        </div>
      </div>

      {/* ── Recent Operations ───────────────────────────────── */}
      <div className="ar-context__section">
        <div className="ar-context__section-header">
          <h3 className="ar-context__title">Recent Operations</h3>
        </div>
        <div className="ar-context__operations">
          {recentOperations.length === 0 ? (
            <div className="ar-operation__meta" style={{ padding: '0.375rem 0' }}>
              No recent operations
            </div>
          ) : (
            recentOperations.map((op) => (
              <div key={op.id} className="ar-operation">
                <div className="ar-operation__icon">
                  {op.actor.type === 'human' ? '✎' : '●'}
                </div>
                <div className="ar-operation__info">
                  <p className="ar-operation__name">
                    {op.content || op.kind}
                  </p>
                  <p className="ar-operation__meta">
                    {op.actor.displayName} · {formatRelative(op.timestamp)}
                  </p>
                </div>
                <OperationBadge kind={op.kind} />
              </div>
            ))
          )}
        </div>
      </div>

      {/* ── OpenCode Sessions ───────────────────────────────── */}
      {sessionEntries.length > 0 && (
        <div className="ar-context__section">
          <div className="ar-context__section-header">
            <h3 className="ar-context__title">OpenCode Sessions</h3>
          </div>
          <div className="ar-context__metrics">
            {activeSessions > 0 && (
              <div className="ar-metric">
                <div className="ar-metric__icon ar-metric__icon--agents">◉</div>
                <div>
                  <p className="ar-metric__value">{activeSessions}</p>
                  <p className="ar-metric__label">Active</p>
                </div>
              </div>
            )}
            {idleSessions > 0 && (
              <div className="ar-metric">
                <div className="ar-metric__icon ar-metric__icon--events">○</div>
                <div>
                  <p className="ar-metric__value">{idleSessions}</p>
                  <p className="ar-metric__label">Idle</p>
                </div>
              </div>
            )}
            {failedSessions > 0 && (
              <div className="ar-metric">
                <div className="ar-metric__icon ar-metric__icon--error">✕</div>
                <div>
                  <p className="ar-metric__value">{failedSessions}</p>
                  <p className="ar-metric__label">Failed</p>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* ── Activity Stream Status ──────────────────────────── */}
      <div className="ar-context__section">
        <div className="ar-context__section-header">
          <h3 className="ar-context__title">System Status</h3>
        </div>
        <div className="ar-context__stream-status">
          <StatusIndicator
            variant={statusConfig.variant}
            size="xs"
            pulse={connectionState === 'live'}
            ariaLabel={`Activity Stream: ${statusConfig.label}`}
          />
          <span className="ar-context__stream-status-label">
            Activity Stream
          </span>
          <span className={`ar-context__stream-status-state ar-context__stream-status-state--${statusConfig.variant}`}>
            {statusConfig.label}
          </span>
        </div>
      </div>
    </div>
  );
}

/**
 * M11C Workflow Browser Column
 *
 * A center-left column (~280px) showing active workflows/sessions with their
 * latest disposition, event counts, and last activity. The navigation plane
 * for scope and at-a-glance health of every workstream.
 *
 * Design spec: activity-room-visual-design-spec.md §2.3
 *   - Target width: ~280px (±16px)
 *   - Content: unit list, scope selector, execution pulse
 *   - At <768px becomes a bottom sheet
 *
 * Authority: derives from M11C stream items and workflow summary projection.
 * No state mutation — pure projection.
 */

import { useMemo, useState } from 'react';
import type { M11CStreamItem } from '../../hooks/useM11CActivityRoom';
import type { WorkflowSummary } from '@vestara/activity-room';
import { StatusIndicator, type StatusVariant } from '@vestara/ui';
import { WORKFLOW_STATUS_CONFIG } from './status-config';

// ─── Types ───────────────────────────────────────────────────

interface WorkflowBrowserProps {
  /** Stream items to derive workflow data from. */
  readonly stream: readonly M11CStreamItem[];
  /** Workflow summary projection (if available). */
  readonly workflowSummary: WorkflowSummary | null;
  /** Currently selected participant (for filtering). */
  readonly selectedParticipantId?: string;
  /** Callback when a workflow context is selected. */
  readonly onSelectWorkflow?: (workflowId: string | null) => void;
}

export interface WorkflowUnit {
  readonly workflowId: string;
  readonly status: string;
  readonly taskCount: number;
  readonly completedTasks: number;
  readonly eventCount: number;
  readonly lastActivity: string;
  readonly agentNames: readonly string[];
  readonly hasErrors: boolean;
  readonly isActive: boolean;
}

// ─── Helpers ─────────────────────────────────────────────────

/** Derive workflow units from stream items. */
export function deriveWorkflowUnits(stream: readonly M11CStreamItem[]): readonly WorkflowUnit[] {
  const workflowMap = new Map<string, {
    events: M11CStreamItem[];
    agents: Set<string>;
    hasErrors: boolean;
  }>();

  for (const item of stream) {
    const wfId = item.workflowRunId;
    if (!wfId) continue;

    let entry = workflowMap.get(wfId);
    if (!entry) {
      entry = { events: [], agents: new Set(), hasErrors: false };
      workflowMap.set(wfId, entry);
    }

    entry.events.push(item);
    if (item.actor.type !== 'human') {
      entry.agents.add(item.actor.displayName);
    }
    if (item.kind === 'error') {
      entry.hasErrors = true;
    }
  }

  const units: WorkflowUnit[] = [];
  for (const [workflowId, entry] of workflowMap) {
    const sorted = [...entry.events].sort((a, b) => b.sequence - a.sequence);
    const latest = sorted[0];
    const completed = entry.events.filter(
      (e) => e.kind === 'activity' && e.content.includes('completed'),
    ).length;

    units.push({
      workflowId,
      status: latest?.kind ?? 'unknown',
      taskCount: entry.events.filter((e) => e.taskId).length,
      completedTasks: completed,
      eventCount: entry.events.length,
      lastActivity: latest?.timestamp ?? '',
      agentNames: [...entry.agents],
      hasErrors: entry.hasErrors,
      isActive: !entry.hasErrors && entry.events.some((e) => e.kind === 'activity' || e.kind === 'progress'),
    });
  }

  // Sort by most recent activity
  return units.sort(
    (a, b) => new Date(b.lastActivity).getTime() - new Date(a.lastActivity).getTime(),
  );
}

/**
 * Authoritative "active work exists" signal for adaptive composition (008F).
 * Single derivation home shared with the browser below: a unit counts as
 * active exactly as the browser defines it, or the latest projected summary
 * is running. No inference beyond these authorities.
 */
export function hasActiveWork(
  units: readonly WorkflowUnit[],
  workflowSummary: WorkflowSummary | null,
): boolean {
  return units.some((u) => u.isActive) || workflowSummary?.status === 'running';
}

function formatTimeAgo(timestamp: string): string {
  const now = Date.now();
  const then = new Date(timestamp).getTime();
  const diffMs = now - then;
  const diffSec = Math.floor(diffMs / 1000);
  if (diffSec < 60) return `${diffSec}s`;
  const diffMin = Math.floor(diffSec / 60);
  if (diffMin < 60) return `${diffMin}m`;
  const diffHr = Math.floor(diffMin / 60);
  if (diffHr < 24) return `${diffHr}h`;
  return `${Math.floor(diffHr / 24)}d`;
}

// ─── Component ───────────────────────────────────────────────

export default function M11CWorkflowBrowser({
  stream,
  workflowSummary,
  onSelectWorkflow,
}: WorkflowBrowserProps) {
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const units = useMemo(() => deriveWorkflowUnits(stream), [stream]);

  // Derive status variant from workflow summary
  const summaryStatus = workflowSummary?.status ?? 'idle';
  const summaryConfig = WORKFLOW_STATUS_CONFIG[summaryStatus];
  const summaryVariant: StatusVariant = summaryConfig?.variant ?? 'idle';
  const summaryPulse = summaryConfig?.pulse ?? false;

  return (
    <div className="ar-workflow-browser" role="region" aria-label="Workflow browser">
      {/* Header */}
      <div className="ar-workflow-browser__header">
        <div className="ar-kicker">Workflows</div>
        <div className="ar-workflow-browser__summary">
          <StatusIndicator
            variant={summaryVariant}
            size="xs"
            pulse={summaryPulse}
            ariaLabel={`Workflow: ${summaryStatus}`}
          />
          <span className="ar-workflow-browser__summary-text">
            {workflowSummary
              ? `${workflowSummary.completedTasks}/${workflowSummary.taskCount} tasks`
              : `${units.length} workflow${units.length !== 1 ? 's' : ''}`}
          </span>
        </div>
      </div>

      {/* Unit list */}
      <div className="ar-workflow-browser__list ar-scroll" role="list">
        {units.length === 0 ? (
          <div className="ar-workflow-browser__empty">
            No active workflows
          </div>
        ) : (
          units.map((unit) => {
            const isExpanded = expandedId === unit.workflowId;
            return (
              <div
                key={unit.workflowId}
                className={`ar-workflow-unit ${isExpanded ? 'ar-workflow-unit--expanded' : ''}`}
                role="listitem"
              >
                <button
                  type="button"
                  className="ar-workflow-unit__header"
                  onClick={() => {
                    setExpandedId(isExpanded ? null : unit.workflowId);
                    onSelectWorkflow?.(isExpanded ? null : unit.workflowId);
                  }}
                  aria-expanded={isExpanded}
                >
                  <StatusIndicator
                    variant={unit.hasErrors ? 'error' : 'live'}
                    size="xs"
                    pulse={!unit.hasErrors}
                    ariaLabel={`Workflow ${unit.workflowId}: ${unit.status}`}
                  />
                  <div className="ar-workflow-unit__info">
                    <span className="ar-workflow-unit__id">
                      {unit.workflowId.length > 12
                        ? `${unit.workflowId.slice(0, 12)}…`
                        : unit.workflowId}
                    </span>
                    <span className="ar-workflow-unit__meta">
                      {unit.eventCount} events · {formatTimeAgo(unit.lastActivity)} ago
                    </span>
                  </div>
                </button>

                {isExpanded && (
                  <div className="ar-workflow-unit__detail">
                    {/* Progress bar */}
                    {unit.taskCount > 0 && (
                      <div className="ar-workflow-unit__progress">
                        <div className="ar-workflow-unit__progress-bar">
                          <div
                            className={`ar-workflow-unit__progress-fill ${unit.hasErrors ? 'ar-workflow-unit__progress-fill--error' : ''}`}
                            style={{ width: `${Math.round((unit.completedTasks / unit.taskCount) * 100)}%` }}
                          />
                        </div>
                        <span className="ar-workflow-unit__progress-text">
                          {unit.completedTasks}/{unit.taskCount} tasks
                        </span>
                      </div>
                    )}
                    {unit.agentNames.length > 0 && (
                      <div className="ar-workflow-unit__agents">
                        <span className="ar-workflow-unit__detail-label">Agents:</span>
                        {unit.agentNames.map((name) => (
                          <span key={name} className="ar-workflow-unit__agent-badge">
                            {name}
                          </span>
                        ))}
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

/**
 * M11C Projection-Driven Participant Panel (VES-DESIGN-008C presentation)
 *
 * Renders participants from M10 ParticipantProjection (via M11A API).
 * Zero hardcoded teams, roles, or model names. Activity Room is a generic
 * consumer of participant/team information — it does not define teams.
 *
 * Identity honesty (008C audit — presentation only, never new authority):
 * - displayName is authoritative PER CONTRACT, but for unnamed agents it
 *   carries the stable agent/model id (e.g. "mimo-v2.5-free"), which must
 *   not masquerade as a chosen actor name.
 * - Rule: displayName that merely echoes modelId is demoted to secondary
 *   metadata; the primary becomes modelDisplayName (the contract-sanctioned
 *   presentation fallback) or "Unknown agent".
 * - FIRST BROKEN BOUNDARY (recorded, not repaired here): upstream adapters
 *   emit model ids as actor.displayName (M9 adapter/agent contracts); M10
 *   passes them through. A future semantic milestone must establish chosen
 *   agent identity upstream. M11C must not invent it.
 *
 * Presence honesty: M10 never resolves presence today (uniform 'offline'
 * default — "resolved independently" path is unwired). Presence lamps render
 * ONLY for positively-resolved states (online/active/busy/away); otherwise
 * presence is omitted, never inferred from workState. Work state renders
 * from WORK_STATE_CONFIG; the M10 resting value 'available' (absent from
 * the config) carries no information and renders no claim.
 *
 * Humans and agents share the same component contract.
 */

import type { ParticipantProjection } from '@vestara/activity-room';
import { Badge, StatusIndicator } from '@vestara/ui';
import { memo, useMemo, useState } from 'react';
import { WORK_STATE_CONFIG, PRESENCE_VARIANT_CONFIG } from './status-config';

// ─── Types ───────────────────────────────────────────────────

interface M11CParticipantRailProps {
  /** Projection-driven participants — never hardcoded. */
  readonly participants: readonly ParticipantProjection[];
  /** Currently selected participant (for stream filtering). */
  readonly selectedParticipantId: string | undefined;
  /** Callback when a participant is selected. */
  readonly onSelectParticipant: (participantId: string | undefined) => void;
  /** Callback when an agent name is clicked/activated — opens Agent Control drawer. */
  readonly onOpenAgentControl?: (participantId: string) => void;
  /** Unread counts per participant (keyed by participantId). */
  readonly unreadCounts?: ReadonlyMap<string, number>;
}

// ─── Identity resolution (presentation fallback only) ────────

interface ResolvedIdentity {
  /** Primary human-facing name — never a bare model id. */
  readonly name: string;
  /** True when no authoritative identity exists upstream. */
  readonly unknown: boolean;
  /** Secondary metadata line (model · provider), when available. */
  readonly meta?: string;
}

function resolveIdentity(p: ParticipantProjection): ResolvedIdentity {
  if (p.type === 'human') {
    return { name: p.displayName, unknown: false };
  }
  const idLike = !p.displayName || p.displayName === p.modelId;
  if (!idLike) {
    const meta = [p.modelId, p.providerId].filter(Boolean).join(' · ');
    return { name: p.displayName, unknown: false, meta: meta || undefined };
  }
  const meta = [p.modelId, p.providerId].filter(Boolean).join(' · ');
  return { name: p.modelDisplayName ?? 'Unknown agent', unknown: !p.modelDisplayName, meta: meta || undefined };
}

/** Presence states that constitute a positively-resolved claim. Compared as
    strings: today's PresenceState union cannot express them, which is
    exactly why presence must stay omitted until the contract grows. */
function resolvedPresence(p: ParticipantProjection): string | null {
  const presence: string = p.presence;
  return presence === 'online' || presence === 'active' || presence === 'busy' || presence === 'away' ? presence : null;
}

// ─── Membership ──────────────────────────────────────────────

const MEMBERSHIP_LABEL: Record<string, string> = {
  member: '',
  observer: 'Observer',
  guest: 'Guest',
};

// ─── Shared presentation classes (canonical tokens only) ─────

const TILE_BASE =
  'grid size-9 shrink-0 place-items-center rounded-[var(--vestara-radius)] border text-sm font-semibold [&_svg]:size-[18px]';

// ─── Component ───────────────────────────────────────────────

export default function M11CParticipantRail({
  participants,
  selectedParticipantId,
  onSelectParticipant,
  onOpenAgentControl,
  unreadCounts,
}: M11CParticipantRailProps) {
  // ─── Search and type filter state ─────────────────────────
  const [search, setSearch] = useState('');
  const [typeFilter, setTypeFilter] = useState<'all' | 'human' | 'agent'>('all');

  // ─── Filtered participants ────────────────────────────────
  // Model/provider stay searchable (secondary recall) but are never
  // primary visual identity.
  const filtered = useMemo(() => {
    const hasFilter = search.trim() !== '' || typeFilter !== 'all';
    if (!hasFilter) return null; // null = use normal grouped presentation

    const searchLower = search.toLowerCase().trim();
    return participants.filter((p) => {
      if (typeFilter !== 'all' && p.type !== typeFilter) return false;
      if (searchLower) {
        const id = resolveIdentity(p);
        const haystack = [id.name, p.role ?? '', p.modelDisplayName ?? '', p.modelId ?? '', p.providerId ?? '']
          .join(' ')
          .toLowerCase();
        return haystack.includes(searchLower);
      }
      return true;
    });
  }, [participants, search, typeFilter]);

  // ─── Normal grouped presentation ──────────────────────────
  const grouped = useMemo(() => {
    if (filtered !== null) return filtered; // filtered mode
    // Default: sort by presence (online first), then by name
    return [...participants].sort((a, b) => {
      const presenceOrder: Record<string, number> = { online: 0, active: 0, busy: 1, away: 2, offline: 3 };
      const aOrder = presenceOrder[a.presence] ?? 4;
      const bOrder = presenceOrder[b.presence] ?? 4;
      if (aOrder !== bOrder) return aOrder - bOrder;
      return a.displayName.localeCompare(b.displayName);
    });
  }, [participants, filtered]);

  if (participants.length === 0) {
    return (
      <div className="ar-rail" role="region" aria-label="Participants">
        <p className="ar-kicker">Participants</p>
        <p className="ar-rail__empty">No participants yet.</p>
      </div>
    );
  }

  // Counts from authoritative workState, not from presence (UNKNOWN).
  // "total" counts projections; "at work" counts working/blocked/
  // attention-required. Presence is never claimed.
  const activeCount = participants.filter((p) => p.workState === 'working' || p.workState === 'blocked' || p.workState === 'attention-required').length;
  const totalCount = participants.length;
  const isFiltered = filtered !== null;

  return (
    <div className="ar-rail" role="region" aria-label="Participants">
      <div className="ar-rail__head">
        <p className="ar-kicker">Participants</p>
        <button
          type="button"
          onClick={() => {
            onSelectParticipant(undefined);
            setSearch('');
            setTypeFilter('all');
          }}
          className={`ar-rail__all ${selectedParticipantId === undefined && !isFiltered ? 'ar-rail__all--active' : ''}`}
          aria-pressed={selectedParticipantId === undefined && !isFiltered}
        >
          <span className="ar-rail__all-label">Everyone</span>
          <span className="ar-rail__census">
            <strong>{totalCount}</strong> total{activeCount > 0 ? <> · <strong>{activeCount}</strong> at work</> : ''}
          </span>
        </button>
      </div>

      {/* ── Search + Type Filter ──────────────────────────── */}
      <div className="ar-rail__filters">
        <div className="ar-rail__search">
          <input
            type="text"
            placeholder="Search participants…"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="ar-rail__search-input"
            aria-label="Search participants"
          />
        </div>
        <div
          role="group"
          aria-label="Filter by type"
          className="inline-flex flex-wrap gap-1 rounded-[var(--vestara-radius)] border border-[var(--vestara-border-default)] bg-[var(--vestara-surface-panel-raised)] p-1"
        >
          {(['all', 'human', 'agent'] as const).map((option) => (
            <button
              key={option}
              type="button"
              aria-pressed={typeFilter === option}
              onClick={() => setTypeFilter(option)}
              className={`min-h-7 rounded-[var(--vestara-radius)] border px-2.5 text-[var(--vestara-font-size-xs)] capitalize focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--vestara-accent)] focus-visible:ring-inset ${typeFilter === option ? 'border-[var(--vestara-accent-border)] bg-[var(--vestara-accent-bg)] text-[var(--vestara-accent-text)]' : 'border-transparent text-[var(--vestara-text-muted)] hover:text-[var(--vestara-text)]'}`}
            >
              {option === 'all' ? 'All' : option === 'human' ? 'Humans' : 'Agents'}
            </button>
          ))}
        </div>
      </div>

      {/* ── Participant list ─────────────────────────────────
          Page owns scrolling (008A finding): no nested rail scrollbar. */}
      <div className="ar-rail__list" role="list">
        {grouped.length === 0 ? (
          <div className="ar-rail__empty">No matching participants.</div>
        ) : (
          grouped.map((participant) => (
            <ParticipantRow
              key={participant.participantId}
              participant={participant}
              selected={selectedParticipantId === participant.participantId}
              onSelect={onSelectParticipant}
              onOpenAgentControl={onOpenAgentControl}
              unreadCount={unreadCounts?.get(participant.participantId) ?? 0}
            />
          ))
        )}
      </div>

      {/* ── Filter status ─────────────────────────────────── */}
      {isFiltered && (
        <div className="ar-rail__filter-status">
          <span>{grouped.length} of {participants.length}</span>
          <button
            type="button"
            onClick={() => { setSearch(''); setTypeFilter('all'); }}
            className="ar-rail__filter-clear"
          >
            Clear
          </button>
        </div>
      )}
    </div>
  );
}

// ─── Participant Row ─────────────────────────────────────────

const ParticipantRow = memo(function ParticipantRow({
  participant,
  selected,
  onSelect,
  onOpenAgentControl,
  unreadCount = 0,
}: {
  participant: ParticipantProjection;
  selected: boolean;
  onSelect: (id: string | undefined) => void;
  onOpenAgentControl?: (participantId: string) => void;
  unreadCount?: number;
}) {
  const isHuman = participant.type === 'human';
  const canOpenDrawer = !isHuman && onOpenAgentControl;
  const identity = resolveIdentity(participant);
  const initial = identity.unknown ? '?' : (identity.name.trim()[0] ?? '?').toUpperCase();

  // Work state from the contract config only. The M10 resting value
  // 'available' is absent from the config: it carries no information and
  // renders no claim (never a presence word).
  const work = WORK_STATE_CONFIG[participant.workState];
  const presence = resolvedPresence(participant);
  const membershipLabel = MEMBERSHIP_LABEL[participant.membership] ?? '';

  // Tile tone decorates actor TYPE only — never status, presence, or health.
  const tileTone = isHuman
    ? 'var(--vestara-status-info)'
    : identity.unknown
      ? 'var(--vestara-text-muted)'
      : 'var(--vestara-accent-text)';

  const handleNameClick = (e: React.MouseEvent) => {
    if (!canOpenDrawer) return;
    e.stopPropagation();
    onOpenAgentControl!(participant.participantId);
  };

  const handleNameKeyDown = (e: React.KeyboardEvent) => {
    if (!canOpenDrawer) return;
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      e.stopPropagation();
      onOpenAgentControl!(participant.participantId);
    }
  };

  return (
    <button
      type="button"
      onClick={() => onSelect(selected ? undefined : participant.participantId)}
      aria-pressed={selected}
      aria-label={`${identity.name}, ${isHuman ? 'human' : 'agent'}${work ? `, ${work.label}` : ''}`}
      className={`group flex w-full min-w-0 items-center gap-2.5 rounded-[var(--vestara-radius)] border px-2 py-2 text-left transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--vestara-accent)] focus-visible:ring-inset ${selected ? 'border-[var(--vestara-accent-border)] bg-[var(--vestara-accent-bg)] shadow-[inset_3px_0_0_var(--vestara-accent)]' : 'border-transparent hover:border-[var(--vestara-border-subtle)] hover:bg-[var(--vestara-accent-bg)]'}`}
    >
      {/* Actor-type tile (type only — never status) */}
      <span
        aria-hidden="true"
        className={TILE_BASE}
        style={{
          color: tileTone,
          background: `color-mix(in srgb, ${tileTone} 12%, transparent)`,
          borderColor: `color-mix(in srgb, ${tileTone} 30%, transparent)`,
        }}
      >
        {initial}
      </span>

      <span className="min-w-0 flex-1">
        {/* Primary identity + kind */}
        <span className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-0.5">
          <span
            className={canOpenDrawer ? 'cursor-pointer truncate text-sm font-medium text-[var(--vestara-accent-text)] hover:underline' : 'truncate text-sm font-medium text-[var(--vestara-text)]'}
            role={canOpenDrawer ? 'button' : undefined}
            tabIndex={canOpenDrawer ? 0 : undefined}
            aria-label={canOpenDrawer ? `Open agent control for ${identity.name}` : undefined}
            onClick={canOpenDrawer ? handleNameClick : undefined}
            onKeyDown={canOpenDrawer ? handleNameKeyDown : undefined}
          >
            {identity.name}
          </span>
          <Badge variant={isHuman ? 'info' : 'default'} size="sm">
            {isHuman ? 'Human' : 'Agent'}
          </Badge>
          {!isHuman && participant.role && (
            <span className="truncate text-[11px] capitalize text-[var(--vestara-text-muted)]">
              {participant.role}
            </span>
          )}
          {unreadCount > 0 && (
            <span className="rounded-[var(--vestara-radius-full)] bg-[var(--vestara-accent)] px-1.5 text-[10px] font-semibold text-[var(--color-zinc-950)]">
              {unreadCount > 99 ? '99+' : unreadCount}
            </span>
          )}
        </span>
        {/* Secondary: model · provider (metadata, never identity) */}
        {identity.meta && (
          <span className="mt-0.5 block truncate font-mono text-[10px] text-[var(--vestara-text-muted)]">
            {identity.meta}
          </span>
        )}
        {/* Tertiary: work state (authoritative) + assignment + membership */}
        <span className="mt-0.5 flex min-w-0 flex-wrap items-center gap-x-2 gap-y-0.5 text-[11px] text-[var(--vestara-text-muted)]">
          {presence && (
            <span className="inline-flex items-center gap-1 capitalize">
              <StatusIndicator variant={PRESENCE_VARIANT_CONFIG[presence] ?? 'idle'} size="xs" pulse={false} aria-hidden />
              {presence}
            </span>
          )}
          {work && (
            <span className="inline-flex items-center gap-1">
              <StatusIndicator variant={work.variant} size="xs" pulse={false} aria-hidden />
              {participant.currentAssignment?.taskTitle ?? work.label}
            </span>
          )}
          {!work && participant.currentAssignment?.taskTitle && (
            <span className="truncate">{participant.currentAssignment.taskTitle}</span>
          )}
          {membershipLabel && <span>{membershipLabel}</span>}
        </span>
      </span>
    </button>
  );
});

/**
 * M11C Live Now Strip
 *
 * A thin narrative strip (48–64px) showing per-participant live output
 * with pulsing green indicators. Sits atop the activity stream in the
 * stream-main column.
 *
 * Design spec: activity-room-visual-design-spec.md §2.5
 *   - Target height: 56px, bounds 48–64px
 *   - Renders per-participant live output (role, "Live" badge, trailing narrative)
 *   - Pulsing green marker for active participants
 *   - At <768px collapses to a single truncated line
 *
 * Authority: derives from M11CParticipantProjection presence + stream items.
 * No state mutation — pure projection.
 */

import { useMemo } from 'react';
import type { ParticipantProjection } from '@vestara/activity-room';
import type { M11CStreamItem } from '../../hooks/useM11CActivityRoom';
import { StatusIndicator } from '@vestara/ui';

// ─── Types ───────────────────────────────────────────────────

interface LiveNowStripProps {
  /** All participants from the room projection. */
  readonly participants: readonly ParticipantProjection[];
  /** Recent stream items (last N) to derive live narrative. */
  readonly stream: readonly M11CStreamItem[];
  /** Whether the room is connected and live. */
  readonly isLive: boolean;
}

interface LiveParticipant {
  readonly participantId: string;
  readonly displayName: string;
  readonly role: string | undefined;
  readonly presence: string;
  readonly workState: string;
  readonly latestContent: string;
  readonly latestTimestamp: string;
}

// ─── Helpers ─────────────────────────────────────────────────

/** Derive the latest narrative text for a participant from recent stream items. */
function deriveLatestContent(
  participantId: string,
  stream: readonly M11CStreamItem[],
): { content: string; timestamp: string } | null {
  // Walk backwards to find the most recent item from this participant
  for (let i = stream.length - 1; i >= 0; i--) {
    const item = stream[i];
    if (item.actor.id === participantId && item.content) {
      // Truncate to 80 chars for the strip
      const content = item.content.length > 80
        ? `${item.content.slice(0, 80)}…`
        : item.content;
      return { content, timestamp: item.timestamp };
    }
  }
  return null;
}

// ─── Component ───────────────────────────────────────────────

export default function M11CLiveNowStrip({
  participants,
  stream,
  isLive,
}: LiveNowStripProps) {
  // Only show participants who are online or active
  const liveParticipants = useMemo(() => {
    const live = participants.filter(
      (p) => p.presence === 'online' || p.presence === 'active',
    );

    const result: LiveParticipant[] = [];
    for (const p of live) {
      const latest = deriveLatestContent(p.participantId, stream);
      if (latest) {
        result.push({
          participantId: p.participantId,
          displayName: p.displayName,
          role: p.role,
          presence: p.presence,
          workState: p.workState,
          latestContent: latest.content,
          latestTimestamp: latest.timestamp,
        });
      }
    }

    // Sort by most recent activity
    return result.sort((a, b) =>
      new Date(b.latestTimestamp).getTime() - new Date(a.latestTimestamp).getTime(),
    );
  }, [participants, stream]);

  if (liveParticipants.length === 0) {
    return (
      <div className="ar-live-now" role="status" aria-live="polite">
        <span className="ar-live-now__idle">
          {isLive ? 'No active participants' : 'Waiting for connection…'}
        </span>
      </div>
    );
  }

  return (
    <div className="ar-live-now" role="status" aria-live="polite" aria-label="Live activity">
      <div className="ar-live-now__items">
        {liveParticipants.map((p) => (
          <div key={p.participantId} className="ar-live-now__item">
            <StatusIndicator
              variant={p.presence === 'active' ? 'live' : 'live'}
              size="xs"
              pulse
              ariaLabel={`${p.displayName}: live`}
            />
            <span className="ar-live-now__name">
              {p.displayName}
              {p.role && (
                <span className="ar-live-now__role">{p.role}</span>
              )}
            </span>
            <span className="ar-live-now__narrative">
              {p.latestContent}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

/**
 * M11C Activity Room Page
 *
 * Production Activity Room UI Shell + Live Read Surface.
 * Consumes frozen M11A HTTP read API and M11B WebSocket protocol.
 *
 * Authority flow: M9 durable truth → M10 projection → M11A/M11B → this page → UI
 *
 * No alternative Activity Room state source, polling loop, mock participant
 * system, or UI-owned workflow state is introduced.
 *
 * Acceptance criteria:
 * 1. Renders entirely from M11A/M11B production contracts
 * 2. Zero hardcoded participants
 * 3. Snapshot → catch-up → live produces no visible duplication
 * 4. Disconnect/reconnect requires no reload
 * 5. resync-required performs controlled resynchronization
 * 6. Historical pages load independently from M10's 500-item working set
 * 7. Older-history prepend preserves viewport position
 * 8. Incoming activity does not steal scroll position when reading history
 * 9. At-bottom users follow live activity naturally
 * 10. Stream importance has primary/secondary/muted visual treatment
 * 11. Aggregated items retain M9 references
 * 12. Participant membership/presence/work state displayed independently
 * 13. Keyboard focus can reach stream items
 * 14. No M8/M9/M10 state can be mutated from this page
 * 15. No polling introduced as a second realtime mechanism
 */

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useM11CActivityRoom, type M11CStreamItem } from '../../hooks/useM11CActivityRoom';
import { useActivityRoomUI } from '../../hooks/useActivityRoomUI';
import { useRenderProfiler } from '../../hooks/useActivityProfiler';
import { fetchM11AAggregateDrillDown, type M11AActivityRecord } from '../../lib/m11a-api';
import { postActivityMessage, retractActivityMessage, editActivityMessage } from '../../lib/activity';
import { Pill, StatusIndicator } from '@vestara/ui';
import { RouteHero } from '../../components/layout/PageHero/RouteHero';
import { useMorningBriefing } from '../../hooks/useMorningBriefing';
import { useGAExecutionConfig } from '../../hooks/useGAExecutionConfig';
import '../../styles/activity-room.css';

function getTimeBasedGreeting(now = new Date()) {
  const h = now.getHours();
  if (h < 12) return { greeting: 'Good Morning', period: 'morning', emoji: '☀️' };
  if (h < 18) return { greeting: 'Good Afternoon', period: 'afternoon', emoji: '🌤️' };
  return { greeting: 'Good Evening', period: 'evening', emoji: '🌙' };
}
import AgentProjectionDrawer from './AgentProjectionDrawer';
import { resolveAgentIdFromParticipantId } from './AgentProjectionDrawer';
import M11CActivityStream from './M11CActivityStream';
import M11CConnectionStatus from './M11CConnectionStatus';
import M11CParticipantRail from './M11CParticipantRail';
import M11CLiveNowStrip from './M11CLiveNowStrip';
import M11CWorkflowBrowser, { deriveWorkflowUnits, hasActiveWork } from './M11CWorkflowBrowser';
import M11CDockedInspector from './M11CDockedInspector';
import { WORKFLOW_STATUS_CONFIG } from './status-config';
import ActivityRoomContextPanel from './ActivityRoomContextPanel';

// ─── Component ───────────────────────────────────────────────

export default function M11CActivityRoomPage() {
  useRenderProfiler('M11CActivityRoomPage');
  const room = useM11CActivityRoom();
  const ui = useActivityRoomUI();
  const { briefing: morningBriefing } = useMorningBriefing();
  const [morningOpen, setMorningOpen] = useState(false);
  const [selectedParticipantId, setSelectedParticipantId] = useState<string | undefined>(undefined);

  // ─── Agent Control Drawer ─────────────────────────────────

  const agentControlParticipant = useMemo(
    () => ui.agentControlParticipantId
      ? room.participants.find((p) => p.participantId === ui.agentControlParticipantId)
      : undefined,
    [ui.agentControlParticipantId, room.participants],
  );

  const agentControlAgentId = useMemo(
    () => ui.agentControlParticipantId
      ? resolveAgentIdFromParticipantId(ui.agentControlParticipantId)
      : null,
    [ui.agentControlParticipantId],
  );

  // ─── Derived counts for context panel ──────────────────────

  // Derive "at work" from authoritative workState, not from presence (which is UNKNOWN).
  const activeAgentCount = useMemo(
    () => room.participants.filter(
      (p) => p.type !== 'human' && (p.workState === 'working' || p.workState === 'blocked' || p.workState === 'attention-required'),
    ).length,
    [room.participants],
  );

  // Participant ID → display name lookup for enriching stream item actor names.
  // Includes both participantId (agent-agent-developer) and raw actor.id (vestara) keys.
  const participantNames = useMemo(() => {
    const map: Record<string, string> = {};
    for (const p of room.participants) {
      map[p.participantId] = p.displayName;
      // Also map the raw agent ID (e.g. "agent-developer") for stream items
      // that use actor.id instead of participantId.
      const rawId = p.participantId.replace(/^agent-/, '');
      if (rawId !== p.participantId) map[rawId] = p.displayName;
    }
    // Known hardcoded agent IDs from M9 adapters that don't match AgentStorage
    if (!map['vestara']) map['vestara'] = 'Assistant';
    return map;
  }, [room.participants]);

  // ─── Callbacks ──────────────────────────────────────────

  const handleSelectParticipant = useCallback((id: string | undefined) => {
    setSelectedParticipantId(id);
  }, []);

  const [drillDownRecords, setDrillDownRecords] = useState<readonly M11AActivityRecord[]>([]);
  const [drillDownLoading, setDrillDownLoading] = useState(false);

  const handleDrillDown = useCallback(async (aggregateId: string, _referencedIds: readonly string[]) => {
    setDrillDownLoading(true);
    try {
      const result = await fetchM11AAggregateDrillDown(aggregateId);
      setDrillDownRecords(result.records);
      const aggregateItem = room.stream.find((s) => s.id === aggregateId);
      if (aggregateItem) {
        ui.openDetail(aggregateItem);
      }
    } catch {
      // Drill-down failed — stay silent, user can retry
    } finally {
      setDrillDownLoading(false);
    }
  }, [room.stream, ui.openDetail]);

  const handleRetract = useCallback(async (item: M11CStreamItem) => {
    try {
      await retractActivityMessage(item.id, 'Message retracted');
    } catch {
      // Retraction failed — stay silent
    }
  }, []);

  // Look up author name by activity ID from the stream
  const lookupAuthor = useCallback((activityId: string): string | undefined => {
    const item = room.stream.find((s) => s.id === activityId);
    return item?.actor.displayName;
  }, [room.stream]);

  // Look up content preview by activity ID from the stream
  const lookupContent = useCallback((activityId: string): string | undefined => {
    const item = room.stream.find((s) => s.id === activityId);
    return item?.content;
  }, [room.stream]);

  // ─── Connection state label ─────────────────────────────

  const stateLabel =
    room.state === 'connecting' ? 'Connecting' :
    room.state === 'live' ? 'Live' :
    room.state === 'reconnecting' ? 'Reconnecting' :
    room.state === 'offline' ? 'Offline' :
    room.state === 'paused' ? 'Paused' :
    room.state === 'error' ? 'Offline' :
    'Unknown';

  // ─── Room name ──────────────────────────────────────────

  const roomName = room.room?.name ?? 'Activity Room';

  // ─── Adaptive work composition (VES-DESIGN-008F) ──────────
  // One composition, state-aware sizing. The active-work signal shares
  // the browser's own derivation home (no parallel logic): a unit counts
  // exactly as the browser defines it, or the latest summary is running.
  const workflowUnits = useMemo(() => deriveWorkflowUnits(room.stream), [room.stream]);
  const hasActiveWorkflows = hasActiveWork(workflowUnits, room.workflowSummary);
  const detailOpen = ui.detailItem != null;
  // Stream owns the flexible share; rails keep bounded widths. Active
  // workflows render as a strip above the stream (never a middle column),
  // so the grid is at most rail + stream + inspector. The inspector track
  // is `auto` and collapses when the (null-gated, CSS-hidden <1440px)
  // inspector renders nothing. Exactly one lg template applies — never
  // two competing column definitions.
  const workingAreaGrid = [
    'grid min-w-0 grid-cols-1 gap-4 mt-3',
    detailOpen
      ? 'lg:grid-cols-[18rem_minmax(0,1fr)_auto]'
      : 'lg:grid-cols-[18rem_minmax(0,1fr)]',
  ].join(' ');

  return (
    <>
      {/* ─── Canonical workspace Hero (VES-DESIGN-008B) ─────────
          Replaces the hand-rolled ar-plinth. Hierarchy:
          STATUS (connection) vs METADATA (records/cursor) vs ACTION
          (Pause/Clear). No reference-only controls, no fake metrics. */}
      <RouteHero
        routeId="activity"
        title={roomName}
        actions={[
          { label: room.paused ? 'Resume' : 'Pause', onClick: room.paused ? room.resume : room.pause },
          { label: 'Clear', onClick: room.clear, title: 'Clear local view' },
        ]}
        meta={
          <>
            <M11CConnectionStatus state={room.state} />
            <span className="mpg-tag-pill">
              {room.stream.length} record{room.stream.length === 1 ? '' : 's'}
            </span>
            {room.cursor && (
              <span className="mpg-tag-pill">cursor {room.cursor.sequenceNumber}</span>
            )}
          </>
        }
      />

      {/* ─── Error Banner ───────────────────────────────── */}
      {room.error && (
        <div className="ar-banner ar-banner--warn mt-3" role="alert">
          <StatusIndicator variant="warn" size="sm" ariaLabel="Warning" />
          <span className="min-w-0 flex-1">{room.error}</span>
          <Pill variant="danger" size="sm" onClick={room.retry}>
            Reconnect
          </Pill>
        </div>
      )}

      {/* ─── Briefing Banner — dynamic greeting based on local time, exact executedAt ─── */}
      {morningBriefing && (() => { const { greeting, period, emoji } = getTimeBasedGreeting(); return (
        <button
          type="button"
          onClick={() => setMorningOpen(true)}
          className="mt-3 flex w-full items-center gap-3 rounded-[var(--vestara-radius-lg)] border border-[var(--vestara-amber)]/30 bg-[var(--vestara-amber)]/10 px-4 py-3 text-left hover:bg-[var(--vestara-amber)]/15 transition-colors cursor-pointer"
        >
          <span className="text-[var(--vestara-amber)]">{emoji}</span>
          <span className="min-w-0 flex-1">
            <span className="block text-xs font-semibold text-[var(--vestara-text)]">{greeting} Director — your {period} briefing</span>
            <span className="block text-[11px] text-[var(--vestara-text-muted)] truncate">{morningBriefing.summary} · Executed: {new Date(morningBriefing.executedAt).toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'medium' })} — click for detail</span>
          </span>
          <span className="shrink-0 text-xs text-[var(--vestara-amber)]">View ›</span>
        </button>
      ); })()}
      {morningOpen && morningBriefing && (() => { const { greeting, period, emoji } = getTimeBasedGreeting(); return (
        <div className="fixed inset-0 z-50 grid place-items-center bg-black/50 p-4" role="dialog" aria-modal="true" onClick={() => setMorningOpen(false)}>
          <div className="w-full max-w-2xl max-h-[80vh] overflow-auto rounded-xl border bg-[var(--vestara-surface-panel)] p-4" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-start justify-between gap-2">
              <div>
                <h3 className="text-sm font-semibold">{emoji} {greeting} Director — {period} briefing detail</h3>
                <p className="text-xs text-[var(--vestara-amber)]">{greeting} Director, here is your {period} briefing for today — {new Date(morningBriefing.executedAt).toLocaleString(undefined, { dateStyle: 'full', timeStyle: 'long' })}</p>
                <p className="text-[10px] text-[var(--vestara-text-dim)]">Created: {new Date(morningBriefing.createdAt).toLocaleString()} · ID: {morningBriefing.id}</p>
              </div>
              <button type="button" onClick={() => setMorningOpen(false)} className="size-8 grid place-items-center rounded-lg border">×</button>
            </div>
            <div className="mt-3 space-y-3 text-xs">
              <div><div className="font-semibold uppercase">Repo Health</div><pre className="mt-1 whitespace-pre-wrap rounded border p-2 bg-[var(--vestara-surface-panel-raised)]">{morningBriefing.details.repoHealth || '(empty)'}</pre></div>
              <div><div className="font-semibold uppercase">Workspace Status</div><pre className="mt-1 whitespace-pre-wrap rounded border p-2 bg-[var(--vestara-surface-panel-raised)]">{morningBriefing.details.workspaceStatus || '(empty)'}</pre></div>
              <div><div className="font-semibold uppercase">Activity</div><pre className="mt-1 whitespace-pre-wrap rounded border p-2 bg-[var(--vestara-surface-panel-raised)]">{morningBriefing.details.activity || '(empty)'}</pre></div>
              {morningBriefing.details.fullContent && <div><div className="font-semibold uppercase">Full</div><pre className="mt-1 whitespace-pre-wrap rounded border p-2 bg-[var(--vestara-surface-panel-raised)]">{morningBriefing.details.fullContent}</pre></div>}
            </div>
          </div>
        </div>
      ); })()}

      {/* ─── Attention Banner ───────────────────────────── */}
      {room.attention.length > 0 && (
        <div className="ar-banner ar-banner--info mt-3">
          <StatusIndicator variant="warn" size="sm" ariaLabel="Attention required" />
          <span className="font-medium text-(--vestara-amber)">
            {room.attention.length} attention item{room.attention.length > 1 ? 's' : ''}
          </span>
          <span className="ar-banner__note">
            {room.attention.filter((a) => a.severity === 'critical').length > 0 && (
              <span className="ar-banner__critical">
                {room.attention.filter((a) => a.severity === 'critical').length} critical
              </span>
            )}
          </span>
        </div>
      )}

      {/* ─── Working area: adaptive composition (VES-DESIGN-008F) ──
          INFORMATION VALUE drives SPACE ALLOCATION. Participants keep a
          stable contextual width; the stream owns the flexible share. The
          workflow column exists only while authoritative active work
          exists — otherwise a compact disclosure preserves browsing
          without spending a permanent column on "0 workflows". */}
      {!hasActiveWorkflows && (
        <details className="mt-3 rounded-[var(--vestara-radius-lg)] border border-[var(--vestara-border-subtle)] bg-[var(--vestara-surface-panel)] px-4 py-2.5">
          <summary className="cursor-pointer text-sm font-medium text-[var(--vestara-text-secondary)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--vestara-accent)] focus-visible:ring-inset">
            Workflows · {workflowUnits.length}
            <span className="ml-2 text-xs font-normal text-[var(--vestara-text-muted)]">
              {workflowUnits.length === 0 ? 'No active workflows' : 'No running workflows — expand to browse'}
            </span>
          </summary>
          <div className="mt-2">
            <M11CWorkflowBrowser
              stream={room.stream}
              workflowSummary={room.workflowSummary}
            />
          </div>
        </details>
      )}
      <div className={workingAreaGrid}>
        {/* Participant Rail (projection-driven; page owns scrolling) */}
        <aside className="ar-panel ar-panel--rail">
          <M11CParticipantRail
            participants={room.participants}
            selectedParticipantId={selectedParticipantId}
            onSelectParticipant={handleSelectParticipant}
            onOpenAgentControl={ui.openAgentControl}
          />
        </aside>

        {/* Center Stream (the salon) */}
        <main className="ar-panel ar-panel--main">
          <div className="ar-panel__head">
            <div className="ar-panel__label" aria-live="polite">
              {selectedParticipantId === undefined ? 'Activity Stream' : `Activity — ${selectedParticipantId}`}
            </div>
            <span className="ar-panel__hint">{room.paused ? `${room.unread} buffered` : stateLabel}</span>
          </div>

          {/* Active-work strip: workflows live above the stream, never as
              a middle column. Collapsed disclosure below covers idle. */}
          {hasActiveWorkflows && (
            <div className="ar-workflow-strip">
              <M11CWorkflowBrowser
                stream={room.stream}
                workflowSummary={room.workflowSummary}
              />
            </div>
          )}

          {/* Live Now Strip */}
          <M11CLiveNowStrip
            participants={room.participants}
            stream={room.stream}
            isLive={room.state === 'live'}
          />

          {/* Stream */}
          <M11CActivityStream
            items={room.stream}
            stateLabel={stateLabel}
            connectionState={room.state}
            unread={room.unread}
            loadingHistory={room.loadingHistory}
            olderLoaded={room.olderLoaded}
            loading={room.state === 'connecting'}
            onLoadOlder={room.loadOlder}
            onReportViewport={room.reportViewport}
            onClearUnread={room.clearUnread}
            onOpenDetail={ui.openDetail}
            onDrillDown={handleDrillDown}
            onReply={ui.setReplyTo}
            onRetract={handleRetract}
            onEdit={ui.openEdit}
            onOpenThread={ui.openThread}
            lookupAuthor={lookupAuthor}
            lookupContent={lookupContent}
            selectedParticipantId={selectedParticipantId}
            submission={room.submission}
            onSubmitResponse={room.submitResponse}
            participantNames={participantNames}
          />

          {/* Composer with reply-to support */}
          <M11CComposer replyTo={ui.replyToItem} onClearReply={ui.clearReply} />
        </main>

        {/* Docked Inspector (right column) — replaces context panel at >=1440px */}
        <M11CDockedInspector
          item={ui.detailItem}
          drillDownRecords={drillDownRecords}
          drillDownLoading={drillDownLoading}
          onClose={ui.closeDetail}
        />
      </div>

      {/* ─── Edit Modal ───────────────────────────────── */}
      {ui.editingItem && (
        <M11CEditModal
          item={ui.editingItem}
          onSave={async (newContent) => {
            await editActivityMessage(ui.editingItem!.id, newContent);
            ui.closeEdit();
          }}
          onClose={ui.closeEdit}
        />
      )}

      {/* ─── Thread View Modal ──────────────────────────── */}
      {ui.threadActivityIds.length > 0 && (
        <M11CThreadModal
          activityIds={ui.threadActivityIds}
          lookupAuthor={lookupAuthor}
          lookupContent={lookupContent}
          onClose={ui.closeThread}
        />
      )}

      {/* ─── Agent Control Drawer ───────────────────────── */}
      {agentControlParticipant && agentControlAgentId && (
        <AgentProjectionDrawer
          open
          onClose={ui.closeAgentControl}
          agentId={agentControlAgentId}
          participant={agentControlParticipant}
        />
      )}
    </>
  );
}

// ─── Visual/Non-Mutating Composer ──────────────────────────

/**
 * M11C Composer — sends human messages to the Activity Room.
 * Messages are persisted via POST /api/messages and broadcast via WebSocket.
 * Supports reply-to: when a message is replied to, the actor name is prepended.
 *
 * Premium UX: clean input with integrated send, compact secondary actions.
 */
function M11CComposer({
  replyTo,
  onClearReply,
}: {
  replyTo?: M11CStreamItem | null;
  onClearReply?: () => void;
}) {
  const [value, setValue] = useState('');
  const [sending, setSending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  // Display-only badge: canonical GAExecutionConfig budget (Fix 1 attribution)
  // Fix 3: badge is truthful — untouched 0 means adapter default 80, not "unlimited"
  const { config: execConfig, isCustom } = useGAExecutionConfig();
  const isUntouchedDefault = execConfig.maxToolCalls === 0 && !isCustom;
  const maxToolCallsLabel = isUntouchedDefault
    ? '80 calls'
    : execConfig.maxToolCalls === 0
      ? 'unlimited'
      : `${execConfig.maxToolCalls} calls`;
  const maxToolCallsHint = isUntouchedDefault
    ? 'maxToolCalls: 80 (adapter default, untouched) — raise in Settings or ExecutionControls; 0 = unlimited when touched'
    : execConfig.maxToolCalls === 0
      ? 'maxToolCalls: unlimited (touched) — adapter budget disabled'
      : `maxToolCalls: ${execConfig.maxToolCalls} (adapter enforces per-turn limit; default 80 when untouched)`;

  // Pre-fill with @mention when replying
  useEffect(() => {
    if (replyTo) {
      setValue(`@${replyTo.actor.displayName} `);
      inputRef.current?.focus();
    }
  }, [replyTo]);

  const handleSend = useCallback(async () => {
    const text = value.trim();
    if (!text || sending) return;

    setSending(true);
    setError(null);
    try {
      // Fix 2: @vestara/@assistant maps to agent-assistant target so triggerAssistantTurn fires (AR-006)
      // Without this, M11C always sent all-agents → no Assistant turn, appearing as "nothing happens"
      const isAssistantMention = /@(?:vestara|assistant|agent-assistant)\b/i.test(text);
      const targets = isAssistantMention
        ? ([{ type: 'agent', agentId: 'agent-assistant' }] as const)
        : ([{ type: 'all-agents' }] as const);
      await postActivityMessage({
        content: text,
        targets: [...targets],
        actor: { displayName: 'You', role: 'human' },
        referencedActivityIds: replyTo ? [replyTo.id] : undefined,
      });
      setValue('');
      onClearReply?.();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to send');
    } finally {
      setSending(false);
    }
  }, [value, sending, replyTo, onClearReply]);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        handleSend();
      }
    },
    [handleSend],
  );

  return (
    // VES-DESIGN-008E: first-class human participation surface. Bounded
    // composition — target chip (truthful fixed contract: all-agents, no
    // picker), input, send — plus reply-context strip and error row. Logic,
    // keyboard (Enter sends), validation, and states are unchanged. No
    // delivery/permission claims: HTTP 201 establishes none (recorded gap).
    <div
      className="rounded-[var(--vestara-radius-lg)] border border-[var(--vestara-border-default)] bg-[var(--vestara-surface-panel-raised)] p-2 focus-within:border-[var(--vestara-accent-border-hover)]"
      role="form"
      aria-label="Message composer"
    >
      {/* Reply context — existing referencedActivityIds mechanism only */}
      {replyTo && (
        <div className="mb-2 flex min-w-0 items-center gap-2 rounded-[var(--vestara-radius)] border border-[var(--vestara-border-subtle)] bg-[var(--vestara-surface-panel)] px-2 py-1 text-xs text-[var(--vestara-text-muted)]">
          <span aria-hidden="true">↩</span>
          <span className="min-w-0 flex-1 truncate">
            Replying to <strong className="font-medium text-[var(--vestara-text-secondary)]">{replyTo.actor.displayName}</strong>
          </span>
          {onClearReply && (
            <button
              type="button"
              onClick={onClearReply}
              aria-label="Clear reply context"
              className="shrink-0 rounded px-1 hover:text-[var(--vestara-text)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--vestara-accent)] focus-visible:ring-inset"
            >
              ×
            </button>
          )}
        </div>
      )}

      <div className="flex min-w-0 items-center gap-2">
        {/* Target: fixed all-agents contract, presented truthfully */}
        <span
          className="shrink-0 rounded-[var(--vestara-radius-full)] border border-[var(--vestara-border-default)] px-2 py-0.5 text-[11px] font-medium text-[var(--vestara-text-muted)]"
          title="Messages from this composer are addressed to all agents in this room"
        >
          All agents
        </span>
        {/* maxToolCalls badge — display-only, no write path (approved plan) */}
        <span
          className="shrink-0 rounded-[var(--vestara-radius-full)] border px-2 py-0.5 text-[10px] font-medium"
          style={{
            borderColor: 'var(--vestara-border-subtle)',
            color: 'var(--vestara-text-muted)',
            background: 'var(--vestara-surface-panel)',
          }}
          title={maxToolCallsHint}
          aria-label={`Tool budget ${maxToolCallsLabel}`}
        >
          {maxToolCallsLabel}
        </span>

        {/* Input */}
        <input
          ref={inputRef}
          type="text"
          value={value}
          onChange={(e) => { setValue(e.target.value); setError(null); }}
          onKeyDown={handleKeyDown}
          placeholder={sending ? 'Sending…' : 'Message the room…'}
          className="min-h-9 min-w-0 flex-1 bg-transparent text-sm text-[var(--vestara-text)] placeholder:text-[var(--vestara-text-muted)] focus:outline-none disabled:opacity-60"
          disabled={sending}
          aria-label="Message input"
        />

        {/* Send */}
        <button
          type="button"
          onClick={handleSend}
          disabled={!value.trim() || sending}
          aria-label={sending ? 'Sending message' : 'Send message'}
          className="grid size-9 shrink-0 place-items-center rounded-[var(--vestara-radius)] border border-[var(--vestara-accent-dark)] bg-[var(--vestara-accent)] text-lg leading-none text-[var(--color-zinc-950)] transition-colors hover:bg-[var(--vestara-accent-light)] disabled:cursor-not-allowed disabled:opacity-40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--vestara-accent)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--vestara-surface-panel-raised)]"
        >
          <span aria-hidden="true">{sending ? '…' : '→'}</span>
        </button>
      </div>

      {/* Error */}
      {error && (
        <p className="mt-2 rounded-[var(--vestara-radius)] border px-2 py-1 text-xs text-[var(--vestara-red)]" role="alert"
          style={{
            borderColor: 'color-mix(in srgb, var(--vestara-red) 35%, transparent)',
            background: 'color-mix(in srgb, var(--vestara-red) 8%, transparent)',
          }}
        >
          {error}
        </p>
      )}
    </div>
  );
}

// ─── Edit Modal ─────────────────────────────────────────

function M11CEditModal({
  item,
  onSave,
  onClose,
}: {
  item: M11CStreamItem;
  onSave: (newContent: string) => Promise<void>;
  onClose: () => void;
}) {
  const [value, setValue] = useState(item.content);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onClose]);

  const handleSave = useCallback(async () => {
    const text = value.trim();
    if (!text || saving) return;
    setSaving(true);
    try {
      await onSave(text);
    } finally {
      setSaving(false);
    }
  }, [value, saving, onSave]);

  return (
    <div
      className="ar-backdrop"
      role="dialog"
      aria-modal="true"
      aria-label="Edit message"
      onClick={onClose}
    >
      <div className="ar-modal" onClick={(e) => e.stopPropagation()}>
        <div className="ar-modal__head">
          <h2 className="ar-modal__title">Edit Message</h2>
          <button type="button" onClick={onClose} className="ar-modal__close" aria-label="Close">
            ×
          </button>
        </div>
        <div className="p-4">
          <textarea
            value={value}
            onChange={(e) => setValue(e.target.value)}
            className="w-full rounded-[var(--vestara-radius)] border border-[var(--vestara-border-default)] bg-[var(--vestara-surface-panel-raised)] px-3 py-2 text-sm text-[var(--vestara-text)] focus:outline-none focus:border-[var(--vestara-accent-border-hover)] resize-none placeholder:text-[var(--vestara-text-muted)]"
            rows={4}
            aria-label="Edit message content"
          />
          <div className="mt-3 flex justify-end gap-2">
            <Pill variant="default" size="sm" onClick={onClose}>
              Cancel
            </Pill>
            <Pill
              variant="gold"
              size="sm"
              onClick={handleSave}
              disabled={!value.trim() || saving}
              loading={saving}
            >
              Save
            </Pill>
          </div>
        </div>
      </div>
    </div>
  );
}

