import type { MembershipState, WorkState } from '@vestara/types';
import type { ActivityCursor, ActivityRecord } from './m9-types';
import type {
  ActivityRoomProjection,
  AttentionEntry,
  ContextualCapabilities,
  ParticipantProjection,
