import type { ActivityRecord, VerificationActivity, VerificationCheck, VerificationOutcome } from '../contracts';
import type { ActivityProjector } from '../projector';
import {
  type ActivitySourceEvent,
  extractEvidenceRefs,
  numberField,
  resolveActivityActor,
  stringField,
  stringFieldOr,
} from '../source-event';

interface CheckLike {
  readonly name?: unknown;
  readonly status?: unknown;
  readonly summary?: unknown;
}

const SUPPORTED_TYPES = new Set([
  'harness.verification.started',
  'harness.verification.completed',
  'harness.verification-result',
  'verification.passed',
  'verification.failed',
  'verification.awaiting-approval',
  'project.verification.reopened',
]);

const VERIFICATION_STATUS = new Set(['passed', 'failed', 'skipped', 'blocked']);

/** Projects verification lifecycle and conclusion events. */
export class VerificationProjector implements ActivityProjector {
  readonly kind = 'verification' as const;

  supports(event: ActivitySourceEvent): boolean {
    return SUPPORTED_TYPES.has(event.type);
  }

  project(event: ActivitySourceEvent): readonly ActivityRecord[] {
    const payload = event.payload;
    const checks = Array.isArray(payload.checks)
      ? (payload.checks as readonly CheckLike[]).filter(isCheckLike).map(toVerificationCheck)
      : [];
    const record: VerificationActivity = {
      id: `activity:${event.id}:verification`,
      sequence: event.sourceSequence ?? 0,
      timestamp: event.at,
      actor: resolveActivityActor(event),
      kind: 'verification',
      verificationRunId: event.verificationRunId,
      taskId: event.taskId,
      outcome: outcomeFor(event),
      confidence: numberField(payload, 'confidence'),
      checks,
      reason: reasonFor(event),
      workflowId: event.workflowId,
      correlationId: event.correlationId,
      evidenceRefs: extractEvidenceRefs(payload),
    };
    return [record];
  }
}

function outcomeFor(event: ActivitySourceEvent): VerificationOutcome {
  switch (event.type) {
    case 'verification.passed':
      return 'passed';
    case 'verification.failed':
      return 'failed';
    case 'verification.awaiting-approval':
      return 'blocked';
    case 'harness.verification.started':
    case 'project.verification.reopened':
      return 'inconclusive';
    default: {
      const status = stringFieldOr(event.payload, 'status', 'inconclusive');
      return status === 'passed' || status === 'failed' || status === 'blocked' ? status : 'inconclusive';
    }
  }
}

function reasonFor(event: ActivitySourceEvent): string | undefined {
  const reason = stringField(event.payload, 'reason');
  if (reason !== undefined) return reason;
  switch (event.type) {
    case 'harness.verification.started':
      return 'verification started';
    case 'harness.verification.completed':
      return 'verification completed';
    case 'verification.passed':
      return 'verification passed';
    case 'verification.failed':
      return 'verification failed';
    case 'verification.awaiting-approval':
      return 'verification awaiting approval';
    case 'project.verification.reopened':
      return 'verification reopened';
    default:
      return undefined;
  }
}

function isCheckLike(
  check: CheckLike,
): check is { readonly name: string; readonly status: string; readonly summary?: unknown } {
  return typeof check.name === 'string' && typeof check.status === 'string';
}

function toVerificationCheck(check: {
  readonly name: string;
  readonly status: string;
  readonly summary?: unknown;
}): VerificationCheck {
  return {
    name: check.name,
    status: VERIFICATION_STATUS.has(check.status) ? (check.status as VerificationCheck['status']) : 'blocked',
    summary: typeof check.summary === 'string' ? check.summary : undefined,
  };
}

/**
 * AR-001C: M9 Activity Room Types
 *
 * Consolidated from @vestara/types. These are the Activity Room's own
 * persistence, input, and query contracts. Previously lived in
 * @vestara/types as "Family B" / M9 contracts.
 *
 * Ownership: @vestara/activity-room
 */

import type {
  BindingId,
  Brand,
  ExecutionId,
  RepositoryBindingId,
  RequestId,
  RuntimeSessionId,
  TraceId,
  WorkflowRunId,
  WorkflowTaskId,
} from '@vestara/types';

// ─── Activity Record ID ─────────────────────────────────────

/** Unique identity for a durable Activity record. */
export type ActivityRecordId = Brand<string, 'ActivityRecordId'>;

// ─── Activity Types ─────────────────────────────────────────

/**
 * Canonical activity types. Extensible for future domains (browser, etc.)
 * but normalized to prevent provider/OpenCode-specific leakage.
 */
export type ActivityType =
  // Workflow lifecycle (consumed from M8 WorkflowEvents)
  | 'workflow.started'
  | 'workflow.completed'
  | 'workflow.failed'
  | 'workflow.cancelled'
  // Task lifecycle (consumed from M8 WorkflowEvents)
  | 'task.runnable'
  | 'task.started'
  | 'task.completed'
  | 'task.failed'
  | 'task.cancelled'
  // Agent lifecycle (normalized from agent harness)
  | 'agent.assigned'
  | 'agent.started'
  | 'agent.progress'
  | 'agent.waiting'
  | 'agent.completed'
  | 'agent.failed'
  | 'agent.cancelled'
  // Tool lifecycle (normalized from OpenCode runtime)
  | 'tool.called'
  | 'tool.succeeded'
  | 'tool.failed'
  // Human interaction
  | 'human.message'
  // System
  | 'system.event'
  // Interaction (AR-REC-C2)
  | 'interaction.presented'
  | 'interaction.responded';

/**
 * Source system that produced the event.
 * Normalized to Vestara concepts, not OpenCode internals.
 */
export type ActivitySource =
  | 'workflow-engine'
  | 'agent-harness'
  | 'human-input'
  | 'runtime-session'
  | 'system'
  | 'interaction-app';

/**
 * Visibility scope for an activity record.
 */
export type ActivityVisibility = 'all' | 'operators' | 'system';

// ─── Activity Record ────────────────────────────────────────

/**
 * Durable Activity record. Carries canonical M1/M2 lineage.
 * Never becomes an orchestration authority.
 *
 * Projection state (UI/API) is reconstructable from these records.
 */
export interface ActivityRecord {
  /** Unique identity for this durable record. */
  readonly activityId: ActivityRecordId;

  /** Idempotency key: canonical event identity. Deduplication anchor. */
  readonly eventId: string;

  /** Monotonic sequence number within the store. Ordering anchor. */
  readonly sequenceNumber: number;

  /** Canonical activity type. */
  readonly type: ActivityType;

  /** When the activity occurred (ISO 8601). */
  readonly timestamp: string;

  // ─── Canonical M1/M2 Lineage ────────────────────────────

  /** Canonical execution identity (M1). */
  readonly executionId?: ExecutionId;

  /** Distributed trace identifier (M1). */
  readonly traceId?: TraceId;

  /** Transport/request identity (M1). */
  readonly requestId?: RequestId;

  /** Workflow run identity (M8). */
  readonly workflowRunId?: WorkflowRunId;

  /** Workflow task identity (M8). */
  readonly taskId?: WorkflowTaskId;

  /** Agent assignment identity. */
  readonly agentAssignmentId?: string;

  /** Repository binding identity (M5). */
  readonly repositoryBindingId?: RepositoryBindingId;

  /** Runtime session binding identity (M7). */
  readonly runtimeSessionBindingId?: RuntimeSessionId;

  /** AI binding identity (M4). */
  readonly aiBindingId?: BindingId;

  // ─── Actor & Source ─────────────────────────────────────

  /** Who generated this activity. */
  readonly actor: import('@vestara/types').ActivityActor;

  /** Specific identity of the actor (agent ID, user ID, etc.) */
  readonly actorId?: string;

  /** Which system produced this event. */
  readonly source: ActivitySource;

  // ─── Content ────────────────────────────────────────────

  /** Normalized payload. Provider/OpenCode-specific details are stripped. */
  readonly payload: ActivityPayload;

  /** Who can see this record. */
  readonly visibility: ActivityVisibility;
}

/**
 * Normalized payload. Structured to avoid provider/OpenCode leakage.
 */
export interface ActivityPayload {
  /** Human-readable message. */
  readonly message?: string;

  /** Activity-specific structured data. */
  readonly data?: Readonly<Record<string, unknown>>;

  /** Error details (for failed activities). */
  readonly error?: {
    readonly message: string;
    readonly code?: string;
  };

  /** Output details (for completed activities). */
  readonly output?: string;

  /** Task dependency condition (for task.runnable). */
  readonly dependencyCondition?: 'completed' | 'any';
}

// ─── Activity Event (Input) ────────────────────────────────

/**
 * Canonical event that arrives at the Activity Store.
 * Can come from M8 WorkflowEvents, human messages, agent lifecycle, etc.
 * The store normalizes these into durable ActivityRecords.
 */
export interface ActivityEvent {
  /** Canonical event identity for deduplication. */
  readonly eventId: string;

  /** Activity type. */
  readonly type: ActivityType;

  /** When the event occurred. */
  readonly timestamp: string;

  // ─── Lineage (same fields as ActivityRecord) ────────────

  readonly executionId?: ExecutionId;
  readonly traceId?: TraceId;
  readonly requestId?: RequestId;
  readonly workflowRunId?: WorkflowRunId;
  readonly taskId?: WorkflowTaskId;
  readonly agentAssignmentId?: string;
  readonly repositoryBindingId?: RepositoryBindingId;
  readonly runtimeSessionBindingId?: RuntimeSessionId;
  readonly aiBindingId?: BindingId;

  // ─── Actor & Source ─────────────────────────────────────

  readonly actor: import('@vestara/types').ActivityActor;
  readonly actorId?: string;
  readonly source: ActivitySource;

  // ─── Content ────────────────────────────────────────────

  readonly payload: ActivityPayload;
  readonly visibility?: ActivityVisibility;
}

// ─── Query Surface ──────────────────────────────────────────

/**
 * Cursor for pagination and replay.
 * Event identity + sequence number, not timestamp alone.
 */
export interface ActivityCursor {
  /** Sequence number for cursor-based pagination. */
  readonly sequenceNumber: number;

  /** Event identity for deduplication verification. */
  readonly eventId: string;

  /** Timestamp for time-based filtering. */
  readonly timestamp: string;
}

/**
 * M9 Query filters for the Activity Store.
 * Supports M10/M11 data requirements without overbuilding.
 *
 * Note: This is the M9 query interface. The canonical ActivityQuery
 * (workflowId, sessionId, taskId, agentId, kind, severity, ...)
 * lives in store.ts and works with the 6-kind discriminated union.
 */
export interface M9ActivityQuery {
  /** Filter by workflow run. */
  readonly workflowRunId?: WorkflowRunId;

  /** Filter by execution identity. */
  readonly executionId?: ExecutionId;

  /** Filter by task identity. */
  readonly taskId?: WorkflowTaskId;

  /** Filter by actor type. */
  readonly actor?: import('@vestara/types').ActivityActorType;

  /** Filter by actor identity. */
  readonly actorId?: string;

  /** Filter by activity type. */
  readonly type?: ActivityType | ActivityType[];

  /** Filter by source system. */
  readonly source?: ActivitySource;

  /** Only records after this cursor (exclusive). */
  readonly after?: ActivityCursor;

  /** Only records before this timestamp. */
  readonly before?: string;

  /** Only records after this timestamp. */
  readonly afterTimestamp?: string;

  /** Maximum number of results. */
  readonly limit?: number;
}

// ─── Store Interface ────────────────────────────────────────

/**
 * M9 Durable Activity Store interface.
 * Idempotent ingestion: same eventId → exactly one ActivityRecord.
 * Deterministic ordering via sequenceNumber.
 *
 * Note: This is the M9 ingestion-oriented store. The canonical ActivityStore
 * (append/get/list/lastSequence) lives in store.ts and works with the
 * 6-kind discriminated union ActivityRecord.
 */
export interface M9ActivityStore {
  /**
   * Append a canonical event. Idempotent: same eventId returns existing record.
   * Returns the durable ActivityRecord with assigned sequenceNumber.
   */
  append(event: ActivityEvent): Promise<ActivityRecord>;

  /**
   * Query activities with filters. Returns results in deterministic order.
   */
  query(q: M9ActivityQuery): Promise<readonly ActivityRecord[]>;

  /**
   * Get activities after a cursor (exclusive). For pagination/replay.
   */
  getAfter(cursor: ActivityCursor): Promise<readonly ActivityRecord[]>;

  /**
   * Get a single record by event ID. For deduplication verification.
   */
  getByEventId(eventId: string): Promise<ActivityRecord | undefined>;

  /**
   * Replay a range of records. For rebuild/verification.
   */
  replay(from?: ActivityCursor, to?: ActivityCursor): Promise<readonly ActivityRecord[]>;

  /**
   * Rebuild projection from all durable facts. Returns all records in order.
   */
  rebuild(): Promise<readonly ActivityRecord[]>;

  /**
   * Get current cursor (last appended record). For reconnect/resume.
   */
  getCursor(): Promise<ActivityCursor | null>;

  /**
   * Get the last sequence number. For polling/recovery.
   */
  lastSequence(): Promise<number>;
}

/**
 * M9 → Projection Record Conversion
 *
 * Converts M9 ActivityRecords to the discriminated-union ActivityRecord
 * format used by the ActivityStreamHub and M11A/M11B projection layers.
 *
 * Extracted from apps/api/src/routes/activity-room-m11a.ts and
 * apps/api/src/routes/activity-room-m11b.ts to eliminate duplication.
 *
 * Architecture Traceability:
 *   ARX-015: M11A/M11B projection composition
 */

import type { ActivityRecord } from './contracts';
import type { ActivityRecord as M9ActivityRecord } from './m9-types';

/**
 * Map M9 activity types to projection ActivityRecord kinds.
 */
const KIND_MAP: Record<string, ActivityRecord['kind']> = {
  'workflow.started': 'workflow',
  'workflow.completed': 'workflow',
  'workflow.failed': 'workflow',
  'workflow.cancelled': 'workflow',
  'task.runnable': 'task',
  'task.started': 'task',
  'task.completed': 'task',
  'task.failed': 'task',
  'task.cancelled': 'task',
  'agent.assigned': 'agent-message',
  'agent.started': 'agent-message',
  'agent.progress': 'agent-message',
  'agent.waiting': 'agent-message',
  'agent.completed': 'agent-message',
  'agent.failed': 'agent-message',
  'agent.cancelled': 'agent-message',
  'tool.called': 'tool-call',
  'tool.succeeded': 'tool-result',
  'tool.failed': 'tool-result',
  'human.message': 'agent-message',
  'system.event': 'workflow',
  'interaction.presented': 'agent-message',
  'interaction.responded': 'agent-message',
};

/**
 * Convert an M9 ActivityRecord to the projection ActivityRecord format
 * used by the ActivityStreamHub for broadcasting.
 *
 * This is a lossy conversion — M9 records carry richer metadata than the
 * discriminated union projection format. The conversion preserves the
 * essential fields needed for UI rendering.
 */
export function toProjectionRecord(record: M9ActivityRecord): ActivityRecord {
  const kind = KIND_MAP[record.type] ?? 'workflow';
  const actor = {
    type: record.actor.type,
    id: record.actor.id,
    displayName: record.actor.displayName,
    ...(record.actorId ? { role: record.actorId } : {}),
  };
  const agentId = record.actor.type === 'agent' ? record.actor.id : '';
  const data = record.payload?.data as Record<string, unknown> | undefined;
  const callID = (data?.callID as string) ?? '';
  const toolName = (data?.toolName as string) ?? '';

  // Tool activities have a distinct shape from agent-message
  if (kind === 'tool-call') {
    return {
      id: String(record.activityId),
      sequence: record.sequenceNumber,
      timestamp: record.timestamp,
      actor,
      kind: 'tool-call',
      agentId,
      toolName,
      callID,
      evidenceRefs: [],
    };
  }
  if (kind === 'tool-result') {
    return {
      id: String(record.activityId),
      sequence: record.sequenceNumber,
      timestamp: record.timestamp,
      actor,
      kind: 'tool-result',
      agentId,
      toolName,
      callID,
      status: record.type === 'tool.failed' ? 'failed' : 'completed',
      evidenceRefs: [],
    };
  }

  return {
    id: String(record.activityId),
    sequence: record.sequenceNumber,
    timestamp: record.timestamp,
    actor,
    kind,
    agentId,
    messageKind: 'message',
    content: record.payload?.message ?? '',
    workflowId: record.workflowRunId,
    sessionId: undefined,
    evidenceRefs: [],
    ...(record.payload?.error ? { effect: 'intervention' as const } : {}),
    ...(record.payload?.output ? { output: record.payload.output } : {}),
  } as ActivityRecord;
}

