    eventId,
    type: 'human.message',
    timestamp: now,
    executionId: input.executionId,
    traceId: input.traceId,
    workflowRunId: input.workflowRunId,
    taskId: input.taskId,
    repositoryBindingId: input.repositoryBindingId,
    runtimeSessionBindingId: input.runtimeSessionBindingId,
