display.text:
// OpenCodeEventBridge — a single persistent SSE subscription to the OpenCode
// headless server. Raw events are normalized (see event-types.ts) and published
// onto the EventBus as `opencode.*` envelopes. The bridge owns one upstream
// connection, coalesces high-frequency `message.part.delta` frames, and
// reconnects with bounded exponential backoff. Delivery to workspace clients
// (WebSocket/SSE) happens through EventBus subscribers.

import type { EventBus } from '@vestara/event-bus';
import type { OpenCodeClient } from '../client/opencode-client';
import type { OpenCodeRequestContext } from '../client/opencode-types';
import type { OpenCodePermissionRequest } from '../permissions/permission-types';
import { normalizePermissionRequest } from '../permissions/permission-types';
import type { OpenCodeBridgeConnectionState } from './event-types';
import { normalizeOpenCodeEvent } from './event-types';

export interface OpenCodeEventBridgeOptions {
  readonly client: OpenCodeClient;
  readonly eventBus: EventBus;
  readonly context: OpenCodeRequestContext;
  readonly reconnectDelayMs?: number;
  readonly maxReconnectDelayMs?: number;
  readonly onConnectionState?: (state: OpenCodeBridgeConnectionState) => void;
  readonly onPermissionRequest?: (request: OpenCodePermissionRequest) => void;
  readonly logger?: { warn?: (message: string, meta?: unknown) => void };
}

export interface OpenCodeEventBridgeMetrics {
  readonly connected: boolean;
  readonly connectionState: OpenCodeBridgeConnectionState;
  readonly receivedEvents: number;
  readonly publishedEvents: number;
  readonly droppedDeltas: number;
  readonly reconnectAttempts: number;
  readonly lastEventAt?: string;
}

interface DeltaSlot {
  readonly sessionId?: string;
  readonly messageId?: string;
  readonly partId?: string;
  text: string;
  lastActivity: number;
}

const DELTA_QUIET_MS = 80;

export class OpenCodeEventBridge {
  private readonly client: OpenCodeClient;
  private readonly eventBus: EventBus;
  private readonly context: OpenCodeRequestContext;
  private readonly options: OpenCodeEventBridgeOptions;
  private readonly reconnectBaseMs: number;
  private readonly maxReconnectMs: number;

  private controller?: AbortController;
  private running = false;
  private stopping = false;
  private connectionState: OpenCodeBridgeConnectionState = 'disconnected';
  private reconnectAttempts = 0;
  private receivedEvents = 0;
  private publishedEvents = 0;
  private droppedDeltas = 0;
  private lastEventAt?: string;
  private reconnectTimer?: ReturnType<typeof setTimeout>;
  private flushTimer?: ReturnType<typeof setTimeout>;
  private readonly deltas = new Map<string, DeltaSlot>();

  constructor(options: OpenCodeEventBridgeOptions) {
    this.options = options;
    this.client = options.client;
    this.eventBus = options.eventBus;
    this.context = options.context;
    this.reconnectBaseMs = options.reconnectDelayMs ?? 250;
    this.maxReconnectMs = options.maxReconnectDelayMs ?? 10_000;
  }

  get connected(): boolean {
    return this.connectionState === 'connected';
  }

  get metrics(): OpenCodeEventBridgeMetrics {
    return {
      connected: this.connected,
      connectionState: this.connectionState,
      receivedEvents: this.receivedEvents,
      publishedEvents: this.publishedEvents,
      droppedDeltas: this.droppedDeltas,
      reconnectAttempts: this.reconnectAttempts,
      lastEventAt: this.lastEventAt,
    };
  }

  async start(): Promise<void> {
    if (this.running) return;
    this.running = true;
    this.stopping = false;
    this.setConnectionState('connecting');
    this.controller = new AbortController();
    void this.consumeLoop(this.controller.signal);
  }

  async stop(): Promise<void> {
    this.stopping = true;
    this.controller?.abort();
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
    if (this.flushTimer) clearTimeout(this.flushTimer);
    this.deltas.clear();
    this.setConnectionState('disconnected');
    this.running = false;
  }

  private setConnectionState(state: OpenCodeBridgeConnectionState): void {
    this.connectionState = state;
    this.options.onConnectionState?.(state);
  }

  private async consumeLoop(signal: AbortSignal): Promise<void> {
    while (this.running && !this.stopping && !signal.aborted) {
      this.setConnectionState(this.reconnectAttempts > 0 ? 'reconnecting' : 'connecting');
      try {
        const stream = this.client.openEventStream(this.context, signal);
        let sawEvent = false;
        for await (const raw of stream) {
          if (this.stopping || signal.aborted) break;
          if (!sawEvent) {
            sawEvent = true;
            this.reconnectAttempts = 0;
            this.setConnectionState('connected');
          }
          this.receivedEvents += 1;
          this.lastEventAt = new Date().toISOString();
          const normalized = normalizeOpenCodeEvent(raw);
          if (!normalized) continue;
          if (normalized.type === 'permission.asked' || normalized.type === 'permission.v2.asked') {
            const request = normalizePermissionRequest(normalized.payload);
            if (request) this.options.onPermissionRequest?.(request);
          }
          if (normalized.type === 'message.part.delta' && normalized.delta) {
            this.bufferDelta(normalized);
            continue;
          }
          this.flushDeltas();
          await this.publish(normalized);
        }
        // Stream ended (or aborted). If stopping, exit cleanly.
        if (this.stopping || signal.aborted) break;
        this.flushDeltas();
        this.scheduleReconnect();
        return;
      } catch (error) {
        this.options.logger?.warn?.('opencode event stream error', { error: String(error) });
        if (this.stopping || signal.aborted) break;
        this.flushDeltas();
        this.scheduleReconnect();
        return;
      }
    }
  }

  private bufferDelta(normalized: ReturnType<typeof normalizeOpenCodeEvent>): void {
    if (!normalized) return;
    const key = `${normalized.sessionId ?? '-'}|${normalized.messageId ?? '-'}|${normalized.partId ?? '-'}`;
    const existing = this.deltas.get(key);
    const now = Date.now();
    if (existing) {
      existing.text += normalized.delta ?? '';
      existing.lastActivity = now;
    } else {
      this.deltas.set(key, {
        sessionId: normalized.sessionId,
        messageId: normalized.messageId,
        partId: normalized.partId,
        text: normalized.delta ?? '',
        lastActivity: now,
      });
    }
    if (!this.flushTimer) {
      this.flushTimer = setTimeout(() => {
        this.flushTimer = undefined;
        this.flushDeltas();
      }, DELTA_QUIET_MS);
    }
  }

  private flushDeltas(): void {
    if (this.flushTimer) {
      clearTimeout(this.flushTimer);
      this.flushTimer = undefined;
    }
    if (this.deltas.size === 0) return;
    const snapshot = [...this.deltas.values()];
    this.deltas.clear();
    for (const slot of snapshot) {
      if (slot.text.length === 0) continue;
      void this.publish({
        upstreamId: `delta-${slot.lastActivity}`,
        type: 'message.part.delta',
        category: 'message',
        sessionId: slot.sessionId,
        messageId: slot.messageId,
        partId: slot.partId,
        delta: slot.text,
        timestamp: new Date(slot.lastActivity).toISOString(),
        payload: { messageID: slot.messageId, partID: slot.partId, field: 'text', delta: slot.text },
      });
    }
  }

  private async publish(event: ReturnType<typeof normalizeOpenCodeEvent>): Promise<void> {
    if (!event) return;
    try {
      await this.eventBus.emit({
        type: `opencode.${event.type}`,
        version: 1,
        source: 'opencode-event-bridge',
        payload: event as unknown as Record<string, unknown>,
        // ARX-015 M2: sessionId is not an execution identity. OpenCode session events
        // without an explicit execution context remain uncorrelated (fail-closed).
        metadata: {},
      });
      this.publishedEvents += 1;
    } catch {
      this.droppedDeltas += 1;
    }
  }

  private scheduleReconnect(): void {
    if (this.stopping) return;
    this.reconnectAttempts += 1;
    const delay = Math.min(this.reconnectBaseMs * 2 ** Math.min(this.reconnectAttempts - 1, 8), this.maxReconnectMs);
    this.setConnectionState('reconnecting');
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = undefined;
      if (this.stopping) return;
      this.controller = new AbortController();
      void this.consumeLoop(this.controller.signal);
    }, delay);
  }
}

/**
 * RuntimeSessionRegistry — Session Continuity Authority
 *
 * The registry is the single mechanism for acquiring and managing physical
 * runtime sessions. It enforces:
 *
 * - Idempotent acquisition: repeated getOrCreate() for the same WorkflowRun
 *   converges on the same binding.
 * - Single-flight concurrency: concurrent acquisition is serialized.
 * - Policy enforcement: maxPhysicalSessions limits physical session count.
 * - Repository authority: directory must match RepositoryBinding.canonicalPath.
 * - Creation reason tracking: every binding records why it was created.
 *
 * Architecture invariant:
 *   Workflow owns session continuity
 *   RuntimeSessionRegistry owns physical acquisition
 *   OpenCode owns execution inside the acquired session
 *   Agent assignments consume the session
 *
 * NOT:
 *   each agent owns an OpenCode session
 */

import type {
  ContinuityPolicy,
  MaxPhysicalSessions,
  RuntimeSessionAcquisitionInput,
  RuntimeSessionAcquisitionResult,
  RuntimeSessionBinding,
  RuntimeSessionId,
  WorkflowRunId,
} from './runtime-session-types';

// ─── Interface ──────────────────────────────────────────────

export interface RuntimeSessionRegistry {
  /**
   * Acquire a runtime session binding for a workflow run.
   * Idempotent: returns existing binding if one exists for this workflowRunId.
   * Single-flight: concurrent calls for the same workflowRunId are serialized.
   * Enforces maxPhysicalSessions policy.
   */
  acquire(input: RuntimeSessionAcquisitionInput): Promise<RuntimeSessionAcquisitionResult>;

  /**
   * Get an existing binding by workflow run ID.
   * Returns undefined if no binding exists.
   */
  getByWorkflowRun(workflowRunId: WorkflowRunId): RuntimeSessionBinding | undefined;

  /**
   * Get an existing binding by runtime session ID.
   * Returns undefined if no binding exists.
   */
  getByRuntimeSessionId(runtimeSessionId: RuntimeSessionId): RuntimeSessionBinding | undefined;

  /**
   * Get an existing binding by physical (OpenCode) session ID.
   * Returns undefined if no binding exists.
   */
  getByPhysicalSessionId(physicalSessionId: string): RuntimeSessionBinding | undefined;

  /**
   * Update the physical session ID after OpenCode session creation.
   * Called after the OpenCode createSession() call succeeds.
   */
  setPhysicalSessionId(runtimeSessionId: RuntimeSessionId, physicalSessionId: string): void;

  /**
   * Update the lifecycle state of a binding.
   */
  updateLifecycle(
    runtimeSessionId: RuntimeSessionId,
    lifecycle: RuntimeSessionBinding['lifecycle'],
    error?: string,
  ): void;

  /**
   * List all bindings (for debugging/audit).
   */
  list(): RuntimeSessionBinding[];

  /**
   * Count active bindings.
   */
  count(): number;
}

// ─── In-Memory Implementation ───────────────────────────────

let nextRuntimeSessionCounter = 0;

function generateRuntimeSessionId(): RuntimeSessionId {
  return `rt-${Date.now()}-${++nextRuntimeSessionCounter}` as RuntimeSessionId;
}

/**
 * Default policy settings.
 */
export const DEFAULT_CONTINUITY_POLICY: ContinuityPolicy = 'SHARED_WORKFLOW';
export const DEFAULT_MAX_PHYSICAL_SESSIONS: MaxPhysicalSessions = 1;

/**
 * Validate that the directory matches the repository binding's canonical path.
 * This enforces M5's invariant: OpenCode server CWD must never become
 * repository authority.
 */
function _validateDirectory(directory: string, expectedCanonicalPath: string): void {
  if (directory !== expectedCanonicalPath) {
    throw new Error(
      `M7 INVARIANT VIOLATION: Session directory "${directory}" does not match ` +
        `RepositoryBinding.canonicalPath "${expectedCanonicalPath}". ` +
        `The OpenCode server CWD must never become repository authority.`,
    );
  }
}

/**
 * Resolve policy defaults.
 */
function resolvePolicy(input: { continuityPolicy?: ContinuityPolicy; maxPhysicalSessions?: MaxPhysicalSessions }): {
  policy: ContinuityPolicy;
  maxSessions: MaxPhysicalSessions;
} {
  const policy = input.continuityPolicy ?? DEFAULT_CONTINUITY_POLICY;
  const maxSessions = input.maxPhysicalSessions ?? DEFAULT_MAX_PHYSICAL_SESSIONS;
  return { policy, maxSessions };
}

/**
 * In-memory implementation of RuntimeSessionRegistry.
 * Suitable for single-process use. For production persistence, implement
 * the RuntimeSessionRegistry interface with SQLite backing.
 */
export class InMemoryRuntimeSessionRegistry implements RuntimeSessionRegistry {
  /** bindings indexed by workflowRunId (one binding per workflow run). */
  private readonly byWorkflowRun = new Map<string, RuntimeSessionBinding>();

  /** bindings indexed by runtimeSessionId. */
  private readonly byRuntimeSessionId = new Map<string, RuntimeSessionBinding>();

  /** bindings indexed by physicalSessionId. */
  private readonly byPhysicalSessionId = new Map<string, RuntimeSessionBinding>();

  /** Single-flight locks per workflowRunId (promise that resolves when lock is released). */
  private readonly locks = new Map<string, Promise<void>>();

  async acquire(input: RuntimeSessionAcquisitionInput): Promise<RuntimeSessionAcquisitionResult> {
    const lockKey = input.workflowRunId;

    // Single-flight: serialize concurrent acquisition for the same workflowRunId.
    // Use a promise chain so that if a lock is held, callers wait for it.
    const existingLock = this.locks.get(lockKey);
    const resultPromise = existingLock
      ? existingLock.then(() => this.doAcquire(input))
      : this.doAcquireWithLock(lockKey, input);
    return resultPromise;
  }

  private async doAcquireWithLock(
    lockKey: string,
    input: RuntimeSessionAcquisitionInput,
  ): Promise<RuntimeSessionAcquisitionResult> {
    // Create a promise that downstream callers can wait on
    let resolveLock!: () => void;
    const lockPromise = new Promise<void>((resolve) => {
      resolveLock = resolve;
    });
    this.locks.set(lockKey, lockPromise);

    try {
      return await this.doAcquire(input);
    } finally {
      resolveLock();
      this.locks.delete(lockKey);
    }
  }

  private async doAcquire(input: RuntimeSessionAcquisitionInput): Promise<RuntimeSessionAcquisitionResult> {
    // Idempotent: return existing binding if one exists.
    const existing = this.byWorkflowRun.get(input.workflowRunId);
    if (existing) {
      return {
        binding: existing,
        created: false,
        acquired: existing.physicalSessionId !== null,
      };
    }

    // Resolve policy
    const { policy, maxSessions } = resolvePolicy({
      continuityPolicy: input.continuityPolicy,
    });

    // Enforce maxPhysicalSessions per workflow run.
    // Under SHARED_WORKFLOW, each workflow run gets exactly 1 binding
    // (enforced by idempotent check above). The maxSessions check
    // guards against policy violations where a workflow somehow
    // acquires more than the allowed number of bindings.
    const existingBindingsForRun = this.byWorkflowRun.has(input.workflowRunId);
    if (existingBindingsForRun) {
      throw new Error(
        `M7 POLICY VIOLATION: Binding already exists for workflow ${input.workflowRunId}. ` +
          `maxPhysicalSessions (${maxSessions}) under ${policy} policy.`,
      );
    }

    // Create new binding
    const now = new Date().toISOString();
    const runtimeSessionId = generateRuntimeSessionId();

    const binding: RuntimeSessionBinding = {
      runtimeSessionId,
      workflowRunId: input.workflowRunId,
      physicalSessionId: null, // Not yet acquired
      repositoryBindingId: input.repositoryBindingId,
      continuityPolicy: policy,
      maxPhysicalSessions: maxSessions,
      creationReason: input.creationReason,
      lifecycle: 'acquiring',
      workspaceId: input.workspaceId,
      directory: input.directory,
      createdAt: now,
      updatedAt: now,
    };

    this.byWorkflowRun.set(input.workflowRunId, binding);
    this.byRuntimeSessionId.set(runtimeSessionId, binding);

    return {
      binding,
      created: true,
      acquired: false,
    };
  }

  getByWorkflowRun(workflowRunId: WorkflowRunId): RuntimeSessionBinding | undefined {
    return this.byWorkflowRun.get(workflowRunId);
  }

  getByRuntimeSessionId(runtimeSessionId: RuntimeSessionId): RuntimeSessionBinding | undefined {
    return this.byRuntimeSessionId.get(runtimeSessionId);
  }

  getByPhysicalSessionId(physicalSessionId: string): RuntimeSessionBinding | undefined {
    return this.byPhysicalSessionId.get(physicalSessionId);
  }

  setPhysicalSessionId(runtimeSessionId: RuntimeSessionId, physicalSessionId: string): void {
    const binding = this.byRuntimeSessionId.get(runtimeSessionId);
    if (!binding) return;

    // Remove old physical session mapping
    if (binding.physicalSessionId) {
      this.byPhysicalSessionId.delete(binding.physicalSessionId);
    }

    // Update binding
    const updated: RuntimeSessionBinding = {
      ...binding,
      physicalSessionId,
      lifecycle: 'active',
      updatedAt: new Date().toISOString(),
    };

    this.byRuntimeSessionId.set(runtimeSessionId, updated);
    this.byWorkflowRun.set(binding.workflowRunId, updated);
    this.byPhysicalSessionId.set(physicalSessionId, updated);
  }

  updateLifecycle(
    runtimeSessionId: RuntimeSessionId,
    lifecycle: RuntimeSessionBinding['lifecycle'],
    error?: string,
  ): void {
    const binding = this.byRuntimeSessionId.get(runtimeSessionId);
    if (!binding) return;

    const updated: RuntimeSessionBinding = {
      ...binding,
      lifecycle,
      error,
      updatedAt: new Date().toISOString(),
    };

    this.byRuntimeSessionId.set(runtimeSessionId, updated);
    this.byWorkflowRun.set(binding.workflowRunId, updated);
    if (binding.physicalSessionId) {
      this.byPhysicalSessionId.set(binding.physicalSessionId, updated);
    }
  }

  list(): RuntimeSessionBinding[] {
    return [...this.byWorkflowRun.values()];
  }

  count(): number {
    return this.byWorkflowRun.size;
  }
}

/**
 * GA-RUNTIME-001 — Assistant Execution Binding Resolver
 *
 * Server-authoritative provider/model resolution for the Global Assistant.
 * The browser's ProviderModelSelector value is a REQUESTED binding, never
 * authority: the server validates provider existence, model existence and
 * provider/model compatibility against the canonical OpenCode runtime provider
 * discovery before any execution happens.
 *
 *   ProviderModelSelector (browser)
 *        ↓ requested provider/model
 *   server validation/resolution  ← this resolver
 *        ↓
 *   Execution Binding { providerID, modelID }
 *        ↓
 *   OpenCode turn (prompt_async model field)
 *
 * If the requested binding cannot be resolved, a deterministic
 * `AssistantBindingError` is thrown (never silent fallback to a previous or
 * default model while displaying the requested one).
 *
 * Discovery results are cached briefly (matching the runtime provider surface
 * the UI is offered), so validation is cheap and consistent per turn.
 */

import type { OpenCodeHttpClient } from '@vestara/opencode-runtime';

export interface AssistantExecutionBinding {
  readonly providerID: string;
  readonly modelID: string;
}

export type AssistantBindingErrorCode = 'provider-not-found' | 'model-not-found' | 'runtime-unavailable';

export class AssistantBindingError extends Error {
  readonly code: AssistantBindingErrorCode;
  readonly providerId?: string;
  readonly modelId?: string;

  constructor(code: AssistantBindingErrorCode, message: string, details?: { providerId?: string; modelId?: string }) {
    super(message);
    this.name = 'AssistantBindingError';
    this.code = code;
    this.providerId = details?.providerId;
    this.modelId = details?.modelId;
  }
}

export interface AssistantBindingRequest {
  readonly providerId?: string;
  readonly modelId?: string;
}

export interface AssistantBindingResolver {
  /**
   * Resolve a requested provider/model to an execution binding.
   * With no request (or an incomplete request) the configured fallback
   * binding is returned. Throws `AssistantBindingError` when a requested
   * binding cannot be resolved deterministically.
   */
  resolve(request?: AssistantBindingRequest): Promise<AssistantExecutionBinding>;
}

const DISCOVERY_CACHE_MS = 30_000;

/**
 * Build the canonical resolver over the local OpenCode runtime client.
 *
 * @param client   the shared OpenCodeHttpClient (127.0.0.1:4096).
 * @param fallback the agent-assistant default binding used when the caller
 *                 requests no provider/model (e.g. activity-room / CLI turns).
 */
export function createAssistantBindingResolver(
  client: OpenCodeHttpClient,
  fallback: AssistantExecutionBinding | undefined,
): AssistantBindingResolver {
  let cache: { providers: ReadonlyArray<{ id: string; models?: readonly string[] }>; at: number } | undefined;

  async function discover(): Promise<ReadonlyArray<{ id: string; models?: readonly string[] }>> {
    if (cache && Date.now() - cache.at < DISCOVERY_CACHE_MS) return cache.providers;
    let providers: ReadonlyArray<{ id: string; models?: readonly string[] }>;
    try {
      providers = await client.listProviders();
    } catch (error) {
      throw new AssistantBindingError(
        'runtime-unavailable',
        `Cannot validate the requested provider/model — the OpenCode runtime is unavailable (${error instanceof Error ? error.message : 'unknown'})`,
      );
    }
    cache = { providers, at: Date.now() };
    return providers;
  }

  return {
    async resolve(request?: AssistantBindingRequest): Promise<AssistantExecutionBinding> {
      const providerId = request?.providerId?.trim();
      const modelId = request?.modelId?.trim();

      // No explicit request → the configured default binding governs.
      if (!providerId || !modelId) {
        if (fallback) return fallback;
        throw new AssistantBindingError(
          'provider-not-found',
          'No provider/model was requested and no default Assistant binding is configured',
        );
      }

      const providers = await discover();
      const provider = providers.find((candidate) => candidate.id === providerId);
      if (!provider) {
        throw new AssistantBindingError('provider-not-found', `Provider not found: ${providerId}`, { providerId });
      }
      const known = provider.models?.includes(modelId);
      if (!known) {
        throw new AssistantBindingError('model-not-found', `Model not found for provider ${providerId}: ${modelId}`, {
          providerId,
          modelId,
        });
      }
      return { providerID: provider.id, modelID: modelId };
    },
  };
}

